as "$COM_TOKEN" GET "procurement/suppliers?contains=%D8%A7%D9%84%D9%81"; check "supplier list shows grade and on-time delivery" '.success and .data[0].grade == 1 and .data[0].receiptLines == 1'

# R1a2 (M8): the bank accounts of a provider (number, SHABA, card) are for purchasing, finance and treasury; everybody else reads them masked to the last four characters
as "$ADMIN_TOKEN" POST Provider/add-account "{\"providerId\":$PA,\"name\":\"حساب جاری آزمون\",\"bank\":\"ملی\",\"no\":\"1234567890123\",\"shaba\":\"IR970170000000100324200002\",\"card\":\"6037991234567890\"}"
check "r1a2 m8: setup: a bank account is added to the supplier" '.success'
M8FULL='.success and ([.data.providerAccounts[]|select(.no == "1234567890123" and .shaba == "IR970170000000100324200002" and .card == "6037991234567890")]|length) == 1'
M8MASK='.success and ([.data.providerAccounts[]|select(.no == "****0123" and .shaba == "****0002" and .card == "****7890")]|length) == 1 and (tostring|contains("1234567890123")|not) and (tostring|contains("IR970170000000100324200002")|not) and (tostring|contains("6037991234567890")|not)'
for M8T in ADMIN_TOKEN COM_TOKEN FIN_TOKEN FM_TOKEN TR_TOKEN; do as "${!M8T}" GET "Provider/providers?Id=$PA"; check "r1a2 m8: ${M8T%_TOKEN} reads the full bank account of the supplier" "$M8FULL"; done
for M8T in WH_TOKEN QC_TOKEN ENG_TOKEN PLAN_TOKEN; do as "${!M8T}" GET "Provider/providers?Id=$PA"; check "r1a2 m8: ${M8T%_TOKEN} reads the supplier with the account masked to the last four characters" "$M8MASK"; done
as "$WH_TOKEN" GET "Provider?PageSize=50"; check "r1a2 m8: in the list of providers the storekeeper sees the account masked as well, and the rest of the record is there" '.success and ([.data.data[]|select(.name == "تامین‌کننده الف آزمون")]|length) == 1 and (tostring|contains("1234567890123")|not) and (tostring|contains("IR970170000000100324200002")|not)'
as "$COM_TOKEN" GET "Provider?PageSize=50"; check "r1a2 m8: while the commercial user sees it in full in the list" '.success and (tostring|contains("1234567890123"))'
as "$WH_TOKEN" GET "Provider/vendor-list"; check "r1a2 m8: the vendor list never carries a full account number either" '.success and (tostring|contains("1234567890123")|not) and (tostring|contains("6037991234567890")|not)'
# R1a2 review (L-6): the IBAN of the supplier profile (procurement/suppliers) is bank data as well: purchasing, finance and treasury read it in full, every other reader of the supplier list gets ****
# and its last four characters (the profile of the supplier was saved with this IBAN a few lines above)
L6SUP='IR970170000000100324200002'
for L6T in ADMIN_TOKEN COM_TOKEN FIN_TOKEN FM_TOKEN TR_TOKEN; do as "${!L6T}" GET "procurement/suppliers?contains=%D8%A7%D9%84%D9%81"; check "r1a2 review l-6: ${L6T%_TOKEN} reads the IBAN of the supplier profile in full" ".success and ([.data[]|select(.providerId == $PA and .iban == \"$L6SUP\")]|length) == 1"; done
for L6T in WH_TOKEN QC_TOKEN ENG_TOKEN PLAN_TOKEN CEO_TOKEN; do as "${!L6T}" GET "procurement/suppliers?contains=%D8%A7%D9%84%D9%81"; check "r1a2 review l-6: ${L6T%_TOKEN} reads the supplier profile with the IBAN masked to the last four characters, and the full IBAN is nowhere in the answer" ".success and ([.data[]|select(.providerId == $PA and .iban == \"****0002\")]|length) == 1 and (tostring|contains(\"$L6SUP\")|not)"; done

as "$CEO_TOKEN" GET finance/ceo-dashboard; check "CEO dashboard: stock value, payables and projects" '.success and .data.stockValue > 0 and .data.payablesOpen == 0 and .data.receivedNotInvoiced > 0 and .data.openPurchaseOrders == 1'
as "$WH_TOKEN" GET finance/ceo-dashboard; [ "$CODE" = "403" ] && ok "storekeeper cannot open the CEO dashboard (403)" || bad "storekeeper cannot open the CEO dashboard (403) got $CODE"

# R1q D11: the quality gates of an item (incoming inspection, required certificate, shelf life) are changed by QC, QA or PMO only; reducing a control needs a reason, and with an
# approved purchase order of the item still open (the bolt's order is 60 of 100 received) also the second approval of the QA manager. The storekeepers keep every other field.
BOLTBODY="\"id\":$BOLT,\"code\":\"$C_BOLT\",\"title\":\"پیچ M24\",\"unit\":\"عدد\",\"trackingMode\":0,\"minStock\":500"
as "$WH_TOKEN" POST inventory/items "{$BOLTBODY,\"requiresIncomingInspection\":true}"; nomsg "r1q D11: a storekeeper cannot change the incoming inspection of an item through the item form" "را فقط QC یا QA تغییر می‌دهد"
as "$WH_TOKEN" POST inventory/items/quality "{\"itemId\":$BOLT,\"requiresIncomingInspection\":true}"; [ "$CODE" = "403" ] && ok "r1q D11: ... nor through the quality endpoint (403)" || bad "r1q D11: ... nor through the quality endpoint (403) got $CODE"
as "$WH_TOKEN" POST inventory/items "{$BOLTBODY,\"requiresIncomingInspection\":false,\"specification\":\"M24 x 90, grade 8.8\"}"; check "r1q D11: with the quality fields as they are, the storekeeper still edits the other fields of the item" '.success and .data.specification == "M24 x 90, grade 8.8" and .data.requiresIncomingInspection == false'
as "$QC_TOKEN" POST inventory/items/quality "{\"itemId\":$BOLT,\"requiresIncomingInspection\":true,\"requiredCertificateType\":2,\"shelfLifeDays\":365}"; check "r1q D11: QC raises the gates of the bolt (inspection on, EN 10204 3.1, one year of shelf life): a stricter control needs neither a reason nor a second approval" '.success and .data.requiresIncomingInspection == true and .data.requiredCertificateType == 2 and .data.shelfLifeDays == 365'
as "$QC_TOKEN" POST inventory/items/quality "{\"itemId\":$BOLT,\"requiresIncomingInspection\":true,\"requiredCertificateType\":2,\"shelfLifeDays\":365}"; nomsg "r1q D11: sending the same values again is refused as no change" "مقدار جدیدی"
as "$QC_TOKEN" POST inventory/items/quality "{\"itemId\":$BOLT,\"requiresIncomingInspection\":false}"; nomsg "r1q D11: taking the inspection, the certificate and the shelf life off needs the reason" "دلیل تغییر را بنویسید"
as "$QC_TOKEN" POST inventory/items/quality "{\"itemId\":$BOLT,\"requiresIncomingInspection\":false,\"reason\":\"Standard bolts of a certified supplier are checked on the line\"}"; check "r1q D11: with the reason the change waits for the second approval (the bolt has an approved purchase order that is partly received): the item keeps its gates for now" '.success and .data.requiresIncomingInspection == true and .data.requiredCertificateType == 2 and .data.shelfLifeDays == 365 and .data.pendingQualityChangeId != null'
as "$QC_TOKEN" GET "inventory/items/quality-changes?ItemId=$BOLT&Status=0"; check "r1q D11: one pending change with its reason, the requested values and the requester" '.success and (.data.data|length) == 1 and .data.data[0].requiresIncomingInspection == false and .data.data[0].requiredCertificateType == null and .data.data[0].shelfLifeDays == null and (.data.data[0].reason|startswith("Standard bolts")) and .data.data[0].currentRequiresIncomingInspection == true and (.data.data[0].requestedByName|length) > 0'
QCH=$(val '.data.data[0].id')
as "$QA_TOKEN" GET "office/inbox?SourceKey=itemquality:$QCH"; check "r1q D11: the QA manager has the second approval in the inbox" '.success and (.data.data|length) == 1 and .data.data[0].recipientRole == "QA"'
as "$QC_TOKEN" POST inventory/items/quality-changes/decide "{\"id\":$QCH,\"approve\":true}"; [ "$CODE" = "403" ] && ok "r1q D11: QC cannot give the second approval (403)" || bad "r1q D11: QC cannot give the second approval (403) got $CODE"
as "$QA_TOKEN" POST inventory/items/quality-changes/decide "{\"id\":$QCH,\"approve\":false}"; nomsg "r1q D11: a rejection needs its reason" "دلیل رد تغییر را بنویسید"
as "$QA_TOKEN" POST inventory/items/quality-changes/decide "{\"id\":$QCH,\"approve\":true,\"note\":\"Incoming checks of the supplier are on file\"}"; check "r1q D11: the QA manager approves: the decision is kept with its day and person" '.success and .data.status == 1 and .data.decidedByName != null and .data.decisionNote == "Incoming checks of the supplier are on file"'
call GET "inventory/items/$BOLT"; check "r1q D11: the bolt is back to its original gates: no inspection, no certificate, no shelf life, nothing pending" '.success and .data.requiresIncomingInspection == false and .data.requiredCertificateType == null and .data.shelfLifeDays == null and .data.pendingQualityChangeId == null'
as "$QA_TOKEN" POST inventory/items/quality-changes/decide "{\"id\":$QCH,\"approve\":true}"; nomsg "r1q D11: a decided change is not decided twice" "قبلاً تصمیم گرفته شده است"
as "$FM_TOKEN" GET "finance/audit?EntityType=InventoryItem&EntityId=$BOLT&PageSize=0"; check "r1q D11: the gate changes of the bolt are in the audit trail with the user: the raise to 365 days, and then the removal" '.success and ([.data.data[]|select(.action == "Modified" and (.userName|length) > 0 and ((.afterJson // "{}")|fromjson|.ShelfLifeDays == 365))]|length) == 1 and ([.data.data[]|select(.action == "Modified" and (.userName|length) > 0 and ((.beforeJson // "{}")|fromjson|.ShelfLifeDays == 365) and ((.afterJson // "{}")|fromjson|.RequiresIncomingInspection == false))]|length) == 1'
as "$ADMIN_TOKEN" POST inventory/items '{"code":"05001001000001","title":"ماده مصرفی آزمون گروه ۰۵","unit":"عدد","trackingMode":0,"requiresIncomingInspection":false}'; check "r1q D11: a consumable (group 05) starts without the incoming inspection and needs no reason: that is the baseline of its group" '.success and .data.requiresIncomingInspection == false'
as "$ADMIN_TOKEN" POST inventory/items '{"code":"01003011060101","title":"ورق آزمون بدون بازرسی ورودی","unit":"kg","trackingMode":1,"requiresIncomingInspection":false}'; nomsg "r1q D11: a new material that starts without the incoming inspection of its group needs the reason" "دلیل تغییر را بنویسید"

# review M8: a reduction of a quality gate ALWAYS waits for the QA manager (also when no purchase order of the item is open), only one reduction waits per item, a stricter control applies at
# once and leaves the waiting request stale (the QA manager can then only reject it), the list of requests is for PMO, QC and QA, and the answer to a decision is the decided row itself
TOKEN=$ADMIN_TOKEN
item XQ "{\"code\":\"01003011060201\",\"title\":\"ورق آزمون تغییر کنترل کیفی\",\"unit\":\"kg\",\"trackingMode\":1,\"requiresIncomingInspection\":true,\"requiredCertificateType\":2,\"shelfLifeDays\":100}" "with the inspection, EN 10204 3.1 and 100 days of shelf life (a start stricter than its group needs no approval)"
check "r1q M8: ... it starts with those gates and nothing waits" '.success and .data.requiresIncomingInspection == true and .data.requiredCertificateType == 2 and .data.shelfLifeDays == 100 and .data.pendingQualityChangeId == null'
as "$QC_TOKEN" POST inventory/items/quality "{\"itemId\":$XQ,\"requiresIncomingInspection\":true,\"requiredCertificateType\":1,\"shelfLifeDays\":100,\"reason\":\"Certificate 2.2 is enough for this plate\"}"
check "r1q M8: lowering the certificate to EN 10204 2.2 waits for the QA manager although no purchase order of the item is open: the item keeps 3.1" '.success and .data.requiredCertificateType == 2 and .data.pendingQualityChangeId != null'
XQCH=$(val .data.pendingQualityChangeId)
as "$QC_TOKEN" POST inventory/items/quality "{\"itemId\":$XQ,\"requiresIncomingInspection\":true,\"requiredCertificateType\":2,\"reason\":\"The shelf life is not needed\"}"; nomsg "r1q M8: a second reduction of the same item is refused while the first one waits (one request per item)" "در انتظار تایید QA است"
as "$QC_TOKEN" POST inventory/items/quality "{\"itemId\":$XQ,\"requiresIncomingInspection\":true,\"requiredCertificateType\":3,\"shelfLifeDays\":100}"
check "r1q M8: a stricter control (EN 10204 3.2) applies at once, with no reason and no second approval, while the reduction still waits" ".success and .data.requiredCertificateType == 3 and .data.pendingQualityChangeId == $XQCH"
as "$QC_TOKEN" GET "inventory/items/quality-changes?ItemId=$XQ&Status=0"
check "r1q M8: the waiting request shows that it is stale: it was made on 3.1, the item is on 3.2 now" ".success and (.data.data|length) == 1 and .data.data[0].id == $XQCH and .data.data[0].stale == true and .data.data[0].oldRequiredCertificateType == 2 and .data.data[0].currentRequiredCertificateType == 3 and .data.data[0].requiredCertificateType == 1"
as "$QA_TOKEN" POST inventory/items/quality-changes/decide "{\"id\":$XQCH,\"approve\":true,\"note\":\"OK\"}"; nomsg "r1q M8: the QA manager cannot approve a stale request (it would apply a picture of the item that is gone)" "تایید آن مجاز نیست"
as "$QA_TOKEN" POST inventory/items/quality-changes/decide "{\"id\":$XQCH,\"approve\":false,\"note\":\"The item changed since the request\"}"
check "r1q M8: ... the rejection works, and the answer is the decided row itself, not the newest row of the list" ".success and .data.id == $XQCH and .data.status == 2 and .data.itemCode == \"01003011060201\" and .data.decidedByName != null"
call GET "inventory/items/$XQ"; check "r1q M8: the item stays on EN 10204 3.2 and nothing waits" '.success and .data.requiredCertificateType == 3 and .data.pendingQualityChangeId == null'
as "$QC_TOKEN" GET "inventory/items/quality-changes?ItemId=$XQ"; check "r1q M8: the history of the item lists its three requests, newest first: the stricter control applied at once, the rejected reduction, the start" '.success and ([.data.data[]|.status]) == [1,2,1]'
as "$WH_TOKEN" GET "inventory/items/quality-changes"; [ "$CODE" = "403" ] && ok "r1q M8: the list of quality-gate requests is closed to the storekeeper (403)" || bad "r1q M8: the list of quality-gate requests is closed to the storekeeper (403) got $CODE"
as "$PLAN_TOKEN" GET "inventory/items/quality-changes"; [ "$CODE" = "403" ] && ok "r1q M8: ... and to the planning user (403)" || bad "r1q M8: ... and to the planning user (403) got $CODE"
as "$QC_TOKEN" POST inventory/items/quality "{\"itemId\":$XQ,\"requiresIncomingInspection\":true,\"requiredCertificateType\":2,\"shelfLifeDays\":100,\"reason\":\"3.1 is enough for this plate\"}"
check "r1q M8: once the first request is decided a new reduction (3.2 to 3.1) is accepted and waits again" '.success and .data.requiredCertificateType == 3 and .data.pendingQualityChangeId != null'
XQCH2=$(val .data.pendingQualityChangeId)
as "$QA_TOKEN" POST inventory/items/quality-changes/decide "{\"id\":$XQCH2,\"approve\":true,\"note\":\"3.1 is the contract requirement\"}"
check "r1q M8: the QA manager approves it: the answer is that row, with the values the request was made on and the values it asked for" ".success and .data.id == $XQCH2 and .data.status == 1 and .data.oldRequiredCertificateType == 3 and .data.requiredCertificateType == 2"
call GET "inventory/items/$XQ"; check "r1q M8: the item is on EN 10204 3.1 now" '.success and .data.requiredCertificateType == 2 and .data.pendingQualityChangeId == null'
call POST inventory/items '{"code":"01003011060301","title":"ورق آزمون شروع بدون بازرسی","unit":"kg","trackingMode":1,"requiresIncomingInspection":false,"qualityChangeReason":"Plates of a certified supplier are checked on the line"}'
check "r1q M8: a new material that asks to start without the incoming inspection is created with the inspection of its group; the request waits for QA" '.success and .data.requiresIncomingInspection == true and .data.pendingQualityChangeId != null'
XQ2=$(val .data.id); XQ2CH=$(val .data.pendingQualityChangeId)
as "$QA_TOKEN" POST inventory/items/quality-changes/decide "{\"id\":$XQ2CH,\"approve\":true,\"note\":\"Supplier file checked\"}"; check "r1q M8: the QA manager approves it" '.success and .data.status == 1'
call GET "inventory/items/$XQ2"; check "r1q M8: ... and the new material has no incoming inspection now" '.success and .data.requiresIncomingInspection == false and .data.pendingQualityChangeId == null'

# switching the purchase order rule on: only petty-cash purchases are received without an order
call POST procurement/settings '{"key":"EnforcePurchaseOrder","value":1}'; check "purchase order rule switched on" '.success and .data.value == 1'
call POST inventory/documents "{\"type\":1,\"documentDate\":\"2026-10-23T00:00:00\",\"warehouseId\":$W1,\"lines\":[{\"itemId\":$BOLT,\"quantity\":1,\"locationId\":$L2}]}"
D=$(val .data.id); call POST "inventory/documents/$D/confirm"; check "receipt without order and price rejected" '.success == false'; call DELETE "inventory/documents/$D"
call POST inventory/documents "{\"type\":1,\"documentDate\":\"2026-10-23T00:00:00\",\"warehouseId\":$W1,\"lines\":[{\"itemId\":$BOLT,\"quantity\":1,\"locationId\":$L2,\"unitPrice\":60000000}]}"
D=$(val .data.id); call POST "inventory/documents/$D/confirm"; check "receipt without order above petty cash rejected" '.success == false'; call DELETE "inventory/documents/$D"
call POST inventory/documents "{\"type\":1,\"documentDate\":\"2026-10-23T00:00:00\",\"warehouseId\":$W1,\"lines\":[{\"itemId\":$BOLT,\"quantity\":2,\"locationId\":$L2,\"unitPrice\":400000}]}"
D=$(val .data.id); call POST "inventory/documents/$D/confirm"; check "petty-cash receipt without order accepted" '.success'

# ---------------------------------------------------------------- quality module (QC + QA), release 1
# Everything below uses its own contract, equipment and work orders; dates are relative to today so the
# welder continuity (six months) and calibration intervals behave the same on every run.
TOKEN=$ADMIN_TOKEN
QAID=$(uid "$QA_TOKEN"); QCID=$(uid "$QC_TOKEN"); QC2ID=$(uid "$QC2_TOKEN"); ENGID=$(uid "$ENG_TOKEN"); PRODID=$(uid "$PROD_TOKEN"); WHID=$(uid "$WH_TOKEN"); SECID=$(uid "$SEC_TOKEN")
[ -n "$QAID" ] && [ -n "$QCID" ] && [ -n "$QC2ID" ] && [ -n "$ENGID" ] && [ -n "$PRODID" ] && [ -n "$WHID" ] && ok "quality: user ids resolved" || bad "quality: user ids resolved"
# (as, uid, refused, no, nomsg, r403 and user2 are defined at the top of the script; the QA, second/third QC and finance-manager users are created there too)

# --- contract, pump equipment, two work orders (the pump template has 6 activities)
call POST Contracts '{"code":"QA-CT-01","title":"قرارداد آزمون ماژول کیفیت","status":1,"employer":"کارفرمای آزمون"}'; check "quality: contract created" '.success and .data.id > 0'
QCT=$(val .data.id)
call POST Equipments '{"code":"QA-EQ-PUMP","title":"Feed Pump API 610"}'; check "quality: pump equipment created" '.success and .data.id > 0'
QEQ=$(val .data.id)
call POST ContractEquipments "{\"contractId\":$QCT,\"equipmentId\":$QEQ,\"count\":2}"; check "quality: contract equipment" '.success'
call POST WorkOrders "{\"contractId\":$QCT,\"equipmentId\":$QEQ,\"code\":\"QA-WO-1\",\"title\":\"Pump unit 1\",\"description\":\"x\",\"count\":1}"; check "quality: work order 1" '.success and .data.id > 0'
WO1=$(val .data.id)
call POST WorkOrders "{\"contractId\":$QCT,\"equipmentId\":$QEQ,\"code\":\"QA-WO-2\",\"title\":\"Pump unit 2\",\"description\":\"x\",\"count\":1}"; check "quality: work order 2" '.success and .data.id > 0'
WO2=$(val .data.id)


# The bolts of the pump units come as the customer's property against the work orders (customer property receipt into a kind-8 warehouse, not valued). A release note lists only what a work
# order made or received, so these receipts are the "made" quantity of the release-note lines and of the delivery gate below (R1q review C1, H4).
call POST inventory/warehouses '{"code":"WH-CP","title":"اموال مشتری","kind":8}'; check "quality: customer-property warehouse (kind 8) created" '.success and .data.id > 0'
WCP=$(val .data.id)
call POST inventory/documents "{\"type\":17,\"documentDate\":\"${D0}T00:00:00\",\"warehouseId\":$WCP,\"contractId\":$QCT,\"workOrderId\":$WO1,\"lines\":[{\"itemId\":$BOLT,\"quantity\":5}]}"; check "quality: customer property receipt of 5 bolts for work order 1 drafted" '.success and .data.id > 0'
CPR1=$(val .data.id); call POST "inventory/documents/$CPR1/confirm"; check "quality: the 5 bolts of work order 1 are received" '.success and .data.status == 1'
call POST inventory/documents "{\"type\":17,\"documentDate\":\"${D0}T00:00:00\",\"warehouseId\":$WCP,\"contractId\":$QCT,\"workOrderId\":$WO2,\"lines\":[{\"itemId\":$BOLT,\"quantity\":1}]}"; CPR2=$(val .data.id)
call POST "inventory/documents/$CPR2/confirm"; check "quality: the bolt of work order 2 is received" '.success and .data.status == 1'
# --- A. ITP: templates, system drafts, point rules
as "$QC_TOKEN" GET quality/itp-templates; check "ITP templates seeded: steam turbine 37 rows, pump, condenser, lube oil" '.success and (.data.data|length) >= 4 and ([.data.data[]|select(.code=="ITP-STEAM-TURBINE")|.activityCount][0] == 37) and ([.data.data[]|select(.code=="ITP-PUMP")|.activityCount][0] == 6)'
PUMPT=$(jq -r '.data.data[]|select(.code=="ITP-PUMP")|.id' "$B")
as "$QC_TOKEN" GET "quality/itp-templates/$PUMPT"; check "pump template: hydro test has H/H/W and no invented test pressure" '[.data.activities[]|select(.seq==3)][0] as $a | ($a.pointVendor == 1 and $a.pointTpi == 1 and $a.pointClient == 2) and ([$a.parameters[]|select(.name=="Test pressure")|.requiresLimits][0] == true) and ([$a.parameters[]|select(.name=="Test pressure")|.max][0] == null)'
as "$WH_TOKEN" POST quality/itps/ensure "{\"workOrderId\":$WO1,\"productType\":4}"; no "warehouse user cannot create an ITP"
as "$QC_TOKEN" POST quality/itps/ensure "{\"workOrderId\":$WO1,\"productType\":4}"; check "ITP drafted from the pump template" '.success and .data.status == 0 and (.data.activities|length) == 6 and .data.templateCode == "ITP-PUMP" and .data.noticeDays == 10'
ITP1=$(val .data.id)
A1=$(val '.data.activities[]|select(.seq==1)|.id'); A2=$(val '.data.activities[]|select(.seq==2)|.id'); A3=$(val '.data.activities[]|select(.seq==3)|.id')
A4=$(val '.data.activities[]|select(.seq==4)|.id'); A5=$(val '.data.activities[]|select(.seq==5)|.id'); A6=$(val '.data.activities[]|select(.seq==6)|.id')
P_TESTP=$(val ".data.activities[]|select(.id==$A3)|.parameters[]|select(.name==\"Test pressure\")|.id")
as "$QC_TOKEN" POST quality/itps/ensure "{\"workOrderId\":$WO1,\"productType\":4}"; check "second ensure returns the same ITP" ".success and .data.id == $ITP1"
as "$QC_TOKEN" POST quality/itps/activity/action "{\"id\":$A1,\"action\":\"done\"}"; nomsg "activity with an H point cannot be done before the client approved the ITP" "کارفرما تایید نشده"
as "$QC_TOKEN" POST quality/itps/action "{\"id\":$ITP1,\"action\":\"client-approve\",\"reference\":\"CL-1\"}"; no "client approval before submission rejected"
as "$QC_TOKEN" POST quality/itps/action "{\"id\":$ITP1,\"action\":\"submit\"}"; check "ITP submitted" '.success and .data.status == 1'
# R1q review H6: the client's approval is recorded by somebody who did not prepare, change or submit the plan (a vendor cannot approve for the client alone), with the client's reference
# (at most 300 characters) and a date that is not in the future and not older than the back-date window
as "$QA_TOKEN" POST quality/itps/action "{\"id\":$ITP1,\"action\":\"client-approve\"}"; nomsg "client approval needs the client letter reference" "مرجع تایید کارفرما را وارد کنید"
as "$ENG_TOKEN" POST quality/itps/action "{\"id\":$ITP1,\"action\":\"client-approve\",\"reference\":\"CL-1\"}"; no "engineering cannot record the client approval"
as "$QC_TOKEN" POST quality/itps/action "{\"id\":$ITP1,\"action\":\"client-approve\",\"reference\":\"CL-LTR-77\",\"date\":\"$D0\"}"; nomsg "r1q H6: the QC user who prepared and submitted the plan cannot record the client's approval of it (segregation of duties)" "تفکیک وظایف"
as "$QA_TOKEN" POST quality/itps/action "{\"id\":$ITP1,\"action\":\"client-approve\",\"reference\":\"$LONGREF\"}"; nomsg "r1q H6: a client reference of 301 characters is refused" "حداکثر 300 نویسه"
as "$QA_TOKEN" POST quality/itps/action "{\"id\":$ITP1,\"action\":\"client-approve\",\"reference\":\"CL-LTR-77\",\"date\":\"$(dd 1)\"}"; nomsg "r1q H6: an approval dated tomorrow is refused" "نمی‌تواند در آینده باشد"
as "$QA_TOKEN" POST quality/itps/action "{\"id\":$ITP1,\"action\":\"client-approve\",\"reference\":\"CL-LTR-77\",\"date\":\"$(dd -10)\"}"; nomsg "r1q H6: an approval dated ten days back is refused (back-date window of 7 days)" "بیش از 7 روز پیش است"
as "$QA_TOKEN" POST quality/itps/action "{\"id\":$ITP1,\"action\":\"client-approve\",\"reference\":\"CL-LTR-77\",\"date\":\"$(dd -2)\"}"; check "ITP approved by the client (letter reference and the day kept; recorded by the QA manager, who did not touch the plan)" ".success and .data.status == 2 and .data.clientApprovalReference == \"CL-LTR-77\" and (.data.clientApprovalDate[0:10]) == \"$(dd -2)\""
as "$QC_TOKEN" POST quality/itps/activity/action "{\"id\":$A1,\"action\":\"done\"}"; check "H point: done refused without the vendor release" '.success == false and (.message|contains("H"))'
as "$ENG_TOKEN" POST quality/itps/release "{\"activityId\":$A1,\"party\":1,\"action\":1,\"personName\":\"Vendor QC\",\"organisation\":\"Vendor Co\",\"reference\":\"V-REL-1\"}"; no "only QC records a point release"
as "$QC_TOKEN" POST quality/itps/release "{\"activityId\":$A1,\"party\":1,\"action\":4,\"personName\":\"Vendor QC\",\"reference\":\"x\"}"; check "H point cannot be waived" '.success == false'
as "$QC_TOKEN" POST quality/itps/release "{\"activityId\":$A1,\"party\":1,\"action\":1,\"personName\":\"Vendor QC\",\"organisation\":\"Vendor Co\",\"reference\":\"V-REL-1\"}"; check "vendor H release recorded" '.success'
as "$QC_TOKEN" POST quality/itps/activity/action "{\"id\":$A1,\"action\":\"done\"}"; nomsg "r1q D18: an activity is not done without proof (an accepted inspection on it or an attached document)" "مدرک لازم است"
as "$QC_TOKEN" POST quality/itps/activity/action "{\"id\":$A1,\"action\":\"done\",\"evidenceDocumentId\":\"3fa85f64-5717-4562-b3fc-2c963f66afa6\"}"; nomsg "r1q D18: a document id that is not in the document store is no proof" "در مخزن اسناد پیدا نشد"
# R1q review M16: the proof is a file uploaded lately by a QC, QA or engineering user, and it proves one activity only
as "$QC_TOKEN" POST quality/itps/activity/action "{\"id\":$A1,\"action\":\"done\",\"evidenceDocumentId\":\"$DOCID\"}"; nomsg "r1q M16: a file uploaded by the PMO account is no proof (the uploader must be QC, QA or engineering)" "توسط کاربر QC، QA یا مهندسی بارگذاری شده باشد"
upload_as "$QC_TOKEN" itp-a1-evidence; EV1=$UPLOADED
[ -n "$EV1" ] && ok "r1q M16: the certificate review file is uploaded by the QC user" || bad "r1q M16: the certificate review file is uploaded by the QC user"
as "$QC_TOKEN" POST quality/itps/activity/action "{\"id\":$A1,\"action\":\"done\",\"evidenceDocumentId\":\"$EV1\",\"note\":\"Certificates EN 10204 3.1 reviewed\"}"; check "H point released and proven by the file the QC user uploaded -> activity done, ITP in use (the evidence stays on the activity)" ".success and ([.data.activities[]|select(.id==$A1)|.status][0] == 2) and ([.data.activities[]|select(.id==$A1)|.evidenceDocumentId][0] == \"$EV1\") and .data.status == 3"
as "$QC_TOKEN" POST quality/itps/release "{\"activityId\":$A6,\"party\":1,\"action\":1,\"personName\":\"Vendor QC\",\"organisation\":\"Vendor Co\",\"reference\":\"V-REL-6\"}"; check "vendor H release on the packing activity" '.success'
as "$QC_TOKEN" POST quality/itps/activity/action "{\"id\":$A6,\"action\":\"done\",\"evidenceDocumentId\":\"$EV1\"}"; nomsg "r1q M16: the file that proved the first activity cannot prove a second one" "پیش‌تر مدرک فعالیت دیگری شده است"
CODE=$(curl -s -o "$B" -w '%{http_code}' -X PUT "$API/Documents/change-file?documentId=$EV1" -H "Authorization: Bearer $QC_TOKEN" -F "File=@$OUT/itp-a1-evidence.txt"); nomsg "r1q M16: the file that proves an activity cannot be replaced afterwards" "مدرک انجام یک فعالیت برنامه بازرسی"
as "$PROD_TOKEN" POST quality/itps/activity/action "{\"id\":$A4,\"action\":\"not-applicable\",\"note\":\"x\"}"; no "production cannot mark an activity not applicable"
as "$QC_TOKEN" POST quality/itps/activity/action "{\"id\":$A4,\"action\":\"not-applicable\"}"; no "not applicable needs a reason"
as "$QC_TOKEN" POST quality/itps/activity/action "{\"id\":$A4,\"action\":\"not-applicable\",\"note\":\"No run test for this pump order\",\"reference\":\"$LONGREF\"}"; nomsg "r1q H6: the reference of a not-applicable decision is at most 300 characters" "حداکثر 300 نویسه"
as "$QC_TOKEN" POST quality/itps/activity/action "{\"id\":$A4,\"action\":\"not-applicable\",\"note\":\"No run test for this pump order\",\"reference\":\"CL-LTR-81\"}"; nomsg "r1q H6: a witness point of the client or the third party is not dropped with a typed reference: only the client's incoming letter registered in the Office counts" "نامه موافقت کارفرما"
# R1q review H6: the notice period is at least the company minimum (1 day by default; 0 days would waive the client's witness at once) and is locked once the client approved the plan
as "$QC_TOKEN" POST quality/itps "{\"id\":$ITP1,\"noticeDays\":0}"; nomsg "r1q H6: a notice period of 0 days is refused (company minimum 1 day)" "باید بین 1 تا 365 روز باشد"
as "$QC_TOKEN" POST quality/itps "{\"id\":$ITP1,\"noticeDays\":3}"; nomsg "r1q D9: the notice period is locked once the client approved the plan" "قفل است"

# the system drafts the ITP of a work order that only has QC records (no human step)
call POST quality/records "{\"type\":1,\"workOrderId\":$WO2,\"operation\":\"Casing welding\",\"result\":1,\"quantity\":1}"; check "first record of work order 2 saved (PMO may write non-ITP records)" '.success' 
as "$QC_TOKEN" GET "quality/itps/by-work-order/$WO2"; check "ITP of work order 2 was drafted by the system when the first record was saved" '.success and .data.autoDrafted == true and .data.status == 0 and (.data.activities|length) == 6'
ITP2=$(val .data.id)

# --- B. calibration and measuring equipment
as "$QC_TOKEN" GET quality/calibration/intervals; check "default calibration intervals seeded with their source" '.success and (.data|length) >= 5 and ([.data[]|.source]|all(. != null))'
as "$WH_TOKEN" POST quality/equipment '{"name":"Caliper","type":1}'; no "warehouse user cannot register measuring equipment"
as "$QC_TOKEN" POST quality/equipment '{"name":"Digital caliper 0-150","type":1,"serialNumber":"DC-1","location":"QC lab"}'; check "equipment registered with an INN-IST code and the default interval" '.success and (.data.code|test("^INN-IST-[0-9]+$")) and .data.intervalMonths > 0'
G1=$(val .data.id); G1CODE=$(val .data.code)
call GET "quality/equipment/$G1"; check "never calibrated instrument is overdue (computed, not stored)" '.data.status == 2'
as "$QC_TOKEN" POST quality/records "{\"type\":3,\"workOrderId\":$WO1,\"quantity\":1,\"result\":1,\"measurements\":[{\"characteristic\":\"Bore\",\"nominal\":100,\"tolPlus\":0.05,\"tolMinus\":0.05,\"measured\":100.01,\"unit\":\"mm\",\"equipmentId\":$G1}]}"; nomsg "record with an uncalibrated instrument rejected" "کالیبره نشده"
as "$QC_TOKEN" POST quality/equipment/calibration "{\"equipmentId\":$G1,\"eventDate\":\"$(dd -200)\",\"labName\":\"Lab A\",\"labAccredited\":true,\"certificateNumber\":\"CAL-G1-1\",\"asFoundPass\":true,\"asLeftPass\":true}"; nomsg "calibration without a traceability statement rejected (ISO 7.1.5.1)" "7.1.5.1"
as "$WH_TOKEN" POST quality/equipment/calibration "{\"equipmentId\":$G1,\"eventDate\":\"$(dd -200)\",\"labName\":\"Lab A\",\"certificateNumber\":\"CAL-G1-1\",\"traceabilityStatement\":\"Traceable to national standard\",\"asFoundPass\":true,\"asLeftPass\":true}"; no "only QC registers a calibration"
as "$QC_TOKEN" POST quality/equipment/calibration "{\"equipmentId\":$G1,\"eventDate\":\"$(dd -200)\",\"labName\":\"Lab A\",\"labAccredited\":true,\"certificateNumber\":\"CAL-G1-1\",\"certificateDocumentId\":\"$DOCID\",\"traceabilityStatement\":\"Traceable to national standard\",\"asFoundPass\":true,\"asLeftPass\":true}"; check "calibration registered: valid for the interval" '.success and .data.status == 0 and .data.nextDue != null and (.data.events|length) == 1'
# an instrument whose certificate expired two years ago, one that failed its last calibration, one due in ten days
as "$QC_TOKEN" POST quality/equipment '{"name":"Old micrometer","type":1,"serialNumber":"MM-2"}'; G2=$(val .data.id)
as "$QC_TOKEN" POST quality/equipment/calibration "{\"equipmentId\":$G2,\"eventDate\":\"$(dd -800)\",\"labName\":\"Lab A\",\"certificateNumber\":\"CAL-G2-1\",\"traceabilityStatement\":\"Traceable\",\"asFoundPass\":true,\"asLeftPass\":true}"
call GET "quality/equipment/$G2"; check "expired certificate -> overdue" '.data.status == 2'
as "$QC_TOKEN" POST quality/records "{\"type\":3,\"workOrderId\":$WO1,\"quantity\":1,\"result\":1,\"measurements\":[{\"characteristic\":\"Bore\",\"nominal\":100,\"tolPlus\":0.05,\"tolMinus\":0.05,\"measured\":100.01,\"unit\":\"mm\",\"equipmentId\":$G2}]}"; check "overdue instrument cannot be used" '.success == false and (.message|contains("INN-IST"))'
as "$QC_TOKEN" POST quality/equipment '{"name":"Dial gauge","type":2}'; G3=$(val .data.id)
as "$QC_TOKEN" POST quality/equipment/calibration "{\"equipmentId\":$G3,\"eventDate\":\"$(dd -10)\",\"labName\":\"Lab A\",\"certificateNumber\":\"CAL-G3-1\",\"traceabilityStatement\":\"Traceable\",\"asFoundPass\":false,\"asLeftPass\":false}"; check "calibration failed as-left -> out of service" '.success and .data.status == 3'
as "$QC_TOKEN" POST quality/records "{\"type\":3,\"workOrderId\":$WO1,\"quantity\":1,\"result\":1,\"measurements\":[{\"characteristic\":\"Bore\",\"nominal\":100,\"tolPlus\":0.05,\"tolMinus\":0.05,\"measured\":100.01,\"unit\":\"mm\",\"equipmentId\":$G3}]}"; nomsg "out-of-service instrument cannot be used" "از رده خارج"
as "$QC_TOKEN" POST quality/equipment/action "{\"id\":$G3,\"action\":\"return-to-service\"}"; nomsg "return to service needs a valid calibration first" "کالیبراسیون معتبر"
as "$QC_TOKEN" POST quality/equipment '{"name":"Torque wrench","type":99}'; G5=$(val .data.id)
as "$QC_TOKEN" POST quality/equipment/calibration "{\"equipmentId\":$G5,\"eventDate\":\"$(dd -355)\",\"labName\":\"Lab A\",\"certificateNumber\":\"CAL-G5-1\",\"traceabilityStatement\":\"Traceable\",\"asFoundPass\":true,\"asLeftPass\":true,\"intervalMonths\":12}"
call GET "quality/equipment/due?Days=30"; check "due list holds the instrument due within 30 days and the overdue ones" "(.data.data|map(.id)|index($G5)) != null and (.data.data|map(.id)|index($G2)) != null"
as "$QC_TOKEN" POST quality/equipment '{"name":"Reference caliper for reports","type":1}'; G4=$(val .data.id)
as "$QC_TOKEN" POST quality/equipment/calibration "{\"equipmentId\":$G4,\"eventDate\":\"$(dd -60)\",\"labName\":\"Lab A\",\"labAccredited\":true,\"certificateNumber\":\"CAL-G4-1\",\"certificateDocumentId\":\"$DOCID\",\"traceabilityStatement\":\"Traceable\",\"asFoundPass\":true,\"asLeftPass\":true}"
as "$QC_TOKEN" POST quality/equipment '{"name":"Test pressure gauge","type":3}'; PG1=$(val .data.id)
as "$QC_TOKEN" POST quality/equipment/calibration "{\"equipmentId\":$PG1,\"eventDate\":\"$(dd -30)\",\"labName\":\"Lab A\",\"labAccredited\":true,\"certificateNumber\":\"CAL-PG1-1\",\"certificateDocumentId\":\"$DOCID\",\"traceabilityStatement\":\"Traceable\",\"asFoundPass\":true,\"asLeftPass\":true}"; check "pressure gauge calibrated" '.success and .data.status == 0'

# --- C. inspection records with measurements, self inspection, auto NCR
as "$QC_TOKEN" POST quality/records "{\"type\":3,\"workOrderId\":$WO1,\"itpActivityId\":$A2,\"quantity\":1,\"result\":1,\"measurements\":[{\"characteristic\":\"Bore\",\"nominal\":100,\"tolPlus\":0.05,\"tolMinus\":0.05,\"measured\":100.02,\"unit\":\"mm\"}]}"; nomsg "r1q D16: a measured value without the instrument that measured it is refused" "تجهیز اندازه‌گیری (ابزار) را انتخاب کنید"
as "$QC_TOKEN" POST quality/records "{\"type\":3,\"workOrderId\":$WO1,\"itpActivityId\":$A2,\"quantity\":1,\"operation\":\"Casing bore\",\"drawingNumber\":\"DWG-1\",\"drawingRevision\":\"A\",\"result\":1,\"measurements\":[{\"characteristic\":\"Bore\",\"nominal\":100,\"tolPlus\":0.05,\"tolMinus\":0.05,\"measured\":100.02,\"unit\":\"mm\",\"equipmentId\":$G1}]}"
check "dimensional record with a calibrated instrument" '.success and (.data.number|startswith("QIR-")) and .data.result == 1 and .data.measurements[0].pass == true and .data.selfInspection == false'
R1=$(val .data.id); R1NUM=$(val .data.number)
as "$QC_TOKEN" POST quality/records "{\"type\":3,\"workOrderId\":$WO1,\"itpActivityId\":$A2,\"quantity\":1,\"result\":1,\"measurements\":[{\"characteristic\":\"Bore\",\"nominal\":100,\"tolPlus\":0.05,\"tolMinus\":0.05,\"measured\":100.2,\"unit\":\"mm\",\"equipmentId\":$G1}]}"; nomsg "accepting an out-of-tolerance measurement rejected" "خارج از تلرانس"
as "$PROD_TOKEN" POST quality/records "{\"type\":3,\"workOrderId\":$WO1,\"itpActivityId\":$A2,\"quantity\":1,\"result\":1,\"measurements\":[{\"characteristic\":\"Bore\",\"nominal\":100,\"tolPlus\":0.05,\"tolMinus\":0.05,\"measured\":100.0,\"unit\":\"mm\"}]}"; nomsg "ITP inspections are QC only (operator refused)" "فقط توسط بازرس QC"
as "$PROD_TOKEN" POST quality/records "{\"type\":1,\"workOrderId\":$WO2,\"operation\":\"Machining\",\"quantity\":1,\"result\":1}"; check "operator self-inspection allowed outside the ITP and marked as such" '.success and .data.selfInspection == true'
as "$QC_TOKEN" POST quality/records "{\"type\":3,\"workOrderId\":$WO2,\"itemId\":$BOLT,\"quantity\":1,\"result\":1,\"measurements\":[{\"characteristic\":\"Thread\",\"nominal\":24,\"tolPlus\":0.1,\"tolMinus\":0.1,\"measured\":24.05,\"unit\":\"mm\",\"equipmentId\":$G1}]}"; check "second record with the same instrument (item known)" '.success'
R2=$(val .data.id); R2NUM=$(val .data.number)
as "$QC_TOKEN" POST quality/records "{\"type\":3,\"workOrderId\":$WO2,\"quantity\":1,\"result\":2,\"note\":\"x\",\"measurements\":[{\"characteristic\":\"Bore\",\"nominal\":100,\"tolPlus\":0.05,\"tolMinus\":0.05,\"measured\":100.4,\"unit\":\"mm\",\"equipmentId\":$G1}]}"; nomsg "reject without an item (no NCR possible) rejected" "گزارش عدم انطباق"
as "$QC_TOKEN" POST quality/records "{\"type\":3,\"workOrderId\":$WO2,\"itemId\":$BOLT,\"quantity\":1,\"result\":2,\"measurements\":[{\"characteristic\":\"Thread\",\"nominal\":24,\"tolPlus\":0.1,\"tolMinus\":0.1,\"measured\":24.4,\"unit\":\"mm\",\"equipmentId\":$G1}]}"
check "reject drafts an NCR automatically (with source record, due date, not classified)" '.success and .data.result == 2 and .data.ncrId != null and (.data.ncrNumber|startswith("NCR-"))'
R3=$(val .data.id); R3NCR=$(val .data.ncrId); R3NUM=$(val .data.number)
call GET "inventory/quality/ncr/$R3NCR"; check "auto NCR: not classified, decision deadline set, source record linked, work order 2" ".success and .data.severity == 0 and .data.dueDate != null and .data.sourceRecordNumber == \"$R3NUM\" and .data.workOrderId == $WO2 and .data.status == 0"

# R1q D15: a record may be entered a few days late (company setting, default 7 days), never months later; the instrument must have been calibrated on the record date and is calibrated today
as "$QC_TOKEN" POST quality/records "{\"type\":3,\"workOrderId\":$WO2,\"itemId\":$BOLT,\"quantity\":1,\"result\":1,\"recordDate\":\"$(dd -30)\",\"measurements\":[{\"characteristic\":\"Thread\",\"nominal\":24,\"tolPlus\":0.1,\"tolMinus\":0.1,\"measured\":24.05,\"unit\":\"mm\",\"equipmentId\":$G1}]}"; nomsg "r1q D15: an inspection dated 30 days back is refused (back-date window of 7 days)" "ثبت با تاخیر بیش از 7 روز مجاز نیست"
as "$QC_TOKEN" POST quality/equipment '{"name":"Fresh caliper","type":1}'; FC=$(val .data.id)
as "$QC_TOKEN" POST quality/equipment/calibration "{\"equipmentId\":$FC,\"eventDate\":\"$(dd -2)\",\"labName\":\"Lab A\",\"labAccredited\":true,\"certificateNumber\":\"CAL-FC-1\",\"certificateDocumentId\":\"$DOCID\",\"traceabilityStatement\":\"Traceable\",\"asFoundPass\":true,\"asLeftPass\":true}"; check "r1q D15: a caliper calibrated two days ago" '.success and .data.status == 0'
as "$QC_TOKEN" POST quality/records "{\"type\":3,\"workOrderId\":$WO2,\"itemId\":$BOLT,\"quantity\":1,\"result\":1,\"recordDate\":\"$(dd -5)\",\"measurements\":[{\"characteristic\":\"Thread\",\"nominal\":24,\"tolPlus\":0.1,\"tolMinus\":0.1,\"measured\":24.05,\"unit\":\"mm\",\"equipmentId\":$FC}]}"; nomsg "r1q D15: a record dated five days back cannot use an instrument that was not calibrated yet on that day" "کالیبراسیون معتبر نداشته است"
as "$QC_TOKEN" POST quality/records "{\"type\":3,\"workOrderId\":$WO2,\"itemId\":$BOLT,\"quantity\":1,\"result\":1,\"recordDate\":\"$(dd -1)\",\"measurements\":[{\"characteristic\":\"Thread\",\"nominal\":24,\"tolPlus\":0.1,\"tolMinus\":0.1,\"measured\":24.05,\"unit\":\"mm\",\"equipmentId\":$FC}]}"; check "r1q D15: a record dated yesterday with the same instrument is accepted (calibrated on that day and today)" ".success and (.data.recordDate[0:10]) == \"$(dd -1)\" and .data.measurements[0].equipmentCode != null"
# R1q D14, review M14: declaring an instrument calibration-free is a two-step decision of the quality department: the QA manager asks with a written reason and another QA or QC user approves; the
# register call itself (new or existing instrument) never switches the requirement off; both steps are in the audit trail
as "$QA_TOKEN" POST quality/equipment "{\"id\":$FC,\"name\":\"Fresh caliper\",\"type\":1,\"requiresCalibration\":false,\"calibrationWaiverReason\":\"x\"}"; nomsg "r1q M14: saving an existing instrument with the calibration switched off is refused, even for the QA manager (two steps)" "دو مرحله دارد"
as "$QA_TOKEN" POST quality/equipment '{"name":"Waived gauge","type":1,"requiresCalibration":false}'; nomsg "r1q M14: a new instrument cannot be registered as calibration-free either" "دو مرحله دارد"
as "$QC_TOKEN" POST quality/equipment/action "{\"id\":$FC,\"action\":\"request-waiver\",\"reason\":\"x\"}"; nomsg "r1q D14: QC cannot ask to switch the calibration requirement off (a decision of the QA manager)" "تصمیم مدیر QA"
as "$QA_TOKEN" POST quality/equipment/action "{\"id\":$FC,\"action\":\"request-waiver\"}"; nomsg "r1q D14: the QA manager needs a written reason" "دلیل بی‌نیازی"
as "$QA_TOKEN" POST quality/equipment/action "{\"id\":$FC,\"action\":\"request-waiver\",\"reason\":\"$LONG1001\"}"; nomsg "r1q L21: a reason longer than 1000 characters is refused with a message, not by the database" "متن دلیل بیش از ۱۰۰۰ نویسه است"
as "$QA_TOKEN" POST quality/equipment/action "{\"id\":$FC,\"action\":\"request-waiver\",\"reason\":\"Go/no-go gauge: no measuring function\"}"; check "r1q M14: the QA manager's request waits for a second person; the instrument still needs its calibration" '.success and .data.waiverPending == true and .data.status != 4 and .data.calibrationWaiverRequestReason == "Go/no-go gauge: no measuring function" and .data.calibrationWaiverRequestedByName != null and .data.calibrationWaivedAt == null'
as "$QA_TOKEN" POST quality/equipment/action "{\"id\":$FC,\"action\":\"request-waiver\",\"reason\":\"again\"}"; nomsg "r1q M14: a second request is refused while one is pending" "در انتظار تایید است"
as "$QC_TOKEN" POST quality/equipment/action "{\"id\":$FC,\"action\":\"reject-waiver\"}"; check "r1q M14: another user rejects the request: the instrument is as before" '.success and .data.waiverPending == false and .data.calibrationWaiverRequestReason == null and .data.status != 4'
as "$QA_TOKEN" POST quality/equipment/action "{\"id\":$FC,\"action\":\"request-waiver\",\"reason\":\"Go/no-go gauge: no measuring function\"}"; check "r1q M14: the QA manager asks again" '.success and .data.waiverPending == true'
as "$QA_TOKEN" POST quality/equipment/action "{\"id\":$FC,\"action\":\"approve-waiver\"}"; nomsg "r1q M14: the requester cannot approve his own request" "درخواست‌کننده نمی‌تواند"
as "$WH_TOKEN" POST quality/equipment/action "{\"id\":$FC,\"action\":\"approve-waiver\"}"; no "r1q M14: the warehouse user cannot approve it"
as "$QC_TOKEN" POST quality/equipment/action "{\"id\":$FC,\"action\":\"approve-waiver\"}"; check "r1q D14: a second person approves: the calibration is not required (status 4), the reason and the day stay on the instrument" '.success and .data.status == 4 and .data.waiverPending == false and .data.calibrationWaiverReason == "Go/no-go gauge: no measuring function" and .data.calibrationWaivedAt != null'
as "$FM_TOKEN" GET "finance/audit?EntityType=MeasuringEquipment&EntityId=$FC&PageSize=0"; check "r1q D14: the two requests and the approval (three changes that carry the reason) are in the audit trail with the user" '.success and ([.data.data[]|select(.action == "Modified" and (.userName|length) > 0 and (.afterJson|tostring|contains("Go/no-go gauge")))]|length) == 3'
# R1q D3: an NCR drafted from a failed inspection is cancelled only by somebody other than the inspector, with a reason, and only after an accepted re-inspection of the same product (★)
as "$QC_TOKEN" POST quality/records "{\"type\":1,\"workOrderId\":$WO2,\"itemId\":$BOLT,\"operation\":\"Final visual\",\"quantity\":1,\"result\":2,\"note\":\"Scratch on the thread\"}"; check "r1q D3: a failed visual inspection drafts an NCR" '.success and .data.result == 2 and .data.ncrId != null'
NCR4=$(val .data.ncrId)
as "$QC2_TOKEN" GET "office/inbox?SourceKey=ncr:$NCR4:classify"; check "r1q D34: the drafted NCR is in the QC inbox at once, due on the minor decision date (7 days), and the link opens the NCR page" ".success and (.data.data|length) == 1 and .data.data[0].recipientRole == \"QC\" and (.data.data[0].dueDate[0:10]) == \"$(dd 7)\" and .data.data[0].link == \"/inventory/ncr/$NCR4\""
as "$QC2_TOKEN" POST inventory/quality/ncr/close "{\"id\":$NCR4,\"cancel\":true}"; nomsg "r1q D3: cancelling an NCR needs a reason" "علت ابطال"
as "$QC_TOKEN" POST inventory/quality/ncr/close "{\"id\":$NCR4,\"cancel\":true,\"reason\":\"Entered by mistake\"}"; nomsg "r1q D3: the inspector whose inspection drafted the NCR cannot cancel it" "ثبت‌کننده یا ویرایشگر"
as "$QC2_TOKEN" POST inventory/quality/ncr/close "{\"id\":$NCR4,\"cancel\":true,\"reason\":\"Entered by mistake\"}"; nomsg "r1q D3: an NCR of a failed inspection is not cancelled before an accepted re-inspection exists" "تا بازرسی مجدد قبول‌شده‌ای"
as "$QC_TOKEN" POST quality/records "{\"type\":1,\"workOrderId\":$WO2,\"itemId\":$BOLT,\"operation\":\"Final visual\",\"quantity\":1,\"result\":1}"; check "r1q D3: the re-inspection of the same product is accepted" '.success and .data.result == 1 and .data.ncrId == null'; RRA=$(val .data.id)
as "$QC2_TOKEN" POST inventory/quality/ncr/close "{\"id\":$NCR4,\"cancel\":true,\"reason\":\"Re-inspected and accepted\"}"; check "r1q D3: another QC user cancels it with a reason; who and why are kept" '.success and .data.status == 4 and .data.cancelReason == "Re-inspected and accepted" and .data.cancelledByName != null'
as "$QC2_TOKEN" GET "office/inbox?SourceKey=ncr:$NCR4:classify"; check "r1q D34: the cancelled NCR leaves the QC inbox" '.success and (.data.data|length) == 0'
# R1q D17 ★: the register of inspector qualifications starts to count when the first one is entered; then a QC inspector records only with a valid certificate of his own
as "$QA_TOKEN" POST quality/persons "{\"name\":\"QC Two (inspector)\",\"personnelCode\":\"I-002\",\"employer\":1,\"userId\":$QC2ID}"; IP2=$(val .data.id)
as "$QA_TOKEN" POST quality/qualifications "{\"personId\":$IP2,\"kind\":4,\"method\":\"VISUAL\",\"scope\":\"Dimensional and visual inspection\",\"certificateNumber\":\"INS-QC2\",\"issuedDate\":\"$(dd -30)\",\"expiryDate\":\"$(dd 300)\"}"; check "r1q D17: an inspector qualification registered for the second QC user" '.success and .data.state == 0 and .data.kind == 4'
as "$QC_TOKEN" POST quality/records "{\"type\":1,\"workOrderId\":$WO2,\"operation\":\"Visual check\",\"quantity\":1,\"result\":1}"; nomsg "r1q D17: a QC inspector without a registered inspector qualification is refused once the register is in use" "ثبت بازرسی بدون گواهی صلاحیت معتبر مجاز نیست"
as "$QC2_TOKEN" POST quality/records "{\"type\":1,\"workOrderId\":$WO2,\"operation\":\"Visual check\",\"quantity\":1,\"result\":1}"; check "r1q D17: the inspector with a valid qualification records" '.success and .data.result == 1'
as "$QA_TOKEN" POST quality/persons "{\"name\":\"QC One (inspector)\",\"personnelCode\":\"I-001\",\"employer\":1,\"userId\":$QCID}"; IP1=$(val .data.id)
as "$QA_TOKEN" POST quality/qualifications "{\"personId\":$IP1,\"kind\":4,\"method\":\"VISUAL\",\"certificateNumber\":\"INS-QC1-OLD\",\"issuedDate\":\"$(dd -400)\",\"expiryDate\":\"$(dd -10)\"}"; IQ1=$(val .data.id)
as "$QC_TOKEN" POST quality/records "{\"type\":1,\"workOrderId\":$WO2,\"operation\":\"Visual check\",\"quantity\":1,\"result\":1}"; nomsg "r1q D17: an expired inspector qualification does not count" "منقضی‌شده"
as "$QC_TOKEN" POST quality/itps/activity/action "{\"id\":$A2,\"action\":\"done\"}"; nomsg "r1q D17: the expired qualification also stops the same QC user marking an ITP activity done (the competence is checked before the plan's own rules)" "ثبت انجام‌شدن فعالیت برنامه بازرسی بدون گواهی صلاحیت معتبر مجاز نیست"
as "$QA_TOKEN" POST quality/qualifications "{\"personId\":$IP1,\"kind\":4,\"method\":\"VISUAL\",\"certificateNumber\":\"INS-QC1\",\"issuedDate\":\"$(dd -5)\",\"expiryDate\":\"$(dd 360)\",\"renewsQualificationId\":$IQ1}"; check "r1q D17: the qualification of the first QC user is renewed" '.success and .data.state == 0'
as "$QC_TOKEN" POST quality/records "{\"type\":1,\"workOrderId\":$WO2,\"operation\":\"Visual check\",\"quantity\":1,\"result\":1}"; check "r1q D17: with the renewed qualification the first QC user records again" '.success and .data.result == 1'
as "$QC_TOKEN" POST quality/itps/activity/action "{\"id\":$A2,\"action\":\"done\"}"; check "r1q D17: with the renewed qualification the same call gets past the competence check and stops only at the plan's own rule (the vendor H release)" '.success == false and (.message|contains("H")) and ((.message|contains("گواهی صلاحیت"))|not)'

# R1q D5: a decision on a product found in the workshop (no warehouse) is "executed" only with the record that proves it
ncr "{\"source\":2,\"severity\":1,\"itemId\":$BOLT,\"quantity\":1,\"workOrderId\":$WO2,\"disposition\":2,\"description\":\"Thread damaged during assembly\",\"causeCategory\":1,\"rootCause\":\"Cross-threaded by hand\",\"correctiveAction\":\"Thread gauge check before assembly\"}"; NCR5=$(val .data.id)
approve3 "$NCR5"; check "r1q D5: NCR5 (a bolt found in the workshop, rework) is approved" '.success and .data.status == 1 and .data.warehouseId == null'
as "$QC_TOKEN" POST inventory/quality/ncr/execute "{\"id\":$NCR5}"; nomsg "r1q D5: a workshop rework is not executed by a click: it needs the finished rework operation or an accepted re-inspection" "عملیات دوباره‌کاری پایان‌یافته و بازرسی قبول‌شده"
as "$QC_TOKEN" POST inventory/quality/ncr/execute "{\"id\":$NCR5,\"reworkOperationId\":999999}"; nomsg "r1q D5: an unknown rework operation is refused" "عملیات دوباره‌کاری پیدا نشد"
as "$QC_TOKEN" POST inventory/quality/ncr/execute "{\"id\":$NCR5,\"reinspectionKind\":\"QcRecord\",\"reinspectionRecordId\":$R3}"; nomsg "r1q D5: a rejected inspection record is not a re-inspection" "با نتیجه «قبول» نیست"
# R1q review H3: the re-inspection that proves a workshop rework is a record of THIS product made AFTER this report; an old accepted record, or an inspection made for something else, proves nothing
as "$QC_TOKEN" POST inventory/quality/ncr/execute "{\"id\":$NCR5,\"reinspectionKind\":\"QcRecord\",\"reinspectionRecordId\":$RRA}"; nomsg "r1q H3: an accepted record made BEFORE the report is no evidence of the rework" "بازرسی مجدد باید بعد از ثبت گزارش عدم انطباق انجام شده باشد"
as "$QC_TOKEN" POST inventory/quality/ncr/execute "{\"id\":$NCR5,\"reinspectionKind\":\"QcInspection\",\"reinspectionRecordId\":$QI_P}"; nomsg "r1q H3: an incoming inspection that is not the re-inspection of this report is refused" "بازرسی مجدد همین گزارش عدم انطباق نیست"
as "$QC_TOKEN" POST quality/records "{\"type\":1,\"workOrderId\":$WO2,\"itemId\":$BOLT,\"operation\":\"Re-inspection after rework\",\"quantity\":1,\"result\":1}"; RR=$(val .data.id)
as "$QC_TOKEN" POST inventory/quality/ncr/execute "{\"id\":$NCR5,\"reinspectionKind\":\"QcRecord\",\"reinspectionRecordId\":$RR}"; check "r1q D5: executed with the accepted re-inspection record, which stays linked to the NCR" ".success and .data.status == 2 and .data.reinspectionKind == \"QcRecord\" and .data.reinspectionRecordId == $RR"
as "$QC2_TOKEN" POST inventory/quality/ncr/close "{\"id\":$NCR5,\"effectivenessCheck\":\"Gauge check in use, no repeat in the next ten assemblies\"}"; check "r1q D5: NCR5 closed by the second QC user" '.success and .data.status == 3'
# R1q review H3: one re-inspection record proves one report, and the person who closes a report does not close it on his own evidence
ncr "{\"source\":2,\"severity\":1,\"itemId\":$BOLT,\"quantity\":1,\"workOrderId\":$WO2,\"disposition\":2,\"description\":\"Second cross-threaded bolt\",\"causeCategory\":1,\"rootCause\":\"Cross-threaded by hand\",\"correctiveAction\":\"Thread gauge check before assembly\"}"; NCR9=$(val .data.id)
approve3 "$NCR9"; check "r1q H3: NCR9 (a second bolt found in the workshop, rework) is approved" '.success and .data.status == 1 and .data.warehouseId == null'
as "$QC_TOKEN" POST inventory/quality/ncr/execute "{\"id\":$NCR9,\"reinspectionKind\":\"QcRecord\",\"reinspectionRecordId\":$RR}"; nomsg "r1q H3: the record that proved NCR5 does not prove NCR9 (one re-inspection proves one report)" "قبلاً برای گزارش عدم انطباق دیگری ثبت شده است"
as "$QC2_TOKEN" POST quality/records "{\"type\":1,\"workOrderId\":$WO2,\"itemId\":$BOLT,\"operation\":\"Re-inspection of the second bolt\",\"quantity\":1,\"result\":1}"; check "r1q H3: the second QC user re-inspects the second bolt (accepted)" '.success and .data.result == 1'
RR9=$(val .data.id)
as "$QC_TOKEN" POST inventory/quality/ncr/execute "{\"id\":$NCR9,\"reinspectionKind\":\"QcRecord\",\"reinspectionRecordId\":$RR9}"; check "r1q H3: NCR9 is executed with its own record" ".success and .data.status == 2 and .data.reinspectionKind == \"QcRecord\" and .data.reinspectionRecordId == $RR9"
as "$QC2_TOKEN" POST inventory/quality/ncr/close "{\"id\":$NCR9,\"effectivenessCheck\":\"Gauge check in use\"}"; nomsg "r1q H3: the second QC user cannot close the report on the re-inspection he recorded himself" "بازرسی مجدد را خود شما ثبت کرده‌اید"
as "$QC3_TOKEN" POST inventory/quality/ncr/close "{\"id\":$NCR9,\"effectivenessCheck\":\"Gauge check in use\"}"; check "r1q H3: the third QC user closes NCR9" '.success and .data.status == 3'
# R1q review H7: the person whose failed record drafted a report (here the operator's self-inspection) is a maker of it and cannot give a signature either; an edit of what the signers read clears the signatures
as "$PROD_TOKEN" POST quality/records "{\"type\":1,\"workOrderId\":$WO2,\"itemId\":$BOLT,\"operation\":\"Operator check of the thread\",\"quantity\":1,\"result\":2,\"note\":\"Burr on the thread\"}"; check "r1q H7: the failed self-inspection of the operator drafts an NCR" '.success and .data.result == 2 and .data.ncrId != null and .data.selfInspection == true'
NCR10=$(val .data.ncrId)
ncr "{\"id\":$NCR10,\"severity\":1,\"disposition\":4,\"source\":2,\"description\":\"Burr on the thread\",\"causeCategory\":1,\"rootCause\":\"Tap worn\",\"correctiveAction\":\"Change the tap every 200 holes\"}"; check "r1q H7: NCR10 classified by QC: minor, scrap" '.success and .data.severity == 1 and .data.disposition == 4'
as "$QC2_TOKEN" POST inventory/quality/ncr/approve "{\"id\":$NCR10,\"kind\":4}"; check "r1q H7: NCR10 signed by the second QC user" '.success and .data.qualityApprovedAt != null'
as "$ENG_TOKEN" POST inventory/quality/ncr/approve "{\"id\":$NCR10,\"kind\":5}"; check "r1q H7: NCR10 signed by engineering" '.success and .data.engineeringApprovedAt != null and .data.status == 0'
as "$PROD_TOKEN" POST inventory/quality/ncr/approve "{\"id\":$NCR10,\"kind\":3}"; nomsg "r1q H7: the operator whose record drafted the report cannot give the manufacturing signature" "ثبت‌کننده یا ویرایشگر گزارش نمی‌تواند آن را امضا کند"
ncr "{\"id\":$NCR10,\"severity\":1,\"disposition\":4,\"source\":2,\"description\":\"Burr on the thread, found again on the next piece\",\"causeCategory\":1,\"rootCause\":\"Tap worn\",\"correctiveAction\":\"Change the tap every 200 holes\"}"; check "r1q H7: a change of what the signers read (the facts) clears both signatures" '.success and .data.qualityApprovedAt == null and .data.engineeringApprovedAt == null and .data.status == 0'
as "$QC_TOKEN" POST quality/records "{\"type\":1,\"workOrderId\":$WO2,\"itemId\":$BOLT,\"operation\":\"Operator check of the thread\",\"quantity\":1,\"result\":1}"; check "r1q H7: a later accepted re-inspection of the same product" '.success and .data.result == 1'
as "$QC2_TOKEN" POST inventory/quality/ncr/close "{\"id\":$NCR10,\"cancel\":true,\"reason\":\"Re-inspected and accepted\"}"; check "r1q H7: another QC user cancels NCR10 with the reason, so nothing stays open" '.success and .data.status == 4'
ncr "{\"source\":2,\"severity\":1,\"itemId\":$BOLT,\"quantity\":1,\"workOrderId\":$WO2,\"disposition\":4,\"description\":\"Thread stripped, not repairable\",\"causeCategory\":1,\"rootCause\":\"Over-torque\",\"correctiveAction\":\"Torque value in the assembly instruction\"}"; NCR6=$(val .data.id)
approve3 "$NCR6"
as "$QC_TOKEN" POST inventory/quality/ncr/execute "{\"id\":$NCR6}"; nomsg "r1q D5: a workshop scrap is not executed without a scrap receipt" "با رسید ضایعات تاییدشده"
call POST inventory/documents "{\"type\":13,\"documentDate\":\"${D0}T00:00:00\",\"warehouseId\":$WS,\"lines\":[{\"itemId\":$BOLT,\"quantity\":1}]}"; WR1=$(val .data.id)
as "$QC_TOKEN" POST inventory/quality/ncr/execute "{\"id\":$NCR6,\"scrapDocumentId\":$WR1}"; nomsg "r1q D5: a scrap receipt that is only a draft proves nothing" "رسید ضایعات هنوز تایید نشده است"
call POST "inventory/documents/$WR1/confirm"; check "r1q D5: the scrap receipt of one bolt is confirmed" '.success and (.data.number|startswith("WR-"))'
as "$QC_TOKEN" POST inventory/quality/ncr/execute "{\"id\":$NCR6,\"scrapDocumentId\":$WR1}"; check "r1q D5: executed with the confirmed scrap receipt, which stays linked to the NCR" ".success and .data.status == 2 and .data.scrapDocumentId == $WR1"
ncr "{\"source\":2,\"severity\":1,\"itemId\":$BOLT,\"quantity\":1,\"workOrderId\":$WO2,\"disposition\":4,\"description\":\"Second stripped bolt\",\"causeCategory\":1,\"rootCause\":\"Over-torque\",\"correctiveAction\":\"Torque value in the assembly instruction\"}"; NCR7=$(val .data.id)
approve3 "$NCR7"
as "$QC_TOKEN" POST inventory/quality/ncr/execute "{\"id\":$NCR7,\"scrapDocumentId\":$WR1}"; nomsg "r1q D5: one scrap receipt cannot prove two reports" "قبلاً برای گزارش عدم انطباق دیگری ثبت شده است"
call POST inventory/documents "{\"type\":13,\"documentDate\":\"${D0}T00:00:00\",\"warehouseId\":$WS,\"lines\":[{\"itemId\":$BOLT,\"quantity\":1}]}"; WR2=$(val .data.id); call POST "inventory/documents/$WR2/confirm"
as "$QC_TOKEN" POST inventory/quality/ncr/execute "{\"id\":$NCR7,\"scrapDocumentId\":$WR2}"; check "r1q D5: with its own scrap receipt the second report is executed" ".success and .data.status == 2 and .data.scrapDocumentId == $WR2"

# --- D. out-of-tolerance impact (ISO 7.1.5.2)
as "$QC_TOKEN" POST quality/release-notes "{\"workOrderId\":$WO1,\"itemsText\":\"Feed pump unit 1\"}"; nomsg "r1q D10: a release note without a list of items is refused (a delivery may only carry what the released note lists)" "فهرست اقلام برگه ترخیص"
as "$QC_TOKEN" POST quality/release-notes "{\"workOrderId\":$WO1,\"itemsText\":\"Feed pump unit 1\",\"lines\":[{\"itemId\":$ROTOR,\"quantity\":2,\"serialNumbers\":[\"RT-1\"]}]}"; nomsg "r1q D10: a serial item needs one serial number per piece" "سریال قطعات"
# R1q review C1, H4: the lines of a release note are checked against what the work order made or received (a serial number of a piece the work order made, a quantity within its confirmed receipts)
as "$QC_TOKEN" POST quality/release-notes "{\"workOrderId\":$WO1,\"itemsText\":\"Feed pump unit 1\",\"lines\":[{\"itemId\":$ROTOR,\"quantity\":1,\"serialNumbers\":[\"NO-SUCH-SERIAL-1\"]}]}"; nomsg "r1q H4: a serial number the system does not know is refused on a release note line" "در سامانه ثبت نشده است"
call GET "inventory/trace/serial/$RT"; ROTORSN=$(val .data.unit.serialNumber)
as "$QC_TOKEN" POST quality/release-notes "{\"workOrderId\":$WO1,\"itemsText\":\"Feed pump unit 1\",\"lines\":[{\"itemId\":$ROTOR,\"quantity\":1,\"serialNumbers\":[\"$ROTORSN\"]}]}"; nomsg "r1q H4: a rotor that another work order (or none) made cannot be released with this work order" "ساخته یا ثبت نشده است"
as "$QC_TOKEN" POST quality/release-notes "{\"workOrderId\":$WO1,\"itemsText\":\"Feed pump unit 1\",\"lines\":[{\"itemId\":$RAW,\"quantity\":1}]}"; nomsg "r1q H4: an item that this work order never made or received is refused" "رسید ساخت یا رسید خریدی ثبت نشده است"
as "$QC_TOKEN" POST quality/release-notes "{\"workOrderId\":$WO1,\"itemsText\":\"Feed pump unit 1\",\"lines\":[{\"itemId\":$BOLT,\"quantity\":6}]}"; nomsg "r1q H4: six bolts against the five the work order received are refused" "از مقدار ساخته یا دریافت‌شده برای دستور کار (5) بیشتر است"
as "$QC_TOKEN" POST quality/release-notes "{\"workOrderId\":$WO1,\"itemsText\":\"Feed pump unit 1\",\"lines\":[{\"itemId\":$BOLT,\"quantity\":5}]}"; check "release note drafted while points are still open (cannot be released yet); r1q D10: it lists the five bolts it will release" '.success and .data.status == 0 and (.data.number|startswith("RN-")) and .data.canRelease == false and (.data.lines|length) == 1 and .data.lines[0].quantity == 5 and .data.draftedByName != null'
RN1=$(val .data.id)
as "$QC_TOKEN" POST quality/release-notes/action "{\"id\":$RN1,\"action\":\"release\"}"; nomsg "r1q D22: the person who drafted the release note cannot release it (maker-checker)" "کسی که آن را تنظیم یا ویرایش کرده نمی‌تواند صادر کند"
as "$QC2_TOKEN" POST quality/release-notes/action "{\"id\":$RN1,\"action\":\"release\"}"; check "release refused while H/W points and reports are open (computed checks named in the answer; r1q D22: tried by a second QC user, since the drafter is refused before the checks)" '.success == false and (.message|contains("ترخیص ممکن نیست"))'
as "$QC_TOKEN" GET "quality/work-orders/$WO1/release-checks"; check "release checks computed: ITP approved, points still open" '.success and .data.canRelease == false and ([.data.checks[]|select(.code=="ITP_APPROVED")|.passed][0] == true) and ([.data.checks[]|select(.code=="POINTS_DONE")|.passed][0] == false)'
as "$QC_TOKEN" POST quality/reports "{\"type\":12,\"workOrderId\":$WO2,\"equipmentIds\":[$G1],\"values\":[{\"parameter\":\"Flange thickness\",\"unit\":\"mm\",\"min\":19.9,\"max\":20.1,\"measured\":20.02}]}"; check "test report made with instrument G1 (before its failed calibration)" '.success and .data.equipment[0].equipmentId != null'
DRG1=$(val .data.number)
as "$QC_TOKEN" POST quality/equipment/calibration "{\"equipmentId\":$G1,\"eventDate\":\"$D0\",\"labName\":\"Lab A\",\"labAccredited\":true,\"certificateNumber\":\"CAL-G1-2\",\"certificateDocumentId\":\"$DOCID\",\"traceabilityStatement\":\"Traceable to national standard\",\"asFoundPass\":false,\"asLeftPass\":true,\"adjusted\":true}"
check "calibration with a failed as-found: instrument usable again, impact case opened" '.success and .data.status == 0 and .data.events[0].ootCaseId != null and (.data.events[0].ootNumber|startswith("OOT-"))'
call GET "quality/out-of-tolerance?EquipmentId=$G1"; OOT=$(val '.data.data[0].id')
check "case lists every document made with the instrument since the previous good calibration" '.data.data[0].itemCount >= 3 and .data.data[0].pendingCount >= 3 and .data.data[0].status == 0'
call GET "quality/out-of-tolerance/$OOT"; check "the case lists the affected test report and the affected inspection records" "([.data.items[]|select(.sourceKind==\"TestReport\")|.sourceNumber]|index(\"$DRG1\")) != null and ([.data.items[]|select(.sourceKind==\"QcRecord\")]|length) >= 3"
as "$QC_TOKEN" GET "quality/work-orders/$WO1/release-checks"; check "release gate: out-of-tolerance impact of work order 1 not assessed" '[.data.checks[]|select(.code=="OOT_ASSESSED")|.passed][0] == false'
as "$QC_TOKEN" POST quality/out-of-tolerance/close "{\"id\":$OOT}"; nomsg "case cannot be closed while documents are not assessed" "ارزیابی اثر"
call GET "quality/out-of-tolerance/$OOT"
OOT_R1I=$(jq -r ".data.items[]|select(.sourceNumber==\"$R1NUM\")|.id" "$B"); OOT_R2I=$(jq -r ".data.items[]|select(.sourceNumber==\"$R2NUM\")|.id" "$B")
# the dimensional record R1 is assessed "re-inspect" (R1q D40: a task, not a tick); the record with an item gets its NCR; the rest have no impact
for IID in $(jq -r '.data.items[].id' "$B"); do
  SRC=$(jq -r ".data.items[]|select(.id==$IID)|.sourceNumber" "$B")
  if [ "$SRC" = "$R2NUM" ]; then AS=3; elif [ "$SRC" = "$R1NUM" ]; then AS=2; else AS=1; fi
  as "$QC_TOKEN" POST quality/out-of-tolerance/assess "{\"itemId\":$IID,\"assessment\":$AS,\"note\":\"assessed in the smoke test\"}"
done
as "$QC_TOKEN" POST quality/out-of-tolerance/assess "{\"itemId\":$IID,\"assessment\":1}"; no "assessment needs a written note"
call GET "quality/out-of-tolerance/$OOT"; check "every item assessed; the one with an item got its NCR drafted" "(.data.pendingCount == 0) and ([.data.items[]|select(.sourceNumber==\"$R2NUM\")|.ncrNumber|startswith(\"NCR-\")][0] == true)"
as "$QC_TOKEN" POST quality/out-of-tolerance/close "{\"id\":$OOT,\"note\":\"closed\"}"; nomsg "r1q D40: the case does not close while the document assessed as re-inspect has no accepted re-inspection linked to it (this check was a plain close before)" "هنوز بازرسی مجدد قبول‌شده‌ای پیوند نشده است"
as "$QC2_TOKEN" GET "office/inbox?SourceKey=oot-reinspect:$OOT_R1I"; check "r1q D40: the re-inspection is a task in the QC inbox, due in 7 days" ".success and (.data.data|length) == 1 and .data.data[0].recipientRole == \"QC\" and (.data.data[0].dueDate[0:10]) == \"$(dd 7)\" and (.data.data[0].title|contains(\"$R1NUM\")) and .data.data[0].link == \"/quality/out-of-tolerance/$OOT\""
as "$QC_TOKEN" GET "quality/work-orders/$WO1/release-checks"; check "r1q D40: the release gate of the work order stays closed while the re-inspection is outstanding (before: it passed after the assessments)" '.success and ([.data.checks[]|select(.code=="OOT_ASSESSED")|.passed][0] == false) and ([.data.checks[]|select(.code=="OOT_ASSESSED")|.detail][0]|contains("بازرسی مجدد"))'
as "$QC_TOKEN" POST quality/out-of-tolerance/reinspection "{\"itemId\":$OOT_R1I,\"kind\":\"QcRecord\",\"recordId\":$R1}"; nomsg "r1q D40: the document itself, made with the same instrument, is not its own re-inspection" "این سند خودش از اسناد پرونده است"
as "$QC_TOKEN" POST quality/out-of-tolerance/reinspection "{\"itemId\":$OOT_R1I,\"kind\":\"Foo\",\"recordId\":$R1}"; nomsg "r1q D40: an unknown kind of re-inspection is refused" "نوع بازرسی مجدد نامعتبر است"
as "$QC_TOKEN" GET "quality/records/$R1"; R1ITEM=$(val '.data.itemId // empty')
RIBODY=$(jq -nc --argjson wo "$WO1" --argjson eq "$G4" --arg item "$R1ITEM" '{type:3,workOrderId:$wo,quantity:1,result:1,measurements:[{characteristic:"Bore",nominal:100,tolPlus:0.05,tolMinus:0.05,measured:100.01,unit:"mm",equipmentId:$eq}]} + (if $item != "" then {itemId:($item|tonumber)} else {} end)')
as "$QC_TOKEN" POST quality/records "$RIBODY"; check "r1q D40: the bore is measured again with the calibrated reference caliper G4 and accepted" '.success and .data.result == 1 and (.data.number|startswith("QIR-"))'
RI1=$(val .data.id)
as "$QC_TOKEN" POST quality/out-of-tolerance/reinspection "{\"itemId\":$OOT_R2I,\"kind\":\"QcRecord\",\"recordId\":$RI1}"; nomsg "r1q D40: a re-inspection is linked only to a document assessed as re-inspect (the one with the NCR is refused)" "ارزیابی آن «بازرسی مجدد» است"
as "$QC_TOKEN" POST quality/out-of-tolerance/reinspection "{\"itemId\":$OOT_R1I,\"kind\":\"QcRecord\",\"recordId\":$RI1}"; check "r1q D40: the new accepted record is linked as the re-inspection of R1 (kind and record kept on the row)" ".success and ([.data.items[]|select(.id == $OOT_R1I)|.reinspectionRecordId][0] == $RI1) and ([.data.items[]|select(.id == $OOT_R1I)|.reinspectionKind][0] == \"QcRecord\") and ([.data.items[]|select(.id == $OOT_R1I)|.reinspectionNumber][0]|startswith(\"QIR-\"))"
as "$QC2_TOKEN" GET "office/inbox?SourceKey=oot-reinspect:$OOT_R1I"; check "r1q D40: the re-inspection task leaves the inbox once it is linked" '.success and (.data.data|length) == 0'
as "$QC_TOKEN" POST quality/out-of-tolerance/close "{\"id\":$OOT,\"note\":\"closed\"}"; check "case closed after the assessments and the linked re-inspection" '.success and .data.status == 1'
as "$QC_TOKEN" GET "quality/work-orders/$WO1/release-checks"; check "release gate: OOT check passes after the assessments and the re-inspection" '[.data.checks[]|select(.code=="OOT_ASSESSED")|.passed][0] == true'

# --- E. test reports: limits, qualified examiners, segregation
as "$QC_TOKEN" GET quality/reports/standards/1; check "PT standard rows: dwell time maximum 10 min as printed, no invented minimum" '.success and ([.data[]|select(.name=="Dwell time")|.max][0] == 10) and ([.data[]|select(.name=="Dwell time")|.min][0] == null) and ([.data[]|select(.mandatory)]|length) >= 4'
as "$QC_TOKEN" GET quality/reports/standards/7; check "hydro standard rows have no limits (engineering sets them)" '.success and ([.data[]|.requiresLimits]|all)'
as "$QC_TOKEN" GET quality/reports/standards/8; check "run test overspeed trip limits 107.8 - 112.2" '[.data[]|select(.name=="Overspeed trip 1")][0] as $t | $t.min == 107.8 and $t.max == 112.2'
# NDT personnel: a person with several certificates
as "$QA_TOKEN" POST quality/persons '{"name":"NDT Examiner","personnelCode":"N-001","employer":1,"stampId":"N1"}'; check "NDT person registered" '.success and .data.id > 0'
NP=$(val .data.id)
as "$WH_TOKEN" POST quality/persons '{"name":"x","employer":1}'; no "warehouse cannot register qualified persons"
qual() { as "$QA_TOKEN" POST quality/qualifications "$1"; }
qual "{\"personId\":$NP,\"kind\":3,\"method\":\"PT\",\"level\":2,\"scheme\":2,\"certificateNumber\":\"PT-L2\",\"issuedDate\":\"$(dd -100)\",\"expiryDate\":\"$(dd 300)\",\"certificateDocumentId\":\"$DOCID\"}"; check "NDT qualification PT level II registered" '.success and .data.state == 0'
QPT2=$(val .data.id)
qual "{\"personId\":$NP,\"kind\":3,\"method\":\"PT\",\"level\":1,\"scheme\":2,\"certificateNumber\":\"PT-L1\",\"issuedDate\":\"$(dd -100)\",\"expiryDate\":\"$(dd 300)\"}"; QPT1=$(val .data.id)
qual "{\"personId\":$NP,\"kind\":3,\"method\":\"PT\",\"level\":2,\"scheme\":2,\"certificateNumber\":\"PT-OLD\",\"issuedDate\":\"$(dd -800)\",\"expiryDate\":\"$(dd -10)\"}"; check "expired certificate is stored as expired (computed)" '.success and .data.state == 2'
QPTX=$(val .data.id)
qual "{\"personId\":$NP,\"kind\":3,\"method\":\"MT\",\"level\":2,\"scheme\":2,\"certificateNumber\":\"MT-L2\",\"issuedDate\":\"$(dd -100)\",\"expiryDate\":\"$(dd 300)\"}"; QMT2=$(val .data.id)
qual "{\"personId\":$NP,\"kind\":3,\"method\":\"PT\",\"level\":2,\"certificateNumber\":\"PT-NOSCHEME\",\"scheme\":9,\"issuedDate\":\"$(dd -10)\"}"; no "NDT certificate needs ASNT SNT-TC-1A or ISO 9712 scheme"
pt_values() { jq -nc --argjson t "$1" --argjson d "$2" '[{parameter:"Part and penetrant temperature",unit:"°C",measured:$t},{parameter:"Dwell time",unit:"min",measured:$d},{parameter:"Interpretation time after developer",unit:"min",measured:20},{parameter:"White light intensity",unit:"lux",measured:1200}]'; }
pt_report() { # pt_report QUALIFICATIONID TEMP DWELL [ITEMID]
  jq -nc --argjson q "$1" --argjson wo "$WO2" --argjson v "$(pt_values "$2" "$3")" --argjson eq "$G4" --arg item "${4:-}" \
    '{type:1,workOrderId:$wo,examinerQualificationId:$q,procedureRef:"WI-QC-004",codeEdition:"ASME V 2023",values:$v,equipmentIds:[$eq]} + (if $item != "" then {itemId:($item|tonumber)} else {} end)'
}
as "$QC_TOKEN" POST quality/reports "$(pt_report "$QPT1" 25 8)"; check "PT report saved as draft (level I examiner)" '.success and .data.status == 0 and (.data.problems|length) > 0'
PR1=$(val .data.id)
as "$QC_TOKEN" POST quality/reports/action "{\"id\":$PR1,\"action\":\"submit\"}"; nomsg "PT report by a level I examiner cannot be submitted" "سطح"
as "$QC_TOKEN" POST quality/reports "$(pt_report "$QPTX" 25 8)"; PR2=$(val .data.id)
as "$QC_TOKEN" POST quality/reports/action "{\"id\":$PR2,\"action\":\"submit\"}"; nomsg "PT report with an expired certificate cannot be submitted" "منقضی"
as "$QC_TOKEN" POST quality/reports "$(pt_report "$QMT2" 25 8)"; PR3=$(val .data.id)
as "$QC_TOKEN" POST quality/reports/action "{\"id\":$PR3,\"action\":\"submit\"}"; nomsg "PT report with an MT certificate cannot be submitted (method mismatch)" "خوان نیست"
as "$QC_TOKEN" POST quality/reports "$(pt_report "$QPT2" 25 8)"; check "PT report with a valid level II examiner has no problems; pass computed by the server" '.success and (.data.problems|length) == 0 and ([.data.values[]|.pass]|all(. == true))'
PR4=$(val .data.id)
as "$ENG_TOKEN" POST quality/reports/action "{\"id\":$PR4,\"action\":\"submit\"}"; no "only QC submits a report"
as "$QC_TOKEN" POST quality/reports/action "{\"id\":$PR4,\"action\":\"submit\"}"; check "PT report submitted; result Pass" '.success and .data.status == 1 and .data.result == 1'
as "$QC_TOKEN" POST quality/reports/action "{\"id\":$PR4,\"action\":\"approve\"}"; nomsg "the examiner cannot approve his own report (segregation of duties)" "تفکیک وظایف"
as "$QC2_TOKEN" POST quality/reports/action "{\"id\":$PR4,\"action\":\"approve\"}"; check "second QC approves the PT report" '.success and .data.status == 2 and .data.approvedByName != null'
as "$QC_TOKEN" POST quality/reports "$(pt_report "$QPT2" 25 8 | jq -c --argjson id "$PR4" '. + {id:$id}')"; nomsg "an approved report cannot be edited" "قابل ویرایش نیست"
# a failing PT (dwell 11 min > 10): needs an item to draft the NCR, the server computes Fail
as "$QC_TOKEN" POST quality/reports "$(pt_report "$QPT2" 25 11)"; check "dwell time 11 min computes Fail" '.success and ([.data.values[]|select(.parameter=="Dwell time")|.pass][0] == false)'
PR5=$(val .data.id)
as "$QC_TOKEN" POST quality/reports/action "{\"id\":$PR5,\"action\":\"submit\"}"; no "failed report without an item (no NCR possible) cannot be submitted"
# r1q M15: a draft report is judged by the date it was entered with: the date stays unless a new one is typed, and a new date still has to fit the window
as "$QC_TOKEN" POST quality/reports "$(pt_report "$QPT2" 25 11 | jq -c --argjson id "$PR5" --arg d "$(dd -3)" '. + {id:$id,reportDate:$d}')"; check "r1q M15: a draft test report can be re-dated three days back (inside the back-date window)" ".success and .data.status == 0 and (.data.reportDate|startswith(\"$(dd -3)\"))"
as "$QC_TOKEN" POST quality/reports "$(pt_report "$QPT2" 25 11 | jq -c --argjson id "$PR5" '. + {id:$id}')"; check "r1q M15: saved again without a date the draft keeps the date it was entered with (it is not moved to today)" ".success and .data.status == 0 and (.data.reportDate|startswith(\"$(dd -3)\"))"
as "$QC_TOKEN" POST quality/reports "$(pt_report "$QPT2" 25 11 | jq -c --argjson id "$PR5" --arg d "$(dd -9)" '. + {id:$id,reportDate:$d}')"; nomsg "r1q M15: a new date older than the back-date window (9 days back) is refused for a draft too" "ثبت با تاخیر بیش از 7 روز مجاز نیست"
as "$QC_TOKEN" POST quality/reports "$(pt_report "$QPT2" 25 11 $BOLT)"; PR6=$(val .data.id)
as "$QC_TOKEN" POST quality/reports/action "{\"id\":$PR6,\"action\":\"submit\"}"; check "failed report submitted: NCR drafted automatically" '.success and .data.result == 2 and .data.ncrId != null and (.data.ncrNumber|startswith("NCR-"))'
# run test limits and mandatory rows
as "$QC_TOKEN" POST quality/reports "{\"type\":8,\"workOrderId\":$WO2,\"itemId\":$BOLT,\"values\":[{\"parameter\":\"Overspeed trip 1\",\"measured\":109}]}"; RT1=$(val .data.id)
as "$QC_TOKEN" POST quality/reports/action "{\"id\":$RT1,\"action\":\"submit\"}"; check "run test without the mandatory rows cannot be submitted" '.success == false and (.message|contains("Overspeed trip 2"))'
as "$QC_TOKEN" POST quality/reports "{\"type\":8,\"workOrderId\":$WO2,\"itemId\":$BOLT,\"values\":[{\"parameter\":\"Overspeed trip 1\",\"measured\":109},{\"parameter\":\"Overspeed trip 2\",\"measured\":110},{\"parameter\":\"Overspeed trip 3\",\"measured\":113},{\"parameter\":\"Continuous run duration\",\"measured\":5}]}"
check "overspeed 113 % is outside 107.8 - 112.2 -> Fail" '.success and ([.data.values[]|select(.parameter=="Overspeed trip 3")|.pass][0] == false)'
as "$QC_TOKEN" POST quality/reports "{\"type\":8,\"itpActivityId\":$A3,\"values\":[]}"; no "report type must match the ITP activity (hydro activity needs a hydro report)"
as "$QC_TOKEN" POST quality/reports "{\"type\":7,\"itpActivityId\":$A3,\"values\":[],\"equipmentIds\":[$G2]}"; no "report with an overdue instrument rejected"

# hydro test on the pump: limits come only from engineering
HYD=$(jq -nc --argjson a "$A3" --argjson pg "$PG1" '{type:7,itpActivityId:$a,procedureRef:"API 610 8.3",values:[{parameter:"Test pressure",unit:"bar",measured:16.5},{parameter:"Hold time",unit:"min",measured:35}],equipmentIds:[$pg]}')
as "$QC_TOKEN" POST quality/reports "$HYD"; check "hydro report: test pressure has no limit yet (unknown, not invented)" '.success and ([.data.values[]|select(.parameter=="Test pressure")|.requiresLimits][0] == true) and ([.data.values[]|select(.parameter=="Test pressure")|.pass][0] == null) and (.data.problems|length) > 0'
HR=$(val .data.id); HRV=$(val .data.rowVersion)
as "$QC_TOKEN" POST quality/reports/action "{\"id\":$HR,\"action\":\"submit\"}"; nomsg "hydro report cannot be submitted without engineering limits" "حدود پذیرش"
as "$QC_TOKEN" POST quality/itps/limits "{\"parameterId\":$P_TESTP,\"min\":15,\"max\":18,\"source\":\"x\"}"; no "QC cannot set acceptance limits (engineering decides)"
as "$ENG_TOKEN" POST quality/itps/limits "{\"parameterId\":$P_TESTP,\"min\":15,\"source\":\"MAWP 11 bar x 1.5 = 16.5 (datasheet DS-77)\"}"; check "engineering sets the limit on the ITP" ".success and ([.data.activities[]|select(.id==$A3)|.parameters[]|select(.name==\"Test pressure\")|.min][0] == 15)"
as "$ENG_TOKEN" POST quality/itps/limits "{\"parameterId\":$P_TESTP,\"min\":20,\"max\":10}"; nomsg "inverted limits rejected" "بیشتر است"
as "$QC_TOKEN" POST quality/reports "$(echo "$HYD" | jq -c --argjson id "$HR" --arg rv "$HRV" '. + {id:$id,rowVersion:$rv}')"; check "report re-evaluated against the engineering limit: Pass" '.success and (.data.problems|length) == 0 and ([.data.values[]|select(.parameter=="Test pressure")|.pass][0] == true)'
as "$ENG_TOKEN" POST quality/itps/limits "{\"parameterId\":$P_TESTP,\"min\":15,\"max\":18,\"source\":\"MAWP 11 bar x 1.5 = 16.5 (datasheet DS-77)\"}"

# --- A (continued). real completion of plan 1: release rows, the witness notice, reports that complete the activity
# The approved plan keeps the notice period of 10 days (R1q review H6: the company minimum is 1 day and a plan can no longer be agreed at 0), so no witness point is waived by notice in
# this scenario; every W point gets a real release row. The waiver by notice (period passed, notice date from a letter) is tested on plan 2 after the Office letters exist.
as "$QC_TOKEN" POST quality/itps/activity/action "{\"id\":$A2,\"action\":\"done\"}"; check "activity 2: done refused (vendor H, TPI W notice and report missing)" '.success == false and (.message|contains("H"))'
as "$QC_TOKEN" POST quality/itps/release "{\"activityId\":$A2,\"party\":1,\"action\":1,\"personName\":\"Vendor QC\",\"reference\":\"V-REL-2\"}"; check "activity 2 vendor H release" '.success'
as "$QC_TOKEN" POST quality/itps/activity/action "{\"id\":$A2,\"action\":\"done\"}"; check "activity 2: W point needs the witness notice; the report is still missing" '.success == false and (.message|contains("W"))'
as "$QC_TOKEN" POST quality/itps/activity/action "{\"id\":$A2,\"action\":\"notify\",\"date\":\"$(dd -12)\"}"; nomsg "r1q D9: a typed past notice date is refused (the notice date is the server day or a signed outgoing letter)" "عقب‌تر از امروز"
as "$QC_TOKEN" POST quality/itps/activity/action "{\"id\":$A2,\"action\":\"notify\"}"; check "witness notice recorded with the server date; the deadline is the notice period of the approved plan (10 days) later" ".success and ([.data.activities[]|select(.id==$A2)|.status][0] == 1) and ([.data.activities[]|select(.id==$A2)|.notificationSentAt[0:10]][0] == \"$D0\") and ([.data.activities[]|select(.id==$A2)|.witnessDeadline[0:10]][0] == \"$(dd 10)\")"
as "$QC_TOKEN" POST quality/itps/activity/action "{\"id\":$A2,\"action\":\"done\"}"; check "r1q H6: the notice period has not passed, so the witness point is not waived by notice" '.success == false and (.message|contains("W"))'
as "$QC_TOKEN" POST quality/itps/release "{\"activityId\":$A2,\"party\":2,\"action\":1,\"personName\":\"TPI Inspector\",\"organisation\":\"TPI Co\",\"reference\":\"TPI-W-2\"}"; check "activity 2: the TPI inspector attends the witness point (release row)" '.success'
as "$QC_TOKEN" POST quality/itps/activity/action "{\"id\":$A2,\"action\":\"done\"}"; check "report still required for activity 2" '.success == false'
DIMV=$(jq -nc --argjson a "$A2" --argjson e "$G4" '{type:12,itpActivityId:$a,equipmentIds:[$e],values:[{parameter:"Bore diameter",unit:"mm",min:99.95,max:100.05,measured:100.01}]}')
as "$QC_TOKEN" POST quality/reports "$DIMV"; DR=$(val .data.id)
as "$QC_TOKEN" POST quality/reports/action "{\"id\":$DR,\"action\":\"submit\"}"; check "dimensional report submitted" '.success and .data.result == 1'
as "$QC2_TOKEN" POST quality/reports/action "{\"id\":$DR,\"action\":\"approve\"}"; check "approved by the second QC" '.success and .data.status == 2'
as "$QC_TOKEN" GET "quality/itps/$ITP1"; check "approved passing report completes activity 2 with the real release rows of the vendor and the TPI (nothing waived by notice)" "([.data.activities[]|select(.id==$A2)|.status][0] == 2) and ([.data.activities[]|select(.id==$A2)|.releases[]|select(.waivedByNotice)]|length) == 0 and ([.data.activities[]|select(.id==$A2)|.releases[]]|length) == 2"
# activity 3 (hydro, H/H/W): both H releases, the client's witness release and the report
as "$QC_TOKEN" POST quality/reports/action "{\"id\":$HR,\"action\":\"submit\"}"; check "hydro report submitted" '.success and .data.status == 1 and .data.result == 1'
as "$QC2_TOKEN" POST quality/reports/action "{\"id\":$HR,\"action\":\"approve\"}"; check "hydro report approved" '.success and .data.status == 2'
as "$QC_TOKEN" GET "quality/itps/$ITP1"; check "approved report alone does not finish the activity: H points of vendor and TPI are open" "([.data.activities[]|select(.id==$A3)|.status][0] != 2) and ([.data.activities[]|select(.id==$A3)|.blockers|length][0] >= 2)"
as "$QC_TOKEN" POST quality/itps/release "{\"activityId\":$A3,\"party\":1,\"action\":1,\"personName\":\"Vendor QC\",\"reference\":\"V-REL-3\"}"; check "vendor H release on the hydro test" '.success'
as "$QC_TOKEN" POST quality/itps/activity/action "{\"id\":$A3,\"action\":\"notify\"}"; check "witness notice of the hydro test recorded" ".success and ([.data.activities[]|select(.id==$A3)|.status][0] == 1)"
as "$QC_TOKEN" POST quality/itps/release "{\"activityId\":$A3,\"party\":2,\"action\":1,\"personName\":\"TPI Inspector\",\"organisation\":\"TPI Co\",\"reference\":\"TPI-REL-3\"}"; check "TPI H release recorded; the client's witness point is still open (10 days of notice, no waiver)" ".success and ([.data.activities[]|select(.id==$A3)|.status][0] != 2)"
as "$QC_TOKEN" POST quality/itps/release "{\"activityId\":$A3,\"party\":3,\"action\":1,\"personName\":\"Client representative\",\"organisation\":\"Client Co\",\"reference\":\"CL-W-3\"}"
check "client W release completes the hydro activity (every point has a real release row)" ".success and ([.data.activities[]|select(.id==$A3)|.status][0] == 2) and ([.data.activities[]|select(.id==$A3)|.releases[]|select(.waivedByNotice)]|length) == 0"
# activity 4 (mechanical running test, H/W/W): engineering sets the two limits the pump template leaves open, and the report names the instrument that measured them
as "$QC_TOKEN" GET "quality/itps/$ITP1"
P_VIB=$(val ".data.activities[]|select(.id==$A4)|.parameters[]|select(.name==\"Vibration\")|.id"); P_BRG=$(val ".data.activities[]|select(.id==$A4)|.parameters[]|select(.name==\"Bearing temperature\")|.id")
RUNV=$(jq -nc --argjson a "$A4" --argjson e "$G4" '{type:8,itpActivityId:$a,equipmentIds:[$e],values:[{parameter:"Overspeed trip 1",measured:109},{parameter:"Overspeed trip 2",measured:110},{parameter:"Overspeed trip 3",measured:111},{parameter:"Continuous run duration",measured:5},{parameter:"Vibration",unit:"mm/s",measured:3.2},{parameter:"Bearing temperature",unit:"°C",measured:71}]}')
as "$QC_TOKEN" POST quality/reports "$RUNV"; check "run test report of activity 4: vibration and bearing temperature have no limit yet (unknown, not invented)" '.success and ([.data.values[]|select(.parameter=="Vibration")|.requiresLimits][0] == true) and ([.data.values[]|select(.parameter=="Vibration")|.pass][0] == null) and (.data.problems|length) > 0'
RUNR=$(val .data.id); RUNRV=$(val .data.rowVersion)
as "$QC_TOKEN" POST quality/reports/action "{\"id\":$RUNR,\"action\":\"submit\"}"; nomsg "run test report cannot be submitted without the engineering limits" "حدود پذیرش"
as "$ENG_TOKEN" POST quality/itps/limits "{\"parameterId\":$P_VIB,\"max\":4.5,\"source\":\"API 610 8.3.4: 4.5 mm/s (datasheet DS-77)\"}"; check "engineering sets the vibration limit" ".success and ([.data.activities[]|select(.id==$A4)|.parameters[]|select(.name==\"Vibration\")|.max][0] == 4.5)"
as "$ENG_TOKEN" POST quality/itps/limits "{\"parameterId\":$P_BRG,\"max\":85,\"source\":\"API 610 8.3.4: 85 degC (datasheet DS-77)\"}"; check "engineering sets the bearing temperature limit" ".success and ([.data.activities[]|select(.id==$A4)|.parameters[]|select(.name==\"Bearing temperature\")|.max][0] == 85)"
as "$QC_TOKEN" POST quality/reports "$(echo "$RUNV" | jq -c --argjson id "$RUNR" --arg rv "$RUNRV" '. + {id:$id,rowVersion:$rv}')"; check "run test report re-evaluated against the engineering limits and the fixed overspeed limits: Pass" '.success and (.data.problems|length) == 0 and ([.data.values[]|.pass]|all(. == true))'
as "$QC_TOKEN" POST quality/reports/action "{\"id\":$RUNR,\"action\":\"submit\"}"; check "run test report submitted; result Pass" '.success and .data.status == 1 and .data.result == 1'
as "$QC2_TOKEN" POST quality/reports/action "{\"id\":$RUNR,\"action\":\"approve\"}"; check "run test report approved by the second QC" '.success and .data.status == 2'
as "$QC_TOKEN" GET "quality/itps/$ITP1"; check "approved report alone does not finish activity 4: the vendor H and the two witness points have no release yet" "([.data.activities[]|select(.id==$A4)|.status][0] != 2) and ([.data.activities[]|select(.id==$A4)|.blockers|length][0] >= 3)"
as "$QC_TOKEN" POST quality/itps/release "{\"activityId\":$A4,\"party\":1,\"action\":1,\"personName\":\"Vendor QC\",\"reference\":\"V-REL-4\"}"; check "vendor H release on the running test" '.success'
as "$QC_TOKEN" POST quality/itps/activity/action "{\"id\":$A4,\"action\":\"notify\"}"; check "witness notice of the running test recorded" ".success and ([.data.activities[]|select(.id==$A4)|.status][0] == 1)"
as "$QC_TOKEN" POST quality/itps/release "{\"activityId\":$A4,\"party\":2,\"action\":1,\"personName\":\"TPI Inspector\",\"organisation\":\"TPI Co\",\"reference\":\"TPI-W-4\"}"; check "TPI witness release on the running test" '.success'
as "$QC_TOKEN" POST quality/itps/release "{\"activityId\":$A4,\"party\":3,\"action\":1,\"personName\":\"Client representative\",\"organisation\":\"Client Co\",\"reference\":\"CL-W-4\"}"
check "client witness release completes the running test (real rows, nothing waived)" ".success and ([.data.activities[]|select(.id==$A4)|.status][0] == 2) and ([.data.activities[]|select(.id==$A4)|.releases[]|select(.waivedByNotice)]|length) == 0"
# activity 5 (performance and NPSH test, H/W/W): no fixed limits, the inspector types the limits of each row
PERFV=$(jq -nc --argjson a "$A5" --argjson e "$G4" '{type:9,itpActivityId:$a,equipmentIds:[$e],values:[{parameter:"Head",unit:"m",min:95,max:105,measured:100.4},{parameter:"Flow",unit:"m3/h",min:190,max:210,measured:201},{parameter:"NPSH required",unit:"m",max:4.5,measured:3.9}]}')
as "$QC_TOKEN" POST quality/reports "$PERFV"; check "performance report with the limits typed per row: Pass computed by the server" '.success and (.data.problems|length) == 0 and ([.data.values[]|.pass]|all(. == true))'
PERFR=$(val .data.id)
as "$QC_TOKEN" POST quality/reports/action "{\"id\":$PERFR,\"action\":\"submit\"}"; check "performance report submitted" '.success and .data.status == 1 and .data.result == 1'
as "$QC2_TOKEN" POST quality/reports/action "{\"id\":$PERFR,\"action\":\"approve\"}"; check "performance report approved by the second QC" '.success and .data.status == 2'
for PARTY in 1 2 3; do
  as "$QC_TOKEN" POST quality/itps/release "{\"activityId\":$A5,\"party\":$PARTY,\"action\":1,\"personName\":\"Release person $PARTY\",\"organisation\":\"Party $PARTY\",\"reference\":\"REL-5-$PARTY\"}"
done
check "the third release completes the performance test (vendor H, TPI W and client W all have release rows)" ".success and ([.data.activities[]|select(.id==$A5)|.status][0] == 2) and ([.data.activities[]|select(.id==$A5)|.releases[]]|length) == 3"
as "$QC_TOKEN" GET "quality/itps/pending-points?WorkOrderId=$WO1"; check "pending points list holds the packing H point only" "(.data.data|length) == 1 and .data.data[0].itemNo == \"6\""

# --- F. welding: WPS/PQR approvals, welder qualification and 6-month continuity (ASME IX QW-322)
call POST quality/pqrs "{\"number\":\"PQR-001\",\"process\":\"GTAW\",\"codeEdition\":\"ASME IX 2023\",\"resultsDocumentId\":\"$DOCID\"}"; check "PQR drafted by planning/PMO" '.success and .data.approved == false'
PQR1=$(val .data.id)
as "$ENG_TOKEN" POST quality/pqrs/action "{\"id\":$PQR1,\"action\":\"approve\"}"; check "PQR approved by engineering (not its creator)" '.success and .data.approved == true'
as "$ENG_TOKEN" POST quality/pqrs "{\"number\":\"PQR-002\",\"process\":\"GTAW\"}"; PQR2=$(val .data.id)
as "$ENG_TOKEN" POST quality/pqrs/action "{\"id\":$PQR2,\"action\":\"approve\"}"; nomsg "engineer cannot approve a PQR he created" "تفکیک وظایف"
call POST quality/wps "{\"number\":\"WPS-001\",\"revision\":\"0\",\"process\":\"GTAW\",\"basePNo\":\"P-1\",\"preheatMinC\":100,\"interpassMaxC\":250,\"pqrIds\":[$PQR2]}"; WPSX=$(val .data.id)
as "$QC_TOKEN" POST quality/wps/action "{\"id\":$WPSX,\"action\":\"approve-qc\"}"; nomsg "WPS without an approved PQR cannot be approved" "PQR تاییدشده"
call POST quality/wps "{\"number\":\"WPS-002\",\"revision\":\"0\",\"process\":\"GTAW\",\"basePNo\":\"P-1\",\"preheatMinC\":100,\"interpassMaxC\":250,\"pqrIds\":[$PQR1]}"; check "WPS drafted" '.success and .data.status == 0'
WPS1=$(val .data.id)
as "$ENG_TOKEN" POST quality/wps/action "{\"id\":$WPS1,\"action\":\"approve-qc\"}"; no "engineering cannot give the QC approval"
as "$QC_TOKEN" POST quality/wps/action "{\"id\":$WPS1,\"action\":\"approve-engineering\"}"; no "QC cannot give the engineering approval"
as "$QC_TOKEN" POST quality/wps/action "{\"id\":$WPS1,\"action\":\"approve-qc\"}"; check "QC approval recorded; WPS still not approved" '.success and .data.status == 0 and .data.qcApprovedAt != null'
as "$QC_TOKEN" POST quality/weld-logs "{\"weldDate\":\"$D0\",\"workOrderId\":$WO2,\"jointNo\":\"J-0\",\"wpsId\":$WPS1,\"qualificationId\":$QPT2,\"vt\":1}"; nomsg "weld log against a WPS with only one approval rejected" "تایید نهایی"
as "$ENG_TOKEN" POST quality/wps/action "{\"id\":$WPS1,\"action\":\"approve-engineering\"}"; check "WPS approved after the second, different approver" '.success and .data.status == 1'
# a WPS created by engineering cannot be approved by engineering
as "$ENG_TOKEN" POST quality/wps "{\"number\":\"WPS-003\",\"revision\":\"0\",\"process\":\"GTAW\",\"pqrIds\":[$PQR1]}"; WPS3=$(val .data.id)
as "$QC_TOKEN" POST quality/wps/action "{\"id\":$WPS3,\"action\":\"approve-qc\"}"
as "$ENG_TOKEN" POST quality/wps/action "{\"id\":$WPS3,\"action\":\"approve-engineering\"}"; nomsg "creator of a WPS cannot approve it (segregation of duties)" "تفکیک وظایف"

wperson() { as "$QA_TOKEN" POST quality/persons "{\"name\":\"$1\",\"personnelCode\":\"$2\",\"employer\":1,\"stampId\":\"$3\"}"; val .data.id; }
addmonths() { # addmonths YYYY-MM-DD N: the same day N months later, the last day of that month when it has no such day (the rule of AddMonths on the server)
  local y=${1:0:4} m=${1:5:2} d=${1:8:2} t last
  t=$(( 10#$y * 12 + 10#$m - 1 + $2 )); y=$(( t / 12 )); m=$(( t % 12 + 1 ))
  last=$(date -d "$(printf '%04d-%02d-01' $y $m) +1 month -1 day" +%d)
  [ $((10#$d)) -gt $((10#$last)) ] && d=$last
  printf '%04d-%02d-%02d' $y $m $((10#$d))
}
wqual() { # wqual PERSON NUMBER METHOD ISSUED-DAYS-AGO
  as "$QA_TOKEN" POST quality/qualifications "{\"personId\":$1,\"kind\":1,\"method\":\"$3\",\"scheme\":1,\"scope\":\"P-1 plate\",\"certificateNumber\":\"$2\",\"issuedDate\":\"$(dd -$4)\",\"certificateDocumentId\":\"$DOCID\"}"; val .data.id; }
WP1=$(wperson "Welder One" W-001 W11); QW1=$(wqual $WP1 WQ-1 GTAW 30)
WP2=$(wperson "Welder Two" W-002 W12); QW2=$(wqual $WP2 WQ-2 GTAW 300)
WP3=$(wperson "Welder Three" W-003 W13); QW3=$(wqual $WP3 WQ-3 GTAW 300)
WP4=$(wperson "Welder Four" W-004 W14); QW4=$(wqual $WP4 WQ-4 GTAW 170)
WP5=$(wperson "Welder Five" W-005 W15); QW5=$(wqual $WP5 WQ-5 SMAW 10)
WP6=$(wperson "Welder Six" W-006 W16); QW6=$(wqual $WP6 WQ-6 GTAW 10)
call GET "quality/qualifications?PersonId=$WP2"; check "welder without welding for more than six months is lapsed (computed)" '.data.data[0].state == 3 and .data.data[0].lapsesOn != null'
weld() { # weld DATE JOINT QUAL [PREHEAT INTERPASS]
  as "$QC_TOKEN" POST quality/weld-logs "{\"weldDate\":\"$1\",\"workOrderId\":$WO2,\"jointNo\":\"$2\",\"wpsId\":$WPS1,\"qualificationId\":$3,\"preheatC\":${4:-120},\"interpassC\":${5:-200},\"fillerBatch\":\"FB-1\",\"vt\":1}"
}
weld "$D0" J-1 $QW1; check "weld log by a qualified welder on an approved WPS" '.success and .data.welderName == "Welder One" and .data.wpsNumber == "WPS-002/0"'
weld "$D0" J-2 $QW5; check "welder certified for SMAW cannot weld a GTAW WPS" '.success == false and (.message|contains("SMAW"))'
weld "$D0" J-3 $QW2; check "lapsed welder cannot weld (continuity broken)" '.success == false and (.message|contains("شش ماه"))'
weld "$D0" J-4 $QW1 80 200; check "preheat below the WPS minimum rejected" '.success == false and (.message|contains("پیش‌گرم"))'
weld "$D0" J-5 $QW1 120 300; check "interpass above the WPS maximum rejected" '.success == false and (.message|contains("بین‌پاسی"))'
as "$QC_TOKEN" POST quality/weld-logs "{\"weldDate\":\"$D0\",\"workOrderId\":$WO2,\"jointNo\":\"J-6\",\"wpsId\":$WPSX,\"qualificationId\":$QW1,\"vt\":1}"; nomsg "weld log against a WPS that is not approved rejected" "تایید نهایی"
as "$QA_TOKEN" POST quality/weld-logs "{\"weldDate\":\"$D0\",\"workOrderId\":$WO2,\"jointNo\":\"J-7\",\"wpsId\":$WPS1,\"qualificationId\":$QW1,\"vt\":1}"; no "only QC writes weld logs"
# R1q D15 (replaces the old "chain" checks, which entered welds dated 250 and 150 days back for a welder who is lapsed today: a back-dated log may not hide a lapse,
# and the entry window is the company setting MaxBackdateDays = 7; the six-month chain itself is covered by the unit tests of QualificationRules)
weld "$(dd -250)" J-10 $QW3; nomsg "r1q D15: a weld log dated 250 days back is refused (back-date window of 7 days)" "ثبت با تاخیر بیش از 7 روز مجاز نیست"
weld "$D0" J-11 $QW3; nomsg "chain: weld today by a welder who has not welded since his certificate was issued 300 days ago -> lapsed" "تداوم جوشکاری قطع شده"
WP7=$(wperson "Welder Seven" W-007 W17); QW7=$(wqual $WP7 WQ-7 GTAW 187)
call GET "quality/qualifications?PersonId=$WP7"; LAPSE7=$(val '.data.data[0].lapsesOn[0:10]')
check "r1q D15: the continuity of welder seven ended on the day of his certificate (issued 187 days ago) plus six months, which is in the last 3 to 6 days" ".success and .data.data[0].state == 3 and (.data.data[0].lapsesOn[0:10]) == \"$(addmonths "$(dd -187)" 6)\" and (.data.data[0].lapsesOn[0:10]) >= \"$(dd -6)\" and (.data.data[0].lapsesOn[0:10]) <= \"$(dd -3)\""
weld "$LAPSE7" J-17 $QW7; nomsg "r1q D15: a weld log dated on the last valid day is refused today, because the certificate is also checked on the day of entry" "امروز قابل استفاده نیست"
weld "$(dd -2)" J-18 $QW1; check "r1q D15: a weld log dated two days back by a welder who is valid on that day and today is accepted" ".success and (.data.weldDate[0:10]) == \"$(dd -2)\""
as "$QA_TOKEN" POST quality/qualifications "{\"personId\":$WP2,\"kind\":1,\"method\":\"GTAW\",\"scheme\":1,\"certificateNumber\":\"WQ-2R\",\"issuedDate\":\"$(dd -5)\",\"renewsQualificationId\":$QW2}"; check "re-test registered as renewal" '.success and .data.renewsQualificationId != null'
QW2N=$(val .data.id)
weld "$D0" J-14 $QW2N; check "renewed qualification can weld" '.success'
weld "$D0" J-15 $QW2; check "old certificate is superseded and cannot be used" '.success == false'
as "$QA_TOKEN" POST quality/qualifications/action "{\"id\":$QW6,\"action\":\"revoke\"}"; no "revoking needs a reason"
as "$QA_TOKEN" POST quality/qualifications/action "{\"id\":$QW6,\"action\":\"revoke\",\"reason\":\"Rejected welds in the audit\"}"; check "qualification revoked" '.success and .data.revoked == true and .data.state == 4'
weld "$D0" J-16 $QW6; check "revoked qualification cannot be used" '.success == false'
call GET "quality/qualifications/continuity?Days=30"; check "continuity list shows the welder whose six months end within 30 days" "(.data.data|map(.id)|index($QW4)) != null"
# R1q review M15 and L19: a weld log restarts the six-month continuity of the welder, so it may be dated today at most; within the window a welder whose six months are nearly over keeps his qualification by welding
weld "$(dd 1)" J-19 $QW1; nomsg "r1q M15: a weld log dated tomorrow is refused (no leeway for the browser's time zone: it would postpone the lapse)" "نمی‌تواند در آینده باشد"
WP8=$(wperson "Welder Eight" W-008 W18); QW8=$(wqual $WP8 WQ-8 GTAW 175)
call GET "quality/qualifications?PersonId=$WP8"; check "r1q L19: welder eight (certificate issued 175 days ago) is usable, but his six months end in 6 to 9 days: expiring soon" ".success and .data.data[0].state == 1 and (.data.data[0].lapsesOn[0:10]) == \"$(addmonths "$(dd -175)" 6)\" and (.data.data[0].lapsesOn[0:10]) >= \"$(dd 6)\" and (.data.data[0].lapsesOn[0:10]) <= \"$(dd 9)\""
call GET "quality/qualifications/continuity?Days=30"; check "r1q L19: the continuity list shows welder eight before he welds" "(.data.data|map(.id)|index($QW8)) != null"
weld "$D0" J-20 $QW8; check "r1q L19: welder eight welds today on the approved WPS" '.success and .data.welderName == "Welder Eight"'
call GET "quality/qualifications?PersonId=$WP8"; check "r1q L19: his six months now run from today (a weld restarts the continuity) and the qualification is valid again" ".success and .data.data[0].state == 0 and (.data.data[0].lapsesOn[0:10]) == \"$(addmonths "$D0" 6)\""
call GET "quality/qualifications/continuity?Days=30"; check "r1q L19: ... so he is no longer on the continuity list" "(.data.data|map(.id)|index($QW8)) == null"
call GET "quality/weld-logs?WorkOrderId=$WO2"; check "weld logs of work order 2: 4 accepted (J-1, J-14, J-18 and J-20 of welder eight; r1q D15 replaced the three old chain welds by one dated two days back)" '(.data.data|length) == 4'

# --- G. material certificates (EN 10204) and traceability
as "$WH_TOKEN" POST quality/certificates "{\"lotId\":$LOT,\"type\":2,\"number\":\"MTC-3.1-9\",\"issuer\":\"Mill A\",\"documentId\":\"$DOCID\",\"summary\":\"26NiCrMoV14-5 chemistry and mechanicals OK\"}"; check "warehouse registers the certificate of the lot (pending)" '.success and .data.result == 0 and .data.heatNumber == "H-7781"'
CERT1=$(val .data.id)
as "$WH_TOKEN" POST quality/certificates/verify "{\"id\":$CERT1,\"accept\":true}"; no "warehouse cannot verify a certificate (QC only)"
as "$QC_TOKEN" POST quality/certificates/verify "{\"id\":$CERT1,\"accept\":false}"; no "rejection needs a reason"
as "$QC_TOKEN" POST quality/certificates/verify "{\"id\":$CERT1,\"accept\":true,\"note\":\"checked against heat H-7781\"}"; check "QC verifies the certificate" '.success and .data.result == 1 and .data.verifiedByName != null'
as "$QC_TOKEN" POST quality/certificates "{\"lotId\":$LOT,\"type\":1,\"number\":\"MTC-2.2-1\",\"documentId\":\"$DOCID\"}"; CERT2=$(val .data.id)
as "$QC_TOKEN" POST quality/certificates/verify "{\"id\":$CERT2,\"accept\":true}"; nomsg "the person who registered a certificate cannot verify it" "تفکیک وظایف"
as "$QC2_TOKEN" POST quality/certificates/verify "{\"id\":$CERT2,\"accept\":false,\"note\":\"Not the right heat\"}"; check "certificate rejected with a reason" '.success and .data.result == 2'
as "$QC_TOKEN" GET "quality/traceability?LotId=$LOT"; check "traceability by lot: heat number, certificates and receipts" '.success and .data.lots[0].lotNumber == "H-7781" and .data.lots[0].heatNumber == "H-7781" and (.data.lots[0].certificates|length) >= 1 and (.data.lots[0].receipts|length) >= 1'
as "$QC_TOKEN" GET "quality/traceability"; no "traceability without a serial or lot rejected"

# required certificate type on an item blocks incoming acceptance
item PL31 '{"code":"01003010060102","title":"ورق با گواهی 3.1","unit":"kg","trackingMode":1,"requiresIncomingInspection":true,"requiredCertificateType":2}' "plate that needs an EN 10204 3.1 certificate"
call GET "inventory/items/by-code?code=01003010060102"; check "required certificate type saved on the item" '.data.requiredCertificateType == 2'
call POST inventory/documents "{\"type\":1,\"documentDate\":\"$D0\",\"warehouseId\":$WQ,\"destinationWarehouseId\":$W1,\"referenceNumber\":\"INV-901\",\"lines\":[{\"itemId\":$PL31,\"quantity\":20,\"heatNumber\":\"HT-3100\",\"unitPrice\":1000}]}"; PRC=$(val .data.id)
call POST "inventory/documents/$PRC/confirm"; check "receipt of the 3.1 plate into quarantine" '.success'
call GET "inventory/quality/inspections?Status=0"; QI31=$(jq -r ".data.data[]|select(.itemId==$PL31)|.id" "$B")
call GET "inventory/stock/lots?ItemId=$PL31"; PL31LOT=$(val '.data.data[0].id')
as "$QC_TOKEN" POST inventory/quality/inspections "{\"id\":$QI31,\"acceptedQuantity\":20,\"rejectedQuantity\":0}"; check "incoming acceptance refused: no verified certificate" '.success == false and (.message|contains("EN 10204"))'
as "$WH_TOKEN" POST quality/certificates "{\"lotId\":$PL31LOT,\"type\":1,\"number\":\"MTC-2.2-77\",\"documentId\":\"$DOCID\"}"; C22=$(val .data.id)
as "$QC_TOKEN" POST quality/certificates/verify "{\"id\":$C22,\"accept\":true}"
as "$QC_TOKEN" POST inventory/quality/inspections "{\"id\":$QI31,\"acceptedQuantity\":20,\"rejectedQuantity\":0}"; check "a 2.2 certificate does not satisfy a 3.1 requirement" '.success == false'
as "$WH_TOKEN" POST quality/certificates "{\"lotId\":$PL31LOT,\"type\":2,\"number\":\"MTC-3.1-77\",\"documentId\":\"$DOCID\"}"; C31=$(val .data.id)
as "$QC_TOKEN" POST quality/certificates/verify "{\"id\":$C31,\"accept\":true}"
# R1q D16 and review M12: an incoming inspection that rests on measured values names the instrument of every value (calibrated today); whether it is "measured" follows from those values, never from
# a flag of the client; and a QC inspector records it only with a valid inspector qualification once the company keeps that register
as "$QC3_TOKEN" POST inventory/quality/inspections "{\"id\":$QI31,\"acceptedQuantity\":20,\"rejectedQuantity\":0}"; nomsg "r1q M12: a QC user with no inspector qualification cannot record an incoming inspection" "ثبت نتیجه بازرسی ورودی بدون گواهی صلاحیت معتبر مجاز نیست"
as "$QC_TOKEN" POST inventory/quality/inspections "{\"id\":$QI31,\"acceptedQuantity\":20,\"rejectedQuantity\":0,\"measurements\":[{\"characteristic\":\"Thickness\",\"nominal\":10,\"tolPlus\":0.2,\"tolMinus\":0.2,\"measured\":10.05,\"unit\":\"mm\"}]}"; nomsg "r1q D16: a measured value without the instrument that measured it is refused" "ابزار اندازه‌گیری به‌کاررفته را انتخاب کنید"
as "$QC_TOKEN" POST inventory/quality/inspections "{\"id\":$QI31,\"acceptedQuantity\":20,\"rejectedQuantity\":0,\"measurements\":[{\"characteristic\":\"Thickness\",\"nominal\":10,\"tolPlus\":0.2,\"tolMinus\":0.2,\"measured\":10.05,\"unit\":\"mm\",\"equipmentId\":$G2}]}"; nomsg "r1q D16: ... and one measured with an overdue instrument (G2, certificate expired) is refused" "منقضی شده است؛ استفاده از آن مجاز نیست"
as "$QC_TOKEN" POST inventory/quality/inspections "{\"id\":$QI31,\"acceptedQuantity\":20,\"rejectedQuantity\":0,\"measurements\":[{\"characteristic\":\"Thickness\",\"nominal\":10,\"tolPlus\":0.2,\"tolMinus\":0.2,\"measured\":10.5,\"unit\":\"mm\",\"equipmentId\":$G4}]}"; nomsg "r1q M12: a value out of tolerance cannot be accepted whole" "اندازه‌گیری خارج از تلرانس ثبت شده است"
as "$QC_TOKEN" POST inventory/quality/inspections "{\"id\":$QI31,\"acceptedQuantity\":20,\"rejectedQuantity\":0,\"measurements\":[{\"characteristic\":\"Thickness\",\"nominal\":10,\"tolPlus\":0.2,\"tolMinus\":0.2,\"measured\":10.05,\"unit\":\"mm\",\"equipmentId\":$G4}]}"; check "with a verified 3.1 certificate the lot is accepted (r1q D16: the measured value names the calibrated instrument G4, which is kept on the inspection)" ".success and .data.status == 1 and .data.equipmentIds == [$G4] and (.data.measurements|length) == 1 and .data.measurements[0].equipmentId == $G4 and .data.measurements[0].pass == true"
# a second lot of the plate: the old client flag \"measured\" has no meaning any more, an inspection without measurement lines is recorded as it is
call POST inventory/documents "{\"type\":1,\"documentDate\":\"$D0\",\"warehouseId\":$WQ,\"destinationWarehouseId\":$W1,\"referenceNumber\":\"INV-902\",\"lines\":[{\"itemId\":$PL31,\"quantity\":10,\"heatNumber\":\"HT-3101\",\"unitPrice\":1000}]}"; PRC2=$(val .data.id)
call POST "inventory/documents/$PRC2/confirm"; check "receipt of the second lot of the 3.1 plate into quarantine" '.success'
call GET "inventory/quality/inspections?Status=0"; QI31B=$(jq -r ".data.data[]|select(.itemId==$PL31)|.id" "$B")
call GET "inventory/stock/lots?ItemId=$PL31"; PL31LOTB=$(jq -r '.data.data[]|select(.heatNumber=="HT-3101")|.id' "$B")
as "$WH_TOKEN" POST quality/certificates "{\"lotId\":$PL31LOTB,\"type\":2,\"number\":\"MTC-3.1-78\",\"documentId\":\"$DOCID\"}"; C31B=$(val .data.id)
as "$QC_TOKEN" POST quality/certificates/verify "{\"id\":$C31B,\"accept\":true}"; check "the 3.1 certificate of the second lot is verified" '.success and .data.result == 1'
as "$QC_TOKEN" POST inventory/quality/inspections "{\"id\":$QI31B,\"acceptedQuantity\":10,\"rejectedQuantity\":0,\"measured\":true}"; check "r1q M12: the old \"measured\" flag alone proves nothing and demands nothing: no measurement lines, no instrument, recorded as it is" ".success and .data.status == 1 and ((.data.equipmentIds // [])|length) == 0 and ((.data.measurements // [])|length) == 0"

# --- H. NCR additions: due date, CAPA for major NCR, committee size (see also the NCR section above)
call GET "inventory/quality/ncr/$NCR2"; check "major NCR from the NCR section has its CAPA drafted by the system" '.success and .data.capaId != null and (.data.capaNumber|startswith("CAPA-")) and .data.dueDate != null'
NCR2CAPA=$(val .data.capaId)

# --- I. CAPA (ISO 9001 10.2): owner, actions, effectiveness check by another person
# R1q review M11: whoever created, edited or owns a CAPA (or one of its actions) does not judge its effectiveness, close it or cancel it. QA defines the CAPAs below, so QC judges the effectiveness and QC2 closes.
# The day an action was really done may be entered up to MaxBackdateDays late; the CAPA is implemented on the day of the last action of the round, and the waiting period of the check runs from that day.
capa_cycle() { # capa_cycle ID OWNER_ID OWNER_TOKEN EFFECTIVENESS_TOKEN CLOSE_TOKEN
  as "$QA_TOKEN" GET "quality/capas/$1"; local rv src sid
  rv=$(val .data.rowVersion); src=$(val .data.source); sid=$(val '.data.sourceId // empty')
  local body
  body=$(jq -nc --argjson id "$1" --arg rv "$rv" --argjson src "$src" --arg sid "$sid" --argjson owner "$2" --arg due "$(dd 20)" --arg adue "$(dd 10)" \
    '{id:$id,rowVersion:$rv,source:$src,problem:"Problem found",rootCauseMethod:1,rootCauseAnalysis:"Why 1 ... why 5: procedure gap",ownerUserId:$owner,dueDate:$due,effectivenessCriteria:"No recurrence in the next 3 lots",actions:[{description:"Revise the procedure and train staff",ownerUserId:$owner,dueDate:$adue}]} + (if $sid != "" then {sourceId:($sid|tonumber)} else {} end)')
  as "$QA_TOKEN" POST quality/capas "$body"
}
capa_cycle $NCR2CAPA $PRODID "$PROD_TOKEN"; check "QA completes the CAPA: owner, root cause, action, effectiveness criteria -> actions defined; the CAPA drafted for a major NCR is mandatory, in round 1, not escalated" '.success and .data.status == 1 and .data.ownerName != null and (.data.actions|length) == 1 and .data.mandatory == true and .data.iteration == 1 and .data.escalationLevel == 0'
CA_ACT=$(val '.data.actions[0].id')
as "$QA_TOKEN" POST quality/capas "{\"id\":$NCR2CAPA,\"problem\":\"Problem found\",\"source\":9,\"rootCauseMethod\":1,\"rootCauseAnalysis\":\"x\",\"ownerUserId\":$PRODID,\"effectivenessCriteria\":\"y\",\"actions\":[]}"; nomsg "r1q M11: the source of a CAPA is fixed when it is created (a mandatory CAPA cannot be turned into an optional one)" "منبع CAPA پس از ثبت تغییر نمی‌کند"
as "$PROD_TOKEN" POST quality/capas/action "{\"id\":$NCR2CAPA,\"action\":\"implemented\"}"; no "implemented refused while an action is not done"
as "$PROD_TOKEN" POST quality/capas/action "{\"id\":$NCR2CAPA,\"action\":\"complete-action\",\"actionId\":$CA_ACT}"; no "completing an action needs evidence or a note"
as "$PROD_TOKEN" POST quality/capas/action "{\"id\":$NCR2CAPA,\"action\":\"complete-action\",\"actionId\":$CA_ACT,\"note\":\"Procedure revised, training record TR-9\",\"date\":\"$(dd 1)\"}"; nomsg "r1q M11: the day an action was done cannot be in the future" "نمی‌تواند در آینده باشد"
as "$PROD_TOKEN" POST quality/capas/action "{\"id\":$NCR2CAPA,\"action\":\"complete-action\",\"actionId\":$CA_ACT,\"note\":\"Procedure revised, training record TR-9\",\"date\":\"$(dd -8)\"}"; nomsg "r1q M11: ... nor older than the back-date window of the company (7 days: 8 days back is refused)" "ثبت با تاخیر بیش از 7 روز مجاز نیست"
as "$PROD_TOKEN" POST quality/capas/action "{\"id\":$NCR2CAPA,\"action\":\"complete-action\",\"actionId\":$CA_ACT,\"note\":\"Procedure revised, training record TR-9\",\"date\":\"$(dd -7)\"}"; check "owner completes the action and enters the day it was really done (7 days ago, the oldest day the window allows)" ".success and ([.data.actions[]|select(.id == $CA_ACT)|.doneAt[0:10]][0] == \"$(dd -7)\")"
as "$PROD_TOKEN" POST quality/capas/action "{\"id\":$NCR2CAPA,\"action\":\"implemented\"}"; check "CAPA implemented: its implementation day is the day of its last action (7 days ago), the effectiveness review date is set automatically" ".success and .data.status == 2 and .data.effectivenessDueDate != null and (.data.implementedAt[0:10]) == \"$(dd -7)\""
as "$PROD_TOKEN" POST quality/capas/action "{\"id\":$NCR2CAPA,\"action\":\"effectiveness\",\"note\":\"ok\",\"passed\":true}"; nomsg "the owner cannot verify effectiveness (role and segregation)" "مجوز"
as "$QC_TOKEN" POST quality/capas/action "{\"id\":$NCR2CAPA,\"action\":\"close\"}"; no "closing before the effectiveness check rejected"
as "$QC_TOKEN" POST quality/capas/action "{\"id\":$NCR2CAPA,\"action\":\"effectiveness\",\"passed\":true}"; no "effectiveness result needs a written note against the criteria"
# R1q D20: the effect of an action shows over time: no check before the waiting period (company setting, default 30 days) has passed since the implementation
as "$QC_TOKEN" POST quality/capas/action "{\"id\":$NCR2CAPA,\"action\":\"effectiveness\",\"note\":\"3 lots inspected, no recurrence\",\"passed\":true}"; nomsg "r1q D20: the effectiveness check is refused before the waiting period (30 days) after the implementation" "حداقل 30 روز پس از اجرای اقدام‌ها"
as "$QA_TOKEN" GET "quality/capas/$NCR2CAPA"; check "r1q D20: the CAPA shows the earliest day of the check (the implementation day, 7 days ago, plus 30)" ".success and (.data.effectivenessEarliest[0:10]) == \"$(dd 23)\""
as "$QA_TOKEN" POST quality/settings '{"key":"EffectivenessWaitDays","value":6}'; nomsg "r1q M14: a waiting period under a week is refused (the range is 7 to 365 days)" "باید عدد صحیح بین 7 تا 365 باشد"
as "$QA_TOKEN" POST quality/settings '{"key":"EffectivenessWaitDays","value":7}'; check "r1q D20: QA sets the waiting period to its minimum, 7 days, for the rest of the test (restored after the audit section)" '.success and ([.data[]|select(.key=="EffectivenessWaitDays")|.value][0] == 7)'
# R1q D21: a failed check re-opens the CAPA for a new round (new iteration, new actions); round 1 stays as the record. The old due date is cleared: the new round needs a new one before its actions are defined (review M11)
as "$QC_TOKEN" POST quality/capas/action "{\"id\":$NCR2CAPA,\"action\":\"effectiveness\",\"note\":\"Recurrence found in lot 4\",\"passed\":false}"; check "r1q D21: a failed effectiveness check re-opens the CAPA as round 2 (no implementation day, no due date)" '.success and .data.status == 0 and .data.iteration == 2 and .data.implementedAt == null and .data.dueDate == null and (.data.actions|length) == 1'
as "$QA_TOKEN" GET "quality/capas/$NCR2CAPA"
CAPA2BODY=$(jq -c --arg adue "$(dd 12)" '.data | {id,rowVersion,source,sourceId,problem,containment,rootCauseMethod,rootCauseAnalysis,ownerUserId,dueDate,effectivenessCriteria,actions:([.actions[]|{id,description,ownerUserId,dueDate}] + [{description:"Release check lot by lot for the next three lots",ownerUserId:.ownerUserId,dueDate:$adue}])}' "$B")
as "$QA_TOKEN" POST quality/capas "$CAPA2BODY"; check "r1q M11: round 2 with an action but no new due date stays open (the old date was cleared, so the CAPA is not defined yet)" '.success and .data.status == 0 and .data.dueDate == null and .data.iteration == 2 and (.data.actions|length) == 2'
as "$QA_TOKEN" GET "quality/capas/$NCR2CAPA"
CAPA2BODY=$(jq -c --arg due "$(dd 25)" '.data | {id,rowVersion,source,sourceId,problem,containment,rootCauseMethod,rootCauseAnalysis,ownerUserId,dueDate:$due,effectivenessCriteria,actions:[.actions[]|{id,description,ownerUserId,dueDate}]}' "$B")
as "$QA_TOKEN" POST quality/capas "$CAPA2BODY"; check "r1q D21: QA gives round 2 its new due date; the actions are defined and the done action of round 1 stays" '.success and .data.status == 1 and .data.iteration == 2 and (.data.actions|length) == 2 and ([.data.actions[]|select(.iteration == 2)]|length) == 1'
CA_ACT2=$(val '[.data.actions[]|select(.iteration == 2)][0].id')
as "$PROD_TOKEN" POST quality/capas/action "{\"id\":$NCR2CAPA,\"action\":\"complete-action\",\"actionId\":$CA_ACT2,\"note\":\"Lot-by-lot release check added to the instruction\",\"date\":\"$(dd -7)\"}"; check "r1q D21: the owner completes the action of round 2 (done 7 days ago, with his note as the evidence)" ".success and ([.data.actions[]|select(.id == $CA_ACT2)|.doneAt[0:10]][0] == \"$(dd -7)\") and ([.data.actions[]|select(.id == $CA_ACT2)|.evidenceNote][0] == \"Lot-by-lot release check added to the instruction\")"
as "$PROD_TOKEN" POST quality/capas/action "{\"id\":$NCR2CAPA,\"action\":\"implemented\"}"; check "r1q D21: round 2 implemented, on the day of its action" ".success and .data.status == 2 and .data.iteration == 2 and (.data.implementedAt[0:10]) == \"$(dd -7)\""
as "$QC_TOKEN" POST quality/capas/action "{\"id\":$NCR2CAPA,\"action\":\"effectiveness\",\"note\":\"3 lots inspected, no recurrence\",\"passed\":true}"; check "effectiveness verified by QC (7 days after the implementation day, the minimum waiting period)" '.success and .data.status == 3'
as "$PROD_TOKEN" POST quality/capas/action "{\"id\":$NCR2CAPA,\"action\":\"close\"}"; no "only QA/QC close a CAPA"
as "$QA_TOKEN" POST quality/capas/action "{\"id\":$NCR2CAPA,\"action\":\"close\",\"note\":\"closed\"}"; nomsg "r1q M11: QA, who defined the CAPA, cannot close it (segregation of duties)" "تفکیک وظایف"
as "$QC2_TOKEN" POST quality/capas/action "{\"id\":$NCR2CAPA,\"action\":\"close\",\"note\":\"closed\"}"; check "CAPA closed by another quality person (QC2), who had no part in it" '.success and .data.status == 4 and .data.closedByName != null'
# a CAPA owned by QA cannot be judged or closed by QA
as "$QA_TOKEN" POST quality/capas "{\"problem\":\"Calibration labels missing\",\"source\":5,\"rootCauseMethod\":2,\"rootCauseAnalysis\":\"Fishbone\",\"ownerUserId\":$QAID,\"dueDate\":\"$(dd 15)\",\"effectivenessCriteria\":\"Audit shows labels\",\"actions\":[{\"description\":\"Label all instruments\",\"ownerUserId\":$QAID,\"dueDate\":\"$(dd 5)\"}]}"; check "manual CAPA with owner QA (source: data analysis, so no rule requires it)" '.success and .data.status == 1 and .data.autoDrafted == false and .data.mandatory == false'
CP2=$(val .data.id); CP2A=$(val '.data.actions[0].id')
as "$QA_TOKEN" POST quality/capas/action "{\"id\":$CP2,\"action\":\"complete-action\",\"actionId\":$CP2A,\"note\":\"done\",\"date\":\"$(dd -7)\"}"; check "QA completes his own action (done 7 days ago)" '.success'
as "$QA_TOKEN" POST quality/capas/action "{\"id\":$CP2,\"action\":\"implemented\"}"; check "the CAPA owned by QA is implemented" '.success and .data.status == 2'
as "$QA_TOKEN" POST quality/capas/action "{\"id\":$CP2,\"action\":\"effectiveness\",\"note\":\"self check\",\"passed\":true}"; nomsg "the owner (QA) cannot verify the effectiveness of his own CAPA" "تفکیک وظایف"
as "$QC_TOKEN" POST quality/capas/action "{\"id\":$CP2,\"action\":\"effectiveness\",\"note\":\"labels present on 14 of 14\",\"passed\":true}"; check "QC verifies the effectiveness of the CAPA owned by QA" '.success and .data.status == 3'
as "$QA_TOKEN" POST quality/capas/action "{\"id\":$CP2,\"action\":\"close\"}"; nomsg "the owner (QA) cannot close his own CAPA" "تفکیک وظایف"
as "$QC2_TOKEN" POST quality/capas/action "{\"id\":$CP2,\"action\":\"close\"}"; check "another quality person closes it" '.success and .data.status == 4'
# R1q D21: a CAPA that a rule required (a major NCR, an audit finding, a non-conformance source) is cancelled only by the QA manager, with a reason that stays on the record, and not by the person who created or owns it (review M11)
as "$QC_TOKEN" POST quality/capas "{\"problem\":\"Recurring paint defects\",\"source\":1,\"rootCauseMethod\":2,\"rootCauseAnalysis\":\"Fishbone\",\"ownerUserId\":$PRODID,\"dueDate\":\"$(dd 15)\",\"effectivenessCriteria\":\"No paint defect in 3 lots\",\"actions\":[{\"description\":\"Check booth humidity\",\"ownerUserId\":$PRODID,\"dueDate\":\"$(dd 5)\"}]}"; check "r1q M11: QC registers a CAPA for recurring paint defects (source: non-conformance, so mandatory)" '.success and .data.status == 1 and .data.mandatory == true'
CP5=$(val .data.id)
as "$QC2_TOKEN" POST quality/capas/action "{\"id\":$CP5,\"action\":\"cancel\",\"note\":\"Not needed\"}"; nomsg "r1q D21: QC cannot cancel a mandatory CAPA (non-conformance source)" "فقط مدیر QA"
as "$QA_TOKEN" POST quality/capas/action "{\"id\":$CP5,\"action\":\"cancel\"}"; nomsg "r1q D21: the QA manager needs a written reason" "دلیل لغو را بنویسید"
as "$QA_TOKEN" POST quality/capas/action "{\"id\":$CP5,\"action\":\"cancel\",\"note\":\"Duplicate of the CAPA of the paint NCR\"}"; check "r1q D21: the QA manager (who did not create or edit it) cancels it; the reason and the day stay on the CAPA" '.success and .data.status == 5 and .data.cancelReason == "Duplicate of the CAPA of the paint NCR" and .data.cancelledAt != null'
as "$FM_TOKEN" GET "finance/audit?EntityType=Capa&EntityId=$CP5&PageSize=0"; check "r1q D21: the cancellation is in the audit trail with the user and the reason" '.success and ([.data.data[]|select(.action == "Modified" and (.userName|length) > 0 and (.afterJson|tostring|contains("Duplicate of the CAPA of the paint NCR")))]|length) == 1'
# an optional CAPA with two actions: the implementation day is the day of the LAST action, so the waiting period of the check starts there (3 days ago plus 7 days = 4 days ahead)
as "$QA_TOKEN" POST quality/capas "{\"problem\":\"Optional improvement idea\",\"source\":9,\"rootCauseMethod\":1,\"rootCauseAnalysis\":\"x\",\"ownerUserId\":$PRODID,\"dueDate\":\"$(dd 15)\",\"effectivenessCriteria\":\"y\",\"actions\":[{\"description\":\"First step\",\"ownerUserId\":$PRODID,\"dueDate\":\"$(dd 5)\"},{\"description\":\"Second step\",\"ownerUserId\":$PRODID,\"dueDate\":\"$(dd 6)\"}]}"; check "an optional CAPA (source: other) with two actions" '.success and .data.status == 1 and .data.mandatory == false and (.data.actions|length) == 2'
CP6=$(val .data.id); CP6A=$(val '.data.actions[0].id'); CP6B=$(val '.data.actions[1].id')
as "$PROD_TOKEN" POST quality/capas/action "{\"id\":$CP6,\"action\":\"complete-action\",\"actionId\":$CP6A,\"note\":\"First step done\",\"date\":\"$(dd -7)\"}"; check "the first action is done 7 days ago" '.success'
as "$PROD_TOKEN" POST quality/capas/action "{\"id\":$CP6,\"action\":\"complete-action\",\"actionId\":$CP6B,\"note\":\"Second step done\",\"date\":\"$(dd -3)\"}"; check "the second action is done 3 days ago" '.success'
as "$PROD_TOKEN" POST quality/capas/action "{\"id\":$CP6,\"action\":\"implemented\"}"; check "r1q M11: the CAPA is implemented on the day of its LAST action (3 days ago), and its earliest effectiveness check is 4 days ahead" ".success and .data.status == 2 and (.data.implementedAt[0:10]) == \"$(dd -3)\" and (.data.effectivenessEarliest[0:10]) == \"$(dd 4)\""
as "$QC_TOKEN" POST quality/capas/action "{\"id\":$CP6,\"action\":\"effectiveness\",\"note\":\"Looks fine\",\"passed\":true}"; nomsg "r1q M11: the check is refused before that day (the first action, done 7 days ago, does not start the waiting period)" "حداقل 7 روز پس از اجرای اقدام‌ها"
as "$QA_TOKEN" POST quality/capas/action "{\"id\":$CP6,\"action\":\"cancel\",\"note\":\"Not pursued\"}"; nomsg "r1q M11: QA, who defined the CAPA, cannot cancel it either (a second person decides it is not needed)" "تفکیک وظایف"
as "$QC_TOKEN" POST quality/capas/action "{\"id\":$CP6,\"action\":\"cancel\",\"note\":\"Not pursued\"}"; check "r1q D21: a CAPA that no rule required may still be cancelled by QC (who had no part in it), with a reason" '.success and .data.status == 5 and .data.cancelReason == "Not pursued"'
# R1q D13 and review M11: late CAPAs escalate to QA and, after 14 days, to the CEO. The very first run only records the level of the CAPAs that are already late (the whole backlog is not announced in one night)
as "$QA_TOKEN" POST quality/capas "{\"problem\":\"Backlog item that was late before the first run\",\"source\":9,\"rootCauseMethod\":1,\"rootCauseAnalysis\":\"x\",\"ownerUserId\":$PRODID,\"dueDate\":\"$(dd -3)\",\"effectivenessCriteria\":\"y\",\"actions\":[{\"description\":\"z\",\"ownerUserId\":$PRODID,\"dueDate\":\"$(dd -3)\"}]}"; CP0=$(val .data.id)
as "$QA_TOKEN" POST quality/capas/escalate; check "r1q M11: the first escalation run only records the level of the CAPA that was already late and tells nobody" '.success and .data.firstRun == true and .data.recorded == 1 and .data.escalated == 0 and .data.ceoNotified == 0 and .data.skipped == 0'
as "$QA_TOKEN" GET "office/inbox?SourceKey=capa-late:qa:$CP0"; check "r1q M11: QA has no alert about it" '.success and (.data.data|length) == 0'
as "$QA_TOKEN" GET "quality/capas/$CP0"; check "r1q M11: but the CAPA carries its level (1: late), so it is not announced later either" '.success and .data.escalationLevel == 1'
# overdue CAPA is computed and listed
as "$QA_TOKEN" POST quality/capas "{\"problem\":\"Late CAPA\",\"source\":9,\"rootCauseMethod\":1,\"rootCauseAnalysis\":\"x\",\"ownerUserId\":$PRODID,\"dueDate\":\"$(dd -5)\",\"effectivenessCriteria\":\"y\",\"actions\":[{\"description\":\"z\",\"ownerUserId\":$PRODID,\"dueDate\":\"$(dd -5)\"}]}"; CP3=$(val .data.id)
as "$QA_TOKEN" GET quality/capas/overdue; check "overdue CAPA listed (computed from the due date)" "(.data.data|map(.id)|index($CP3)) != null"
# R1q D13: every action owner finds his action in the inbox with its due date and reads the CAPA he works on
as "$QA_TOKEN" POST quality/capas "{\"problem\":\"Gate pass log not kept\",\"source\":9,\"rootCauseMethod\":1,\"rootCauseAnalysis\":\"x\",\"ownerUserId\":$QCID,\"dueDate\":\"$(dd -20)\",\"effectivenessCriteria\":\"y\",\"actions\":[{\"description\":\"Keep the gate pass log\",\"ownerUserId\":$SECID,\"dueDate\":\"$(dd -20)\"}]}"; check "r1q D13: a CAPA with an action owned by the security officer" '.success and .data.status == 1'
CP4=$(val .data.id); CP4A=$(val '.data.actions[0].id')
as "$SEC_TOKEN" GET "office/inbox?SourceKey=capa-action:$CP4A"; check "r1q D13: the action is in the inbox of its owner with its due date" ".success and (.data.data|length) == 1 and (.data.data[0].dueDate[0:10]) == \"$(dd -20)\" and (.data.data[0].title|contains(\"Keep the gate pass log\")) and .data.data[0].link == \"/quality/capa/$CP4\""
as "$SEC_TOKEN" GET quality/capas; check "r1q D13: the action owner sees only the CAPA he works on" ".success and (.data.data|length) == 1 and .data.data[0].id == $CP4"
as "$SEC_TOKEN" GET "quality/capas/$NCR2CAPA"; nomsg "r1q D13: ... and cannot open another CAPA" "شما مجوز این کار را ندارید"
as "$SEC_TOKEN" GET "quality/capas/$CP4"; check "r1q D13: the action owner opens the CAPA of his action" ".success and .data.id == $CP4"
as "$QA_TOKEN" POST quality/capas/escalate; check "r1q D13: the escalation (the method the 04:00 job calls) raises the two CAPAs that became late after the first run, one of them to the CEO; the backlog CAPA recorded by the first run is not raised again" '.success and .data.firstRun == false and .data.recorded == 0 and .data.escalated == 2 and .data.ceoNotified == 1'
as "$QA_TOKEN" GET "office/inbox?SourceKey=capa-late:qa:$CP4"; check "r1q D13: QA is told about the CAPA that is 20 days late" '.success and (.data.data|length) == 1'
as "$CEO_TOKEN" GET "office/inbox?SourceKey=capa-late:ceo:$CP4"; check "r1q D13: and the CEO too, because it is 14 days or more late" '.success and (.data.data|length) == 1'
as "$CEO_TOKEN" GET "office/inbox?SourceKey=capa-late:ceo:$CP3"; check "r1q D13: the CEO is not told about the CAPA that is only 5 days late" '.success and (.data.data|length) == 0'
as "$QA_TOKEN" GET "office/inbox?SourceKey=capa-late:qa:$CP3"; check "r1q D13: QA is told about it" '.success and (.data.data|length) == 1'
as "$QA_TOKEN" POST quality/capas/escalate; check "r1q D13: a second run raises nothing again" '.success and .data.escalated == 0 and .data.ceoNotified == 0 and .data.recorded == 0'
as "$QC_TOKEN" POST quality/capas/action "{\"id\":$CP3,\"action\":\"cancel\",\"note\":\"Superseded by the CAPA of the gate pass log\"}"; check "r1q M11: QC cancels the 5-day late CAPA (an optional one, and QC had no part in it)" '.success and .data.status == 5'
as "$QA_TOKEN" GET "office/inbox?SourceKey=capa-late:qa:$CP3"; check "r1q M11: the late alert of a cancelled CAPA is closed with it" '.success and (.data.data|length) == 0'
as "$QC_TOKEN" POST quality/capas/action "{\"id\":$CP0,\"action\":\"cancel\",\"note\":\"Backlog item dropped\"}"; check "the backlog CAPA is cancelled too, so only the 20-day late CAPA of the gate pass log stays overdue" '.success and .data.status == 5'
as "$SEC_TOKEN" POST quality/capas/action "{\"id\":$CP4,\"action\":\"complete-action\",\"actionId\":$CP4A,\"note\":\"Gate pass log kept since Monday\"}"; check "r1q D13: the action owner completes his own action (done today, with his note as the evidence)" ".success and ([.data.actions[]|select(.id == $CP4A)|.doneAt[0:10]][0] == \"$D0\") and ([.data.actions[]|select(.id == $CP4A)|.evidenceNote][0] == \"Gate pass log kept since Monday\")"
as "$SEC_TOKEN" GET "office/inbox?SourceKey=capa-action:$CP4A"; check "r1q D13: the done action leaves his inbox" '.success and (.data.data|length) == 0'

# --- J. customer complaints (response due within 10 days)
as "$COM_TOKEN" POST quality/complaints "{\"contractId\":$QCT,\"workOrderId\":$WO1,\"channel\":\"letter\",\"description\":\"Vibration after installation\",\"severity\":2,\"receivedDate\":\"$(dd -15)\"}"; check "commercial registers a complaint; response was due 5 days ago -> overdue" '.success and .data.overdue == true and (.data.number|startswith("CC-")) and .data.status == 0'
CC1=$(val .data.id)
as "$COM_TOKEN" POST quality/complaints "{\"workOrderId\":$WO1,\"description\":\"second complaint left open\",\"severity\":1,\"receivedDate\":\"$(dd -20)\"}"; CC2=$(val .data.id)
as "$QA_TOKEN" POST quality/complaints/action "{\"id\":$CC1,\"action\":\"respond\",\"response\":\"x\"}"; no "cannot respond before the review"
as "$QA_TOKEN" POST quality/complaints/action "{\"id\":$CC1,\"action\":\"review\"}"; check "complaint under review" '.success and .data.status == 1'
as "$QA_TOKEN" POST quality/complaints/action "{\"id\":$CC1,\"action\":\"respond\"}"; no "response text is required"
as "$QA_TOKEN" POST quality/complaints/action "{\"id\":$CC1,\"action\":\"respond\",\"response\":\"Site visit on Monday, root cause analysis opened\"}"; check "responded" '.success and .data.status == 2'
as "$QA_TOKEN" POST quality/complaints/action "{\"id\":$CC1,\"action\":\"close\"}"; no "major complaint cannot be closed without an NCR or CAPA link"
as "$QA_TOKEN" POST quality/complaints/action "{\"id\":$CC1,\"action\":\"create-capa\"}"; check "CAPA drafted from the complaint" '.success and .data.capaId != null and (.data.capaNumber|startswith("CAPA-"))'
as "$QA_TOKEN" POST quality/complaints/action "{\"id\":$CC1,\"action\":\"close\"}"; check "complaint closed" '.success and .data.status == 3'

# --- K. document control (PR/WI/FO): preparer, reviewer and approver are three different people
as "$WH_TOKEN" POST quality/documents '{"type":1,"department":"QC","title":"Calibration control"}'; no "warehouse cannot create controlled documents"
as "$QC_TOKEN" POST quality/documents '{"type":1,"department":"QC","title":"Control of measuring equipment","retentionClass":"Quality records","responsibleUnit":"QC"}'; check "controlled document coded TYPE-DEPT-NNN" '.success and (.data.code|test("^PR-QC-[0-9]{3}$"))'
DOC1=$(val .data.id); DOC1CODE=$(val .data.code)
as "$QC_TOKEN" GET "quality/documents/check-code?type=1&department=QC&serial=1"; check "code check reports an existing code and the next free one" '.success and .data.exists == true and .data.nextFreeCode != null'
as "$QC_TOKEN" POST quality/documents/revisions "{\"documentId\":$DOC1,\"revision\":\"00\",\"changeSummary\":\"First issue\"}"; check "revision 00 drafted (no file yet)" '.success'
DREV=$(val '.data.revisions[0].id')
as "$QC_TOKEN" POST quality/documents/revisions/action "{\"id\":$DREV,\"action\":\"review\"}"; nomsg "preparer cannot review his own revision" "تفکیک وظایف"
as "$ENG_TOKEN" POST quality/documents/revisions/action "{\"id\":$DREV,\"action\":\"review\"}"; check "reviewed by engineering" '.success and ([.data.revisions[]|select(.id=='$DREV')|.status][0] == 1)'
as "$QA_TOKEN" POST quality/documents/revisions/action "{\"id\":$DREV,\"action\":\"approve\",\"effectiveDate\":\"$D0\"}"; nomsg "approval needs the file attached" "فایل بازنگری"
as "$QC_TOKEN" POST quality/documents/revisions "{\"documentId\":$DOC1,\"revision\":\"00\",\"changeSummary\":\"First issue\",\"fileDocumentId\":\"$DOCID\"}"; no "duplicate revision number rejected"
# attach the file by saving the revision again is not allowed once in review, so use a second document for the full cycle
as "$QC_TOKEN" POST quality/documents '{"type":2,"department":"QC","title":"Welding inspection instruction"}'; DOC2=$(val .data.id)
as "$QC_TOKEN" POST quality/documents/revisions "{\"documentId\":$DOC2,\"revision\":\"00\",\"changeSummary\":\"First issue\",\"fileDocumentId\":\"$DOCID\"}"; DREV2=$(val '.data.revisions[0].id')
as "$ENG_TOKEN" POST quality/documents/revisions/action "{\"id\":$DREV2,\"action\":\"review\"}"
as "$ENG_TOKEN" POST quality/documents/revisions/action "{\"id\":$DREV2,\"action\":\"approve\"}"; nomsg "reviewer cannot approve (and engineering is not an approver role)" "تایید سند"
as "$QC_TOKEN" POST quality/documents/revisions/action "{\"id\":$DREV2,\"action\":\"approve\"}"; nomsg "preparer cannot approve" "تایید سند"
as "$QA_TOKEN" POST quality/documents/revisions/action "{\"id\":$DREV2,\"action\":\"approve\",\"effectiveDate\":\"$D0\"}"; check "QA approves the third-person revision -> effective" ".success and ([.data.revisions[]|select(.id==$DREV2)|.status][0] == 3) and .data.currentRevision == \"00\" and .data.status == 3"
as "$QC_TOKEN" POST quality/documents/revisions/action "{\"id\":$DREV2,\"action\":\"distribute\",\"recipientUserIds\":[$PRODID,$WHID],\"recipientUnits\":[\"Assembly\"]}"; check "effective revision distributed" "([.data.revisions[]|select(.id==$DREV2)|.distributions|length][0]) == 3"
DIST=$(jq -r ".data.revisions[]|select(.id==$DREV2)|.distributions[]|select(.recipientUserId==$PRODID)|.id" "$B")
as "$WH_TOKEN" POST quality/documents/revisions/action "{\"id\":$DREV2,\"action\":\"acknowledge\",\"distributionId\":$DIST}"; no "a recipient cannot acknowledge for someone else"
as "$PROD_TOKEN" POST quality/documents/revisions/action "{\"id\":$DREV2,\"action\":\"acknowledge\",\"distributionId\":$DIST}"; check "recipient acknowledges receipt" ".success and ([.data.revisions[]|select(.id==$DREV2)|.distributions[]|select(.id==$DIST)|.acknowledgedAt][0] != null)"
as "$QC_TOKEN" POST quality/documents/revisions "{\"documentId\":$DOC2,\"revision\":\"01\",\"changeSummary\":\"Added NDT hold points\",\"fileDocumentId\":\"$DOCID\"}"; DREV3=$(val '.data.revisions[]|select(.revision=="01")|.id')
as "$ENG_TOKEN" POST quality/documents/revisions/action "{\"id\":$DREV3,\"action\":\"review\"}"
as "$QA_TOKEN" POST quality/documents/revisions/action "{\"id\":$DREV3,\"action\":\"approve\",\"effectiveDate\":\"$D0\"}"; check "new revision effective; the previous one becomes obsolete" "([.data.revisions[]|select(.revision==\"00\")|.status][0] == 4) and ([.data.revisions[]|select(.revision==\"01\")|.status][0] == 3) and .data.currentRevision == \"01\""
# R1q D41: a revision approved with an effective date in the future does not replace the revision in force today (the floor keeps working to revision 01 until that day)
as "$QC_TOKEN" POST quality/documents/revisions "{\"documentId\":$DOC2,\"revision\":\"02\",\"changeSummary\":\"Coating hold point added\",\"fileDocumentId\":\"$DOCID\"}"; DREV4=$(val '.data.revisions[]|select(.revision=="02")|.id')
as "$ENG_TOKEN" POST quality/documents/revisions/action "{\"id\":$DREV4,\"action\":\"review\"}"
as "$QA_TOKEN" POST quality/documents/revisions/action "{\"id\":$DREV4,\"action\":\"approve\",\"effectiveDate\":\"$(dd 10)\"}"; check "r1q D41: revision 02 approved for a day ten days ahead is Scheduled (5) and revision 01 stays effective and current" ".success and ([.data.revisions[]|select(.revision==\"02\")|.status][0] == 5) and ([.data.revisions[]|select(.revision==\"02\")|.effectiveDate[0:10]][0] == \"$(dd 10)\") and ([.data.revisions[]|select(.revision==\"01\")|.status][0] == 3) and .data.currentRevision == \"01\" and .data.status == 3"
as "$QC_TOKEN" GET quality/documents/master-list; check "r1q D41: the master list still carries revision 01 of the document" "([.data.data[]|select(.id == $DOC2)|.currentRevision][0]) == \"01\" and ([.data.data[]|select(.id == $DOC2)|.status][0]) == 3"
as "$QC_TOKEN" POST quality/documents/revisions "{\"documentId\":$DOC2,\"revision\":\"03\",\"changeSummary\":\"x\",\"fileDocumentId\":\"$DOCID\"}"; nomsg "r1q D41: no further revision is drafted while one waits for its day" "برنامه‌ریزی شده است"
as "$QA_TOKEN" POST quality/documents/revisions/action "{\"id\":$DREV4,\"action\":\"obsolete\"}"; check "r1q D41: QA withdraws the scheduled revision: it becomes obsolete and revision 01 is still the one in force" ".success and ([.data.revisions[]|select(.revision==\"02\")|.status][0] == 4) and ([.data.revisions[]|select(.revision==\"01\")|.status][0] == 3) and .data.currentRevision == \"01\" and .data.status == 3"
as "$QC_TOKEN" GET quality/documents/master-list; check "master list holds only effective documents" '.success and ([.data.data[]|.status]|all(. == 3)) and (.data.data|length) >= 1'
as "$QC_TOKEN" GET quality/retention; check "retention rules seeded with a source" '.success and (.data|length) >= 3'
as "$QA_TOKEN" POST quality/retention '{"recordType":"Welding procedures","permanent":true,"source":"Company rule"}'; check "retention rule saved by QA" '.success'

# --- L. audits, findings and management review
as "$QA_TOKEN" POST quality/audit-programs '{"year":1405,"scope":"All units, ISO 9001:2015 clause 9.2"}'; check "annual audit program" '.success and .data.id > 0'
APR=$(val .data.id)
call POST quality/audits "{\"programId\":$APR,\"auditedUnit\":\"QC\",\"criteria\":\"ISO 9001:2015\",\"plannedDate\":\"$(dd 5)\",\"leadAuditorUserId\":$QCID}"; check "auditor cannot audit his own unit (independence, ISO 9.2)" '.success == false'
call POST quality/audits "{\"programId\":$APR,\"auditedUnit\":\"QC\",\"criteria\":\"ISO 9001:2015, WI-QC-004\",\"plannedDate\":\"$(dd 5)\",\"leadAuditorUserId\":$QAID,\"teamUserIds\":[$ENGID]}"; check "audit planned by an auditor from another unit" '.success and (.data.number|startswith("AUD-")) and .data.status == 0'
AUD=$(val .data.id)
as "$WH_TOKEN" POST quality/audits/findings "{\"auditId\":$AUD,\"clause\":\"7.1.5\",\"type\":2,\"evidence\":\"x\"}"; no "warehouse cannot add findings"
call POST quality/audits/action "{\"id\":$AUD,\"action\":\"done\"}"; no "audit cannot be marked done without its report"
call POST quality/audits/findings "{\"auditId\":$AUD,\"clause\":\"7.1.5\",\"type\":2,\"evidence\":\"Two calipers without calibration label\"}"; check "minor nonconformance finding drafts a CAPA automatically" '.success and (.data.findings|length) == 1 and .data.findings[0].capaId != null'
AFC=$(val '.data.findings[0].capaId')
call POST quality/audits/findings "{\"auditId\":$AUD,\"clause\":\"8.5\",\"type\":3,\"evidence\":\"Good practice in packing\"}"; check "observation does not create a CAPA" '.success and ([.data.findings[]|select(.type==3)|.capaId][0] == null)'
call POST quality/audits/action "{\"id\":$AUD,\"action\":\"done\",\"reportDocumentId\":\"$DOCID\"}"; check "audit done with its report" '.success and .data.status == 1'
call POST quality/audits/action "{\"id\":$AUD,\"action\":\"close\"}"; nomsg "audit cannot be closed while the finding CAPA is open" "CAPA"
capa_cycle $AFC $PRODID "$PROD_TOKEN"; CAA=$(val '.data.actions[0].id')
as "$PROD_TOKEN" POST quality/capas/action "{\"id\":$AFC,\"action\":\"complete-action\",\"actionId\":$CAA,\"note\":\"Labels fitted\",\"date\":\"$(dd -7)\"}"; check "the CAPA of the audit finding: its action is done (7 days ago)" '.success'
as "$PROD_TOKEN" POST quality/capas/action "{\"id\":$AFC,\"action\":\"implemented\"}"; check "the CAPA of the audit finding is implemented" '.success and .data.status == 2'
as "$QC_TOKEN" POST quality/capas/action "{\"id\":$AFC,\"action\":\"effectiveness\",\"note\":\"All labelled\",\"passed\":true}"; check "the CAPA of the audit finding: effectiveness verified by QC" '.success and .data.status == 3'
as "$QA_TOKEN" POST quality/capas/action "{\"id\":$AFC,\"action\":\"close\"}"; nomsg "r1q M11: QA, who defined the CAPA of the finding, does not close it (segregation of duties)" "تفکیک وظایف"
as "$QC2_TOKEN" POST quality/capas/action "{\"id\":$AFC,\"action\":\"close\"}"; check "the CAPA of the audit finding is closed by another quality person" '.success and .data.status == 4'
call POST quality/audits/action "{\"id\":$AUD,\"action\":\"close\"}"; check "audit closed once the CAPA is closed" '.success and .data.status == 2'
as "$QA_TOKEN" POST quality/settings '{"key":"EffectivenessWaitDays","value":30}'; check "r1q D20: the waiting period of the effectiveness check is back to 30 days" '.success and ([.data[]|select(.key=="EffectivenessWaitDays")|.value][0] == 30)'
# management review: inputs are computed from the system data
call POST quality/management-reviews "{\"reviewDate\":\"$D0\",\"attendees\":\"CEO, QA, QC, Production\"}"; check "management review drafted with the 12 inputs of clause 9.3.2" '.success and (.data.inputs|length) == 12'
MR1=$(val .data.id)
check "inputs for CAPA/NCR, audits, objectives are computed by the system" '([.data.inputs[]|select(.category==6)|.autoDrafted][0] == true) and ([.data.inputs[]|select(.category==8)|.autoDrafted][0] == true) and ([.data.inputs[]|select(.category==3)|.autoDrafted][0] == true)'
MRCATS=$(jq -r '.data.inputs[]|select(.text == null or .text == "")|.category' "$B")
call POST quality/management-reviews/action "{\"id\":$MR1,\"action\":\"hold\"}"; check "review cannot be held while inputs are empty" '.success == false and (.message|contains("9.3.2") or contains("ورودی"))'
for CATN in $MRCATS; do
  call POST quality/management-reviews/input "{\"reviewId\":$MR1,\"category\":$CATN,\"text\":\"Reviewed in the meeting.\"}"
done
call POST quality/management-reviews/action "{\"id\":$MR1,\"action\":\"hold\"}"; check "review held after the inputs are complete" '.success and .data.status == 1'
call POST quality/management-reviews/decision "{\"reviewId\":$MR1,\"text\":\"Add a second calibration technician\",\"responsibleUserId\":$QCID,\"dueDate\":\"$(dd 30)\",\"createCapa\":true}"; check "decision with an action creates a CAPA" '.success and (.data.decisions|length) == 1 and .data.decisions[0].capaId != null'
MRD1=$(val '.data.decisions[0].id')
call POST quality/management-reviews/decision "{\"reviewId\":$MR1,\"text\":\"Update the calibration schedule\",\"responsibleUserId\":$ENGID,\"dueDate\":\"$(dd 20)\"}"; check "r1q D23: a second decision, without a CAPA" '.success and (.data.decisions|length) == 2 and ([.data.decisions[]|.status]|all(. == 0))'
MRD2=$(val '[.data.decisions[]|select(.text == "Update the calibration schedule")][0].id')
call POST quality/management-reviews/decision "{\"reviewId\":$MR1,\"text\":\"Brief the gate staff on the visitor procedure\",\"responsibleUserId\":$SECID,\"dueDate\":\"$(dd 25)\"}"; check "r1q M17: a third decision, of the security officer (who is not a quality reader)" '.success and (.data.decisions|length) == 3'
MRD3=$(val '[.data.decisions[]|select(.text == "Brief the gate staff on the visitor procedure")][0].id')
call POST quality/management-reviews/decision "{\"reviewId\":$MR1,\"text\":\"Review the quality objectives every quarter\",\"responsibleUserId\":$QAID,\"dueDate\":\"$(dd 40)\"}"; check "r1q M17: a fourth decision, of the QA manager himself" '.success and (.data.decisions|length) == 4'
MRD4=$(val '[.data.decisions[]|select(.text == "Review the quality objectives every quarter")][0].id')
call POST quality/management-reviews/action "{\"id\":$MR1,\"action\":\"close\"}"; no "review cannot be closed without the minutes (FO-QA-022)"
call POST quality/management-reviews/action "{\"id\":$MR1,\"action\":\"close\",\"minutesDocumentId\":\"$DOCID\"}"; check "management review closed with the minutes" '.success and .data.status == 2'
# R1q D23 and review M17: after the meeting the decisions are followed up: an open decision is a task of its responsible person with the due date. The responsible person reports the work done, and a reviewer
# (QA, PMO, the CEO) who is not that person confirms it; only then is the decision done. The responsible person reads the review his decision belongs to, with his own decisions only.
as "$QC_TOKEN" GET "office/inbox?SourceKey=review-decision:$MRD1"; check "r1q D23: the open decision is a task in the inbox of the responsible person, due on its date, and the link opens the review" ".success and (.data.data|length) == 1 and (.data.data[0].dueDate[0:10]) == \"$(dd 30)\" and .data.data[0].link == \"/quality/management-reviews/$MR1\""
as "$SEC_TOKEN" GET "quality/management-reviews/$MR1"; check "r1q M17: the security officer, who is not a quality reader, reads the closed review his decision belongs to: his own decision only and none of the inputs" ".success and (.data.decisions|length) == 1 and .data.decisions[0].id == $MRD3 and (.data.inputs|length) == 0"
as "$FM_TOKEN" GET "quality/management-reviews/$MR1"; nomsg "r1q M17: the finance manager, who is neither a reader nor responsible for a decision of it, cannot read it" "شما مجوز این کار را ندارید"
as "$QC_TOKEN" POST quality/management-reviews/decision/action "{\"decisionId\":$MRD1,\"action\":\"done\"}"; nomsg "r1q D23: a decision is reported done with a written note" "شرح اقدام انجام‌شده"
as "$QC_TOKEN" POST quality/management-reviews/decision/action "{\"decisionId\":$MRD1,\"action\":\"done\",\"note\":\"Technician hired\"}"; nomsg "r1q D23: ... and not before the CAPA of the decision is closed" "هنوز بسته نشده است"
as "$WH_TOKEN" POST quality/management-reviews/decision/action "{\"decisionId\":$MRD2,\"action\":\"done\",\"note\":\"Schedule updated\"}"; nomsg "r1q D23: somebody who is neither responsible nor a reviewer cannot report it" "شما مجوز این کار را ندارید"
as "$ENG_TOKEN" POST quality/management-reviews/decision/action "{\"decisionId\":$MRD2,\"action\":\"done\",\"note\":\"Schedule updated\"}"; check "r1q M17: the responsible person reports his decision done: it stays open and waits for the confirmation of QA or PMO" ".success and ([.data.decisions[]|select(.id == $MRD2)|.status][0] == 0) and ([.data.decisions[]|select(.id == $MRD2)|.doneRequested][0] == true) and ([.data.decisions[]|select(.id == $MRD2)|.doneRequestedByName][0] != null) and ([.data.decisions[]|select(.id == $MRD2)|.doneAt][0] == null)"
as "$ENG_TOKEN" GET "office/inbox?SourceKey=review-decision:$MRD2"; check "r1q M17: the reported decision leaves the inbox of its owner" '.success and (.data.data|length) == 0'
as "$QA_TOKEN" GET "office/inbox?SourceKey=review-decision-confirm:$MRD2"; check "r1q M17: ... and becomes a task of QA and PMO to confirm" '.success and (.data.data|length) == 1'
as "$ENG_TOKEN" POST quality/management-reviews/decision/action "{\"decisionId\":$MRD2,\"action\":\"done\",\"note\":\"Schedule updated, confirm please\"}"; nomsg "r1q M17: the owner cannot confirm his own report: it waits for QA or PMO" "منتظر تایید QA یا PMO است"
as "$QA_TOKEN" POST quality/management-reviews/decision/action "{\"decisionId\":$MRD2,\"action\":\"return\"}"; nomsg "r1q M17: a report is sent back with a written reason" "دلیل برگرداندن گزارش انجام را بنویسید"
as "$QA_TOKEN" POST quality/management-reviews/decision/action "{\"decisionId\":$MRD2,\"action\":\"return\",\"note\":\"Attach the revised schedule\"}"; check "r1q M17: QA sends the report back with the reason: the decision is the owner's task again" ".success and ([.data.decisions[]|select(.id == $MRD2)|.status][0] == 0) and ([.data.decisions[]|select(.id == $MRD2)|.doneRequested][0] == false)"
as "$ENG_TOKEN" GET "office/inbox?SourceKey=review-decision:$MRD2"; check "r1q M17: ... and it is back in his inbox" '.success and (.data.data|length) == 1'
as "$ENG_TOKEN" POST quality/management-reviews/decision/action "{\"decisionId\":$MRD2,\"action\":\"done\",\"note\":\"Revised schedule attached, document FO-QC-31\"}"; check "r1q M17: the owner reports it again" ".success and ([.data.decisions[]|select(.id == $MRD2)|.doneRequested][0] == true)"
as "$QA_TOKEN" POST quality/management-reviews/decision/action "{\"decisionId\":$MRD2,\"action\":\"done\",\"note\":\"Schedule checked against the calibration plan\"}"; check "r1q M17: QA, who is not the owner, confirms: the decision is done; the day and the person are kept" ".success and ([.data.decisions[]|select(.id == $MRD2)|.status][0] == 1) and ([.data.decisions[]|select(.id == $MRD2)|.doneAt][0] != null) and ([.data.decisions[]|select(.id == $MRD2)|.doneByName][0] != null) and ([.data.decisions[]|select(.id == $MRD2)|.doneNote][0] == \"Schedule checked against the calibration plan\")"
as "$QA_TOKEN" GET "office/inbox?SourceKey=review-decision-confirm:$MRD2"; check "r1q M17: the confirmation task is closed" '.success and (.data.data|length) == 0'
as "$SEC_TOKEN" POST quality/management-reviews/decision/action "{\"decisionId\":$MRD3,\"action\":\"done\",\"note\":\"Gate staff briefed on Sunday\"}"; check "r1q M17: the security officer (not a quality reader) reports his decision; the answer holds his decision only" ".success and (.data.decisions|length) == 1 and .data.decisions[0].id == $MRD3 and .data.decisions[0].doneRequested == true and (.data.inputs|length) == 0"
as "$QA_TOKEN" POST quality/management-reviews/decision/action "{\"decisionId\":$MRD4,\"action\":\"cancel\",\"note\":\"Not needed\"}"; nomsg "r1q M17: nobody cancels a decision he is responsible for himself" "خودتان لغو نمی‌کنید"
as "$QA_TOKEN" POST quality/management-reviews/decision/action "{\"decisionId\":$MRD4,\"action\":\"done\",\"note\":\"Quarterly review put in the calendar\"}"; check "r1q M17: the QA manager, responsible for his own decision, reports it done: it waits for somebody else" ".success and ([.data.decisions[]|select(.id == $MRD4)|.status][0] == 0) and ([.data.decisions[]|select(.id == $MRD4)|.doneRequested][0] == true)"
call POST quality/management-reviews/decision/action "{\"decisionId\":$MRD4,\"action\":\"done\",\"note\":\"Calendar entry checked\"}"; check "r1q M17: the PMO confirms it" ".success and ([.data.decisions[]|select(.id == $MRD4)|.status][0] == 1)"
as "$QC_TOKEN" POST quality/management-reviews/decision/action "{\"decisionId\":$MRD1,\"action\":\"cancel\",\"note\":\"x\"}"; nomsg "r1q D23: cancelling a decision is for QA, the CEO or PMO" "لغو تصمیم بازنگری"
as "$QA_TOKEN" POST quality/management-reviews/decision/action "{\"decisionId\":$MRD1,\"action\":\"cancel\"}"; nomsg "r1q D23: ... with a reason" "دلیل لغو تصمیم را بنویسید"
as "$QA_TOKEN" POST quality/management-reviews/decision/action "{\"decisionId\":$MRD1,\"action\":\"cancel\",\"note\":\"Replaced by an outsourced calibration contract\"}"; check "r1q D23: QA cancels the decision with the reason" ".success and ([.data.decisions[]|select(.id == $MRD1)|.status][0] == 2) and ([.data.decisions[]|select(.id == $MRD1)|.doneNote][0] == \"Replaced by an outsourced calibration contract\")"
as "$QA_TOKEN" POST quality/management-reviews/decision/action "{\"decisionId\":$MRD1,\"action\":\"reopen\",\"note\":\"Contract not signed\"}"; check "r1q D23: and reopens it when the plan fails; the decision is open again with no done day" ".success and ([.data.decisions[]|select(.id == $MRD1)|.status][0] == 0) and ([.data.decisions[]|select(.id == $MRD1)|.doneAt][0] == null)"

# --- M. release note, final data book and the delivery gate
as "$QC_TOKEN" POST quality/itps/activity/action "{\"id\":$A6,\"action\":\"plan\",\"date\":\"$(dd 3)\"}"; check "packing activity planned" '.success'
# R1q D22: the product is released only after the last final inspection of the work order accepted it (and when every production order of it is complete)
as "$QC_TOKEN" GET "quality/work-orders/$WO1/release-checks"; check "r1q D22: without a final inspection record the release checks fail on that one check only" '.success and .data.canRelease == false and ([.data.checks[]|select(.code=="FINAL_INSPECTION")|.passed][0] == false) and ([.data.checks[]|select(.code != "FINAL_INSPECTION")|.passed]|all) and ([.data.checks[]|select(.code=="PRODUCTION_COMPLETE")|.passed][0] == true)'
as "$QC_TOKEN" POST quality/records "{\"type\":2,\"workOrderId\":$WO1,\"itemId\":$BOLT,\"operation\":\"Final inspection of pump unit 1\",\"quantity\":1,\"result\":2,\"note\":\"Paint chipped at the nameplate\"}"; check "r1q D22: a rejected final inspection drafts an NCR of the final source and does not open the release" '.success and .data.result == 2 and .data.ncrId != null'
FNCR=$(val .data.ncrId)
as "$QC_TOKEN" GET "quality/work-orders/$WO1/release-checks"; check "r1q D22: the last final inspection rejected: the check names the result; the NCR of the work order blocks as well" '.success and .data.canRelease == false and ([.data.checks[]|select(.code=="FINAL_INSPECTION")|.passed][0] == false) and ([.data.checks[]|select(.code=="FINAL_INSPECTION")|.detail][0] == "نتیجه آخرین بازرسی نهایی: رد") and ([.data.checks[]|select(.code=="NO_OPEN_NCR")|.passed][0] == false)'
as "$QC2_TOKEN" POST inventory/quality/ncr/close "{\"id\":$FNCR,\"cancel\":true,\"reason\":\"Repainted and re-inspected\"}"; nomsg "r1q D3: the NCR of the final inspection stays until an accepted re-inspection of the product exists" "تا بازرسی مجدد قبول‌شده‌ای"
as "$QC_TOKEN" POST quality/records "{\"type\":2,\"workOrderId\":$WO1,\"itemId\":$BOLT,\"operation\":\"Final inspection of pump unit 1\",\"quantity\":1,\"result\":1}"; check "r1q D22: the final inspection repeated after the repair is accepted" '.success and .data.result == 1'
as "$QC2_TOKEN" POST inventory/quality/ncr/close "{\"id\":$FNCR,\"cancel\":true,\"reason\":\"Repainted and re-inspected\"}"; check "r1q D3: ... and then another QC user cancels the NCR with the reason" '.success and .data.status == 4'
as "$QC_TOKEN" GET "quality/work-orders/$WO1/release-checks"; check "all release checks of work order 1 pass (computed)" '.success and .data.canRelease == true and ([.data.checks[]|.passed]|all)'
as "$QC_TOKEN" GET "quality/work-orders/$WO1/data-book"; check "final data book: 10 sections, nothing mandatory missing" '.success and (.data.sections|length) == 10 and .data.missingCount == 0 and ([.data.sections[]|select(.no==6)|.entries[]|select(.sourceKind=="TestReport")]|length) >= 1'
as "$QC_TOKEN" GET "quality/release-notes/$RN1"; check "the same release note can now be released (computed checks all pass)" '.success and .data.status == 0 and .data.canRelease == true'
as "$QA_TOKEN" POST quality/release-notes/action "{\"id\":$RN1,\"action\":\"release\"}"; nomsg "the release note is signed by QC (QA refused)" "مدیر QC"
as "$QC_TOKEN" POST quality/release-notes "{\"workOrderId\":$WO1,\"itemsText\":\"duplicate\"}"; nomsg "second active release note for the same work order rejected" "برگه ترخیص فعال"
as "$QC_TOKEN" POST quality/release-notes "{\"workOrderId\":$WO2,\"itemsText\":\"Feed pump unit 2\",\"lines\":[{\"itemId\":$BOLT,\"quantity\":1}]}"; RN2=$(val .data.id)
as "$QC2_TOKEN" POST quality/release-notes/action "{\"id\":$RN2,\"action\":\"release\"}"; check "work order 2 cannot be released: ITP not approved, open NCRs, reports missing" '.success == false and (.message|contains("ترخیص"))'
as "$QC_TOKEN" GET "quality/work-orders/$WO2/release-checks"; check "work order 2 checks fail for the ITP and the open NCR" '.data.canRelease == false and ([.data.checks[]|select(.code=="ITP_APPROVED")|.passed][0] == false) and ([.data.checks[]|select(.code=="NO_OPEN_NCR")|.passed][0] == false)'
# delivery gate: no release -> no customer delivery
mkdelivery() { # mkdelivery WORKORDER [QUANTITY of bolts, default 1] (empty work order = none)
  local wo="" q=${2:-1}; [ -n "$1" ] && wo=",\"workOrderId\":$1"
  call POST inventory/documents "{\"type\":11,\"documentDate\":\"$D0\",\"warehouseId\":$W1,\"contractId\":$QCT$wo,\"driverName\":\"Driver\",\"vehiclePlate\":\"11A111\",\"receiverName\":\"Client rep\",\"lines\":[{\"itemId\":$BOLT,\"quantity\":$q}]}"
}
mkdelivery $WO2; DL2=$(val .data.id); as "$QC_TOKEN" POST "inventory/documents/$DL2/approve" '{"kind":4}'
call POST "inventory/documents/$DL2/confirm"; check "customer delivery of a work order without a release note refused" '.success == false and (.message|contains("ترخیص"))'
mkdelivery ""; DL0=$(val .data.id); as "$QC_TOKEN" POST "inventory/documents/$DL0/approve" '{"kind":4}'
call POST "inventory/documents/$DL0/confirm"; check "customer delivery without a work order refused (release cannot be checked)" '.success == false and (.message|contains("دستور کار"))'
as "$QC_TOKEN" GET "quality/work-orders/$WO1/data-book"; COMPANY_N=$(jq '[.data.sections[].entries[]]|length' "$B"); check "data book default variant is company (every entry)" '.data.variant == "company"'
as "$QC_TOKEN" GET "quality/work-orders/$WO1/data-book?variant=client"; check "client data book: only entries the client receives (ITP, reports with a client point, release note), fewer than the company book" ".success and .data.variant == \"client\" and ([.data.sections[].entries[]|.clientRelevant]|all) and ([.data.sections[].entries[]]|length) < $COMPANY_N and ([.data.sections[].entries[]|select(.sourceKind==\"Itp\")]|length) == 1 and ([.data.sections[].entries[]|select(.sourceKind==\"Equipment\")]|length) == 0"
as "$QC_TOKEN" GET "quality/work-orders/$WO1/data-book?variant=x"; no "unknown data book variant rejected"
as "$QC_TOKEN" POST quality/release-notes/action "{\"id\":$RN1,\"action\":\"release\"}"; nomsg "r1q D22: the drafter of the note is still refused when every check passes" "کسی که آن را تنظیم یا ویرایش کرده نمی‌تواند صادر کند"
as "$QC2_TOKEN" POST quality/release-notes/action "{\"id\":$RN1,\"action\":\"release\"}"; check "release note signed by a second QC manager: certificate of conformity numbered (r1q D22: not the person who drafted it)" '.success and .data.status == 1 and (.data.certificateOfConformityNumber|startswith("CoC-")) and .data.releasedByName != null and .data.releasedByName != .data.draftedByName and ([.data.checks[]|.passed]|all)'
as "$QC2_TOKEN" POST quality/release-notes/action "{\"id\":$RN1,\"action\":\"release\"}"; nomsg "release note cannot be released twice" "فقط برگه پیش‌نویس صادر می‌شود"
as "$QC_TOKEN" POST quality/release-notes "{\"id\":$RN1,\"workOrderId\":$WO1,\"itemsText\":\"changed\"}"; nomsg "a released note cannot be edited" "ویرایش نمی"
as "$QC_TOKEN" GET "quality/work-orders/$WO1/data-book"; check "data book: release note section now complete" '[.data.sections[]|select(.no==10)|.entries[0].missing][0] == false'
# R1q D10: the delivery carries only what the released note lists, and only while no non-conformance is open on the work order
mkdelivery $WO1 6; DL3=$(val .data.id); as "$QC_TOKEN" POST "inventory/documents/$DL3/approve" '{"kind":4}'
call POST "inventory/documents/$DL3/confirm"; nomsg "r1q D10: a delivery of 6 bolts against a release note that lists 5 is refused" "از مقدار ترخیص‌شده (5) بیشتر است"
ncr "{\"source\":2,\"severity\":1,\"itemId\":$BOLT,\"quantity\":1,\"workOrderId\":$WO1,\"description\":\"Found after the release\"}"; NCR8=$(val .data.id); NCR8NUM=$(val .data.number)
mkdelivery $WO1 1; DL1=$(val .data.id); as "$QC_TOKEN" POST "inventory/documents/$DL1/approve" '{"kind":4}'
call POST "inventory/documents/$DL1/confirm"; check "r1q D10: an NCR raised after the release stops the delivery until it is closed or cancelled; the NCR number is named" ".success == false and (.message|contains(\"تا بسته‌شدن عدم انطباق‌های باز\")) and (.message|contains(\"$NCR8NUM\"))"
as "$QC2_TOKEN" POST inventory/quality/ncr/close "{\"id\":$NCR8,\"cancel\":true,\"reason\":\"Entered against the wrong work order\"}"; check "r1q D3: another QC user cancels that NCR (a report with no inspection or test behind it)" '.success and .data.status == 4'
call POST "inventory/documents/$DL1/confirm"; check "customer delivery of the released work order is confirmed" '.success and .data.status == 1'
mkdelivery $WO1 5; DL4=$(val .data.id); as "$QC_TOKEN" POST "inventory/documents/$DL4/approve" '{"kind":4}'
call POST "inventory/documents/$DL4/confirm"; nomsg "r1q D10: earlier deliveries are counted: 1 delivered, 5 more would make 6 of the 5 released" "از مقدار ترخیص‌شده (5) بیشتر است"
mkdelivery $WO1 2; DL5=$(val .data.id); as "$QC_TOKEN" POST "inventory/documents/$DL5/approve" '{"kind":4}'
call POST "inventory/documents/$DL5/confirm"; check "r1q D10: two more bolts, within the released list, are delivered (3 of 5)" '.success and .data.status == 1'
mkdelivery $WO1 3; DL6=$(val .data.id); as "$QC_TOKEN" POST "inventory/documents/$DL6/approve" '{"kind":4}'
call POST "inventory/documents/$DL6/confirm"; nomsg "r1q D10: three more would go over the list (3 of 5 delivered, 6 asked)" "از مقدار ترخیص‌شده (5) بیشتر است"

# --- N. ITP revision after approval (snapshot) and settings
# R1q review H6: ITP 2 was drafted by the system; the client's approval is recorded by somebody who did not submit or change it
as "$QC_TOKEN" POST quality/itps/action "{\"id\":$ITP2,\"action\":\"submit\"}"; check "ITP 2 (drafted by the system) is submitted by the QC user" '.success and .data.status == 1'
as "$QC_TOKEN" POST quality/itps/action "{\"id\":$ITP2,\"action\":\"client-approve\",\"reference\":\"CL-2-1\"}"; nomsg "r1q H6: the QC user who submitted the plan cannot record the client's approval of it" "تفکیک وظایف"
call POST quality/itps "{\"id\":$ITP2,\"noticeDays\":10}"; check "r1q H6: the PMO account saves the plan (and so becomes one of its editors)" '.success and .data.noticeDays == 10 and .data.status == 1'
call POST quality/itps/action "{\"id\":$ITP2,\"action\":\"client-approve\",\"reference\":\"CL-2-1\"}"; nomsg "r1q H6: ... and cannot record the client's approval either" "تفکیک وظایف"
as "$QA_TOKEN" POST quality/itps/action "{\"id\":$ITP2,\"action\":\"client-approve\",\"reference\":\"CL-2-1\",\"date\":\"$(dd -3)\"}"; check "ITP 2 approved (recorded by the QA manager, who did not touch the plan, with the day of the client's letter, 3 days ago)" ".success and .data.status == 2 and (.data.clientApprovalDate[0:10]) == \"$(dd -3)\""
A2_1=$(val '.data.activities[0].id')
as "$QC_TOKEN" POST quality/itps/activity "{\"id\":$A2_1,\"itpId\":$ITP2,\"seq\":1,\"activity\":\"Material certificates of pressure-containing parts (revised)\",\"pointVendor\":1,\"pointTpi\":3,\"pointClient\":3}"; nomsg "changing an approved ITP needs a written reason" "دلیل تغییر"
as "$QC_TOKEN" POST quality/itps/activity "{\"id\":$A2_1,\"itpId\":$ITP2,\"seq\":1,\"activity\":\"Material certificates of pressure-containing parts (revised)\",\"pointVendor\":1,\"pointTpi\":3,\"pointClient\":3,\"reason\":\"Client asked for review of all certificates\"}"; check "approved ITP edited with a reason: revision 1 (first issue is 0), back to draft, old revision kept" '.success and .data.revision == 1 and .data.status == 0 and (.data.revisions|length) >= 1'
as "$QA_TOKEN" GET quality/settings; check "quality settings: defaults with their source, major NCR committee minimum 3" '.success and ([.data[]|select(.key=="MajorNcrCommitteeMin")|.value][0] == 3) and ([.data[]|select(.key=="ItpNoticeDaysIran")|.value][0] == 10) and ([.data[]|.source]|all(. != null))'
as "$WH_TOKEN" POST quality/settings '{"key":"ItpNoticeDaysIran","value":12}'; no "warehouse cannot change quality settings"
as "$QA_TOKEN" POST quality/settings '{"key":"NotASetting","value":1}'; no "unknown setting rejected"
as "$QA_TOKEN" POST quality/settings '{"key":"CalibrationWarnDays","value":45}'; check "setting changed by QA" '[.data[]|select(.key=="CalibrationWarnDays")|.value][0] == 45 and [.data[]|select(.key=="CalibrationWarnDays")|.isDefault][0] == false'
as "$QA_TOKEN" POST quality/settings '{"key":"CalibrationWarnDays","value":30}'
# R1q D30: every setting has its range; the answer names the range, so a check cannot pass for an unrelated reason
as "$QA_TOKEN" POST quality/settings '{"key":"MajorNcrCommitteeMin","value":1}'; nomsg "r1q D30: a technical committee for a major NCR has at least two members (1 refused)" "باید عدد صحیح بین 2 تا 10 باشد"
as "$QA_TOKEN" POST quality/settings '{"key":"WeldContinuityMonths","value":3650}'; nomsg "r1q D30: a welder continuity of 3650 months is refused (ASME IX QW-322: the range is 1 to 12 months)" "باید عدد صحیح بین 1 تا 12 باشد"
as "$QA_TOKEN" POST quality/settings '{"key":"NcrMinorDueDays","value":7.5}'; nomsg "r1q D30: days are whole numbers (7.5 refused)" "باید عدد صحیح بین 1 تا 180 باشد"
as "$QA_TOKEN" POST quality/settings '{"key":"EffectivenessWaitDays","value":400}'; nomsg "r1q D30: a waiting period beyond a year is refused (the range is 7 to 365 days since the review)" "باید عدد صحیح بین 7 تا 365 باشد"
as "$QA_TOKEN" GET quality/settings; check "r1q D30: the refused values were not stored (committee minimum still 3, minor NCR period still 7, welder continuity still 6 months and a default)" '.success and ([.data[]|select(.key=="MajorNcrCommitteeMin")|.value][0] == 3) and ([.data[]|select(.key=="NcrMinorDueDays")|.value][0] == 7) and ([.data[]|select(.key=="WeldContinuityMonths")|.value][0] == 6) and ([.data[]|select(.key=="WeldContinuityMonths")|.isDefault][0] == true) and ([.data[]|select(.key=="WeldContinuityMonths")|.max][0] == 12)'
as "$QA_TOKEN" POST quality/settings '{"key":"WeldContinuityMonths","value":12}'; check "r1q D30: twelve months, the top of the range, is accepted and stored" '.success and ([.data[]|select(.key=="WeldContinuityMonths")|.value][0] == 12) and ([.data[]|select(.key=="WeldContinuityMonths")|.isDefault][0] == false)'
as "$QA_TOKEN" POST quality/settings '{"key":"WeldContinuityMonths","value":6}'; check "r1q D30: ... and put back to the six months of the standard" '.success and ([.data[]|select(.key=="WeldContinuityMonths")|.value][0] == 6)'
# R1q review H6 and M14: the minimum of the witness notice period (company setting, 1 to 30 days, default 1) and the ranges of the other new settings
as "$QA_TOKEN" GET quality/settings; check "r1q M14: the new settings carry their ★ default and their range: back-date window 7 (0-30), waiting period of the effectiveness check 30 (7-365, put back by QA), minimum witness notice 1 (1-30)" '.success and ([.data[]|select(.key=="MaxBackdateDays")|[.value,.min,.max,.isDefault]][0] == [7,0,30,true]) and ([.data[]|select(.key=="EffectivenessWaitDays")|[.value,.min,.max]][0] == [30,7,365]) and ([.data[]|select(.key=="MinNoticeDays")|[.value,.min,.max,.isDefault]][0] == [1,1,30,true])'
as "$QA_TOKEN" POST quality/settings '{"key":"MaxBackdateDays","value":31}'; nomsg "r1q M14: a back-date window beyond a month is refused" "باید عدد صحیح بین 0 تا 30 باشد"
as "$QA_TOKEN" POST quality/settings '{"key":"MinNoticeDays","value":31}'; nomsg "r1q H6: the company minimum of the witness notice is at most 30 days (31 refused)" "باید عدد صحیح بین 1 تا 30 باشد"
as "$QA_TOKEN" POST quality/settings '{"key":"MinNoticeDays","value":0}'; nomsg "r1q H6: ... and at least one day (0 refused: a notice of no days would waive the client's witness at once)" "باید عدد صحیح بین 1 تا 30 باشد"
as "$QA_TOKEN" POST quality/settings '{"key":"MinNoticeDays","value":14}'; check "r1q H6: QA raises the company minimum of the notice period to 14 days" '.success and ([.data[]|select(.key=="MinNoticeDays")|.value][0] == 14)'
as "$QC_TOKEN" POST quality/itps "{\"id\":$ITP2,\"noticeDays\":10}"; nomsg "r1q H6: a plan cannot be saved with a notice period under the company minimum (10 under 14)" "باید بین 14 تا 365 روز باشد"
as "$QC_TOKEN" GET "quality/itps/$ITP2"; check "r1q H6: a plan saved with fewer days than the minimum (10 under 14) is read at the minimum, so every deadline of its witness notices follows the minimum" '.success and .data.noticeDays == 14'
as "$QA_TOKEN" POST quality/settings '{"key":"MinNoticeDays","value":1}'; check "r1q H6: the minimum is back to one day" '.success and ([.data[]|select(.key=="MinNoticeDays")|.value][0] == 1)'
as "$QC_TOKEN" GET "quality/itps/$ITP2"; check "r1q H6: ... and the plan reads its own 10 days again" '.success and .data.noticeDays == 10'

# --- O. quality dashboard and CEO dashboard (computed, read-only)
as "$QA_TOKEN" GET quality/dashboard; cp "$B" "$B.dash"
check "quality dashboard: the exact counts of the scenario: 1 overdue CAPA, 1 instrument overdue and 1 due within 30 days, 1 H point waiting, no witness notice due, 3 welder certificates lapsing, 1 complaint open and overdue, no NCR past its decision day, 1 release note waiting" '.success and .data.overdueCapas == 1 and .data.calibrationOverdue == 1 and .data.calibrationDue30 == 1 and .data.pendingHPoints == 1 and .data.witnessNoticesDue == 0 and .data.qualificationsLapsing == 3 and .data.complaintsOpen == 1 and .data.complaintsOverdue == 1 and .data.overdueNcrs == 0 and .data.releaseNotesPending == 1'
check "quality dashboard: the alerts are exactly these six, with their level and count, computed from the records" '.success and ([.data.alerts[]|[.code,.level,.count]]) == [["CAPA_OVERDUE","danger",1],["CALIBRATION_OVERDUE","danger",1],["CALIBRATION_DUE","warning",1],["H_POINTS","warning",1],["QUALIFICATION","warning",3],["COMPLAINT_OVERDUE","danger",1]]'
as "$QA_TOKEN" GET quality/capas/overdue; OVC=$(jq -c '[.data.data[].id]' "$B")
as "$QA_TOKEN" GET quality/equipment/due; EQD=$(jq -c '[.data.data[].id]' "$B")
as "$QA_TOKEN" GET "quality/qualifications/continuity?Days=30"; QLC=$(jq -c '[.data.data[].id]' "$B")
as "$QA_TOKEN" GET "inventory/quality/ncr?PageSize=0"
NCRC=$(jq -c '[.data.data[]|select(.status != 3 and .status != 4)|.severity] | {notClassified:(map(select(. == 0))|length),minor:(map(select(. == 1))|length),major:(map(select(. == 2))|length)}' "$B")
cp "$B.dash" "$B"
check "quality dashboard: the lists are those of the screens behind them (same overdue CAPAs, instruments and certificates); the open NCRs by severity equal the NCR list: 3 not classified, 3 minor, 1 major, all reported within a week, none past its decision day" ".success and (.data.overdueCapaList|map(.id)) == $OVC and (.data.calibrationList|map(.id)) == $EQD and (.data.qualificationList|map(.id)) == $QLC and (.data.ncrs|{notClassified,minor,major}) == $NCRC and .data.ncrs.notClassified == 3 and .data.ncrs.minor == 3 and .data.ncrs.major == 1 and .data.ncrs.age0To7 == 7 and .data.ncrs.age8To30 == 0 and .data.ncrs.age31Plus == 0 and .data.ncrs.overdue == 0 and (.data.pendingPoints|map({workOrderCode,hPoints,wPoints})) == [{workOrderCode:\"QA-WO-1\",hPoints:1,wPoints:0}]"
as "$CEO_TOKEN" GET finance/ceo-dashboard
check "CEO dashboard: the same exact quality counts, and the six quality alerts with their texts" ".success and .data.overdueCapas == 1 and .data.calibrationOverdue == 1 and .data.pendingHPoints == 1 and .data.qualificationsLapsing == 3 and .data.complaintsOverdue == 1 and ($(jq -c '[.data.alerts[].text]' "$B.dash") - [.data.alerts[].text]) == []"
as "$QA_TOKEN" POST inventory/documents "{\"type\":1,\"documentDate\":\"2026-10-15T00:00:00\",\"warehouseId\":$W1,\"lines\":[]}"; [ "$CODE" = "403" ] && ok "QA user cannot write warehouse documents (403)" || bad "QA user cannot write warehouse documents (403) got $CODE"

# --- P. Goods under hold, expired lots, stock counts of quarantine stock, serial write-off, length checks (review M10, M13, M18, L21, L24)
# Zero-value test goods (items of their own, adjustments without a price), so the books and the stock value of the later sections stay as they are.
TOKEN=$ADMIN_TOKEN
item XSER "{\"code\":\"02130002010003\",\"title\":\"شفت آزمون نگهداری ناانطباق\",\"itemGroupId\":$G2,\"unit\":\"عدد\",\"trackingMode\":2,\"requiresIncomingInspection\":false}" "serial part for the hold and write-off tests"
item XEXP "{\"code\":\"01001026120101\",\"title\":\"میلگرد آزمون ماندگاری\",\"itemGroupId\":$G2,\"unit\":\"kg\",\"trackingMode\":1,\"shelfLifeDays\":10,\"requiresIncomingInspection\":false}" "lot material with 10 days of shelf life"
call GET "inventory/items/$XEXP"; check "r1q M13: the test material has a shelf life of 10 days and no incoming inspection (after the QA approval of its start gates)" '.success and .data.shelfLifeDays == 10 and .data.requiresIncomingInspection == false and .data.pendingQualityChangeId == null'
adjust_in() { # adjust_in DATE WAREHOUSE LINES : an increase adjustment with the approvals of the warehouse supervisor and of planning, confirmed (the answer of the confirmation stays in $B)
  call POST inventory/documents "{\"type\":7,\"documentDate\":\"${1}T00:00:00\",\"warehouseId\":$2,\"referenceNumber\":\"P-HOLD\",\"lines\":$3}"; ADJ=$(val .data.id)
  as "$SUP_TOKEN" POST "inventory/documents/$ADJ/approve" '{"kind":1}'; as "$PLAN_TOKEN" POST "inventory/documents/$ADJ/approve" '{"kind":2}'
  call POST "inventory/documents/$ADJ/confirm"
}
TRX() { echo "{\"type\":6,\"documentDate\":\"${D0}T00:00:00\",\"warehouseId\":$1,\"destinationWarehouseId\":$2,\"lines\":$3}"; } # TRX FROM TO LINES : a transfer draft
adjust_in "$D0" $W1 "[{\"itemId\":$XSER,\"quantity\":3,\"serialNumbers\":[\"XS-1\",\"XS-2\",\"XS-3\"]}]"; check "r1q M18: three pieces of the test shaft (XS-1 to XS-3) are in the main warehouse" '.success and .data.status == 1'
adjust_in "$(dd -30)" $W1 "[{\"itemId\":$XEXP,\"quantity\":10,\"lotNumber\":\"XE-OLD\"}]"; check "r1q M13: 10 kg of the test material received 30 days ago (lot XE-OLD)" '.success and .data.status == 1'
adjust_in "$D0" $W1 "[{\"itemId\":$XEXP,\"quantity\":10,\"lotNumber\":\"XE-NEW\"}]"; check "r1q M13: 10 kg received today (lot XE-NEW)" '.success and .data.status == 1'
call GET "inventory/stock/lots?ItemId=$XEXP"; XEOLD=$(val '.data.data[]|select(.lotNumber=="XE-OLD")|.id'); XENEW=$(val '.data.data[]|select(.lotNumber=="XE-NEW")|.id')
check "r1q M13: the lots expire after the shelf life counted from the day of the receipt: XE-OLD 20 days ago, XE-NEW in 10 days" "([.data.data[]|select(.lotNumber==\"XE-OLD\")|.expiryDate[0:10]][0] == \"$(dd -20)\") and ([.data.data[]|select(.lotNumber==\"XE-NEW\")|.expiryDate[0:10]][0] == \"$(dd 10)\")"

# M13: an expired lot is moved only INTO quarantine (or scrap), never to a warehouse that production or a customer draws on
call POST inventory/documents "$(TRX $W1 $W2 "[{\"itemId\":$XEXP,\"quantity\":4,\"lotId\":$XEOLD}]")"; DX=$(val .data.id)
call POST "inventory/documents/$DX/confirm"; nomsg "r1q M13: an expired lot is not transferred to a usable warehouse (the workshop)" "منقضی شده است"
call DELETE "inventory/documents/$DX"
call POST inventory/documents "$(TRX $W1 $W2 "[{\"itemId\":$XEXP,\"quantity\":4,\"lotId\":$XENEW}]")"; DX=$(val .data.id)
call POST "inventory/documents/$DX/confirm"; check "r1q M13: a lot that has not expired (XE-NEW, 10 days left) is transferred as before" '.success and .data.status == 1'
call POST inventory/documents "$(TRX $W1 $WQ "[{\"itemId\":$XEXP,\"quantity\":4,\"lotId\":$XEOLD}]")"; DX=$(val .data.id)
call POST "inventory/documents/$DX/confirm"; check "r1q M13: ... the expired lot may go INTO the quarantine warehouse (the way out of the expiry); an inspection waits for it there" '.success and .data.status == 1'
as "$QC_TOKEN" GET "inventory/quality/inspections?Status=0&PageSize=0"; QI_X=$(jq -r ".data.data[]|select(.itemId == $XEXP)|.id" "$B")
check "r1q M13: ... exactly one inspection waits for the 4 kg of XE-OLD" ".success and ([.data.data[]|select(.itemId == $XEXP)]|length) == 1 and ([.data.data[]|select(.itemId == $XEXP)|.quantity][0]) == 4"
IDS60=$(jq -nc '[range(1001;1061)]')
as "$QC_TOKEN" POST inventory/quality/inspections "{\"id\":$QI_X,\"acceptedQuantity\":4,\"rejectedQuantity\":0,\"targetWarehouseId\":$W1,\"reportNumber\":\"QC-IR-XE-1\",\"equipmentIds\":$IDS60}"; nomsg "r1q L21: a list of measuring instruments that does not fit the column is refused with a message" "تعداد ابزارهای اندازه‌گیری انتخاب‌شده بیش از حد است"
as "$QC_TOKEN" POST inventory/quality/inspections "{\"id\":$QI_X,\"acceptedQuantity\":4,\"rejectedQuantity\":0,\"targetWarehouseId\":$W1,\"reportNumber\":\"QC-IR-XE-1\"}"; nomsg "r1q M13: accepting the expired lot would release it to a usable warehouse: refused" "منقضی شده است"
as "$QC_TOKEN" GET "inventory/quality/inspections?Status=0&PageSize=0"; check "r1q M13: ... and the inspection is still waiting" ".success and ([.data.data[]|select(.id == $QI_X)]|length) == 1"

# M18: goods an open NCR is about are held; a piece (serial number) is held wherever it is, a lot only for the quantity of the report in its warehouse
ncr "{\"source\":2,\"severity\":1,\"itemId\":$XSER,\"quantity\":1,\"serialNumbers\":[\"XS-1\"],\"warehouseId\":$W1,\"disposition\":4,\"description\":\"Shaft XS-1 cracked in the store\",\"causeCategory\":4,\"rootCause\":\"Dropped during handling\",\"correctiveAction\":\"Racks with padded rests\"}"
check "r1q M18: an NCR for piece XS-1 (decision: scrap)" '.success and .data.status == 0 and .data.disposition == 4'
NCRXA=$(val .data.id); NCRXAN=$(val .data.number)
call POST inventory/documents "$(TRX $W1 $W2 "[{\"itemId\":$XSER,\"quantity\":1,\"serialNumbers\":[\"XS-1\"]}]")"
check "r1q M18: the piece is not moved to a usable warehouse while the report is open: refused already at the draft, the piece and the report are named" ".success == false and (.message|contains(\"XS-1\")) and (.message|contains(\"$NCRXAN\")) and (.message|contains(\"نگهداری می‌شود\"))"
call POST inventory/documents "$(TRX $W1 $W2 "[{\"itemId\":$XSER,\"quantity\":1,\"serialNumbers\":[\"XS-3\"]}]")"; DX3=$(val .data.id)
check "r1q M18: a clean draft for another piece (XS-3) is saved" '.success and .data.status == 0'
ncr "{\"source\":2,\"severity\":1,\"itemId\":$XSER,\"quantity\":1,\"serialNumbers\":[\"XS-3\"],\"warehouseId\":$W1,\"disposition\":1,\"concessionNumber\":\"CN-XS-3\",\"description\":\"Doubt about the bore of XS-3\",\"causeCategory\":4,\"rootCause\":\"Gauge reading to be repeated\"}"
NCRXB=$(val .data.id); NCRXBN=$(val .data.number)
call POST "inventory/documents/$DX3/confirm"; check "r1q M18: a report raised after the draft holds the piece: the confirmation checks again and refuses (the report is named)" ".success == false and (.message|contains(\"XS-3\")) and (.message|contains(\"$NCRXBN\"))"
as "$QC2_TOKEN" POST inventory/quality/ncr/close "{\"id\":$NCRXB,\"cancel\":true,\"reason\":\"$LONG1001\"}"; nomsg "r1q L21: a cancel reason longer than 1000 characters is refused with a message" "علت ابطال نباید بیش از ۱۰۰۰ نویسه باشد"
as "$QC2_TOKEN" POST inventory/quality/ncr/close "{\"id\":$NCRXB,\"cancel\":true,\"reason\":\"The bore was measured again: within tolerance\"}"; check "r1q M18: the report is cancelled by another QC user" '.success and .data.status == 4'
call POST "inventory/documents/$DX3/confirm"; check "r1q M18: with the report gone the hold ends: the same draft is confirmed" '.success and .data.status == 1'
call POST inventory/quality/ncr/close "{\"id\":$NCRXA,\"effectivenessCheck\":\"x\"}"; [ "$CODE" = "403" ] && ok "r1q L24: a PMO user cannot close or cancel NCRs (QC and QA only) (403)" || bad "r1q L24: a PMO user cannot close or cancel NCRs (QC and QA only) (403) got $CODE"
approve3 "$NCRXA"; check "r1q M18: NCR XS-1 is approved by the three signatures (scrap decision, not executed yet)" '.success and .data.status == 1'
call POST inventory/documents "$(TRX $W1 $W2 "[{\"itemId\":$XSER,\"quantity\":1,\"serialNumbers\":[\"XS-1\"]}]")"; nomsg "r1q M18: an approved decision that is not executed still holds the piece" "نگهداری می‌شود"
as "$QC_TOKEN" POST inventory/quality/ncr/execute "{\"id\":$NCRXA,\"targetWarehouseId\":$WS}"; check "r1q M18: the decision is executed (XS-1 moves to the scrap warehouse by the report's own transfer)" '.success and .data.status == 2 and (.data.resultDocumentNumber|startswith("TR-"))'
call GET "inventory/stock/serials?Contains=XS-1&ItemId=$XSER"; check "r1q M18: ... the piece is in the scrap warehouse" ".success and .data.data[0].warehouseId == $WS"
# a lot is held for the quantity of the report only: 3 of the 6 kg of XE-NEW in the main warehouse
ncr "{\"source\":2,\"severity\":1,\"itemId\":$XEXP,\"lotId\":$XENEW,\"quantity\":3,\"warehouseId\":$W1,\"disposition\":1,\"concessionNumber\":\"CN-XE-NEW\",\"description\":\"Surface rust on part of lot XE-NEW\",\"causeCategory\":4,\"rootCause\":\"Wet rack\"}"
NCRXL=$(val .data.id); NCRXLN=$(val .data.number)
call POST inventory/documents "$(TRX $W1 $W2 "[{\"itemId\":$XEXP,\"quantity\":4,\"lotId\":$XENEW}]")"
check "r1q M18: 4 of the 6 kg would leave less than the 3 kg the report holds: refused (the held quantity and the report are named)" ".success == false and (.message|contains(\"$NCRXLN\")) and (.message|contains(\"XE-NEW\")) and (.message|contains(\"3 از موجودی این انبار\"))"
call POST inventory/documents "$(TRX $W1 $W2 "[{\"itemId\":$XEXP,\"quantity\":3,\"lotId\":$XENEW}]")"; DXL=$(val .data.id)
call POST "inventory/documents/$DXL/confirm"; check "r1q M18: 3 kg may go: the 3 kg of the report stay in the main warehouse" '.success and .data.status == 1'
as "$QC2_TOKEN" POST inventory/quality/ncr/close "{\"id\":$NCRXL,\"cancel\":true,\"reason\":\"The rust was surface dust: cleaned\"}"; check "r1q M18: the lot report is cancelled by another QC user" '.success and .data.status == 4'

# M10: pieces of a serial item are written off by a decrease adjustment only against a scrap NCR (approved or executed) that lists them
ncr "{\"source\":2,\"severity\":1,\"itemId\":$XSER,\"quantity\":1,\"serialNumbers\":[\"XS-2\"],\"warehouseId\":$W1,\"disposition\":4,\"description\":\"Shaft XS-2 lost its centre holes\",\"causeCategory\":4,\"rootCause\":\"Machined twice\",\"correctiveAction\":\"Job card checks the operation count\"}"
NCRXW=$(val .data.id)
WOFF() { echo "{\"type\":8,\"documentDate\":\"${D0}T00:00:00\",\"warehouseId\":$W1,\"lines\":[{\"itemId\":$XSER,\"quantity\":1,\"serialNumbers\":[\"$1\"]}]$2}"; } # WOFF SERIAL [,extra fields]
call POST inventory/documents "$(WOFF XS-2 '')"; nomsg "r1q M10: a serial piece is not written off by a decrease adjustment without a report" "فقط با گزارش عدم انطباق دارای تصمیم ضایعات"
call POST inventory/documents "$(WOFF XS-2 ",\"writeOffNcrId\":$NCRXW")"; nomsg "r1q M10: a report that is still open (no approved scrap decision) does not allow it" "تصمیم ضایعات تاییدشده یا اجراشده ندارد"
approve3 "$NCRXW"
call POST inventory/documents "$(WOFF XS-1 ",\"writeOffNcrId\":$NCRXW")"; nomsg "r1q M10: the report must list the piece (XS-1 is not in the report of XS-2)" "نیامده است"
call POST inventory/documents "$(WOFF XS-2 ",\"writeOffNcrId\":$NCRXW")"; WOD=$(val .data.id)
check "r1q M10: with the approved scrap report that lists XS-2 the write-off is saved as a draft that names the report" ".success and .data.status == 0 and .data.writeOffNcrId == $NCRXW"
as "$SUP_TOKEN" POST "inventory/documents/$WOD/approve" '{"kind":1}'; as "$PLAN_TOKEN" POST "inventory/documents/$WOD/approve" '{"kind":2}'
call POST "inventory/documents/$WOD/confirm"; check "r1q M10: ... and, with the two approvals of an adjustment, confirmed (the approved report holds goods, but an adjustment is a correction, not a use)" '.success and .data.status == 1 and (.data.number|startswith("AD-"))'
call GET "inventory/stock?ItemId=$XSER"; check "r1q M10: the main warehouse holds none of the three pieces any more (XS-1 in scrap, XS-2 written off, XS-3 in the workshop)" "(([.data.data[]|select(.warehouseId==$W1)|.quantity]|add) // 0) == 0 and ([.data.data[]|select(.warehouseId==$WS)|.quantity]|add) == 1 and ([.data.data[]|select(.warehouseId==$W2)|.quantity]|add) == 1"

# M10: a stock count in a quarantine, scrap or contractor warehouse needs the quality approval (QC or QA) besides the approvals of the warehouse and planning
call POST inventory/counts "{\"kind\":1,\"countDate\":\"${D0}T00:00:00\",\"warehouseId\":$WQ,\"groupCode\":\"01001026120101\"}"
check "r1q M10: a count in the quarantine warehouse says that it needs the quality approval too" '.success and .data.qualityApprovalRequired == true and .data.qualityApprovedAt == null and .data.linesCount == 1'
CNTQ=$(val .data.id); LINESQ=$(jq -c '[.data.lines[]|{lineId:.id,countedQuantity:(.systemQuantity-1)}]' "$B")
call POST inventory/counts/lines "{\"id\":$CNTQ,\"lines\":$LINESQ}"; check "r1q M10: 1 kg less than the books in quarantine" '.success and .data.differencesCount == 1'
call POST inventory/counts/action "{\"id\":$CNTQ,\"action\":\"submit\"}"; check "r1q M10: the count is submitted" '.success and .data.status == 1'
as "$SUP_TOKEN" POST inventory/counts/action "{\"id\":$CNTQ,\"action\":\"approve-warehouse\"}"; as "$PLAN_TOKEN" POST inventory/counts/action "{\"id\":$CNTQ,\"action\":\"approve-planning\"}"
check "r1q M10: with the warehouse and planning approvals the count is still not approved: the quality approval is missing" '.success and .data.status == 1 and .data.warehouseApprovedAt != null and .data.planningApprovedAt != null and .data.qualityApprovedAt == null'
call POST inventory/counts/action "{\"id\":$CNTQ,\"action\":\"post\"}"; no "r1q M10: ... and it cannot be posted"
as "$WH_TOKEN" POST inventory/counts/action "{\"id\":$CNTQ,\"action\":\"approve-quality\"}"; nomsg "r1q M10: the storekeeper cannot give the quality approval" "کنترل کیفیت یا مدیر تضمین کیفیت"
as "$QC_TOKEN" POST inventory/counts/action "{\"id\":$CNTQ,\"action\":\"approve-quality\"}"; check "r1q M10: a QC user who did not start, count or approve it gives the quality approval: the count is approved" '.success and .data.status == 2 and .data.qualityApprovedAt != null and .data.qualityApprovedByName != null'
as "$QC2_TOKEN" POST inventory/counts/action "{\"id\":$CNTQ,\"action\":\"approve-quality\"}"; nomsg "r1q M10: the quality approval is given once" "قبلاً ثبت شده است"
call POST inventory/counts/action "{\"id\":$CNTQ,\"action\":\"post\"}"; check "r1q M10: the count is posted: one decrease adjustment of 1 kg out of quarantine" '.success and .data.status == 3 and (.data.decreaseDocumentNumber|startswith("AD-"))'
call GET "inventory/stock?ItemId=$XEXP"; check "r1q M10: quarantine holds 3 kg of the test material now" "([.data.data[]|select(.warehouseId==$WQ)|.quantity]|add) == 3"
call POST inventory/counts "{\"kind\":1,\"countDate\":\"${D0}T00:00:00\",\"warehouseId\":$W1,\"groupCode\":\"01001026120101\"}"
check "r1q M10: a count in a usable warehouse does not need it" '.success and .data.qualityApprovalRequired == false and .data.linesCount == 2'
CNTU=$(val .data.id); LINESU=$(jq -c '[.data.lines[]|{lineId:.id,countedQuantity:.systemQuantity}]' "$B")
call POST inventory/counts/lines "{\"id\":$CNTU,\"lines\":$LINESU}"; call POST inventory/counts/action "{\"id\":$CNTU,\"action\":\"submit\"}"
as "$QC_TOKEN" POST inventory/counts/action "{\"id\":$CNTU,\"action\":\"approve-quality\"}"; nomsg "r1q M10: ... and a quality approval on it is refused" "تایید کنترل کیفیت لازم ندارد"
call POST inventory/counts/action "{\"id\":$CNTU,\"action\":\"cancel\"}"; check "r1q M10: the usable-warehouse count is cancelled again (the warehouse is not left frozen)" '.success and .data.status == 4'

# L21: more texts that have a column length are refused with a message
LINES400=$(jq -nc '[range(1;401)|"LONG-SERIAL-\(.)"]')
as "$QC_TOKEN" POST quality/release-notes "{\"id\":$RN2,\"workOrderId\":$WO2,\"itemsText\":\"Feed pump unit 2\",\"lines\":[{\"itemId\":$SHAFT,\"quantity\":400,\"serialNumbers\":$LINES400}]}"; nomsg "r1q L21: a serial list that does not fit the release line column (4000 characters) is refused with a message" "بیش از ۴۰۰۰ نویسه"
as "$QC_TOKEN" POST quality/release-notes/action "{\"id\":$RN2,\"action\":\"cancel\",\"reason\":\"$LONG1001\"}"; nomsg "r1q L21: a release note cancel reason longer than 1000 characters is refused with a message" "دلیل لغو نباید بیش از ۱۰۰۰ نویسه باشد"
TOKEN=$ADMIN_TOKEN

# ================================================================ PROJECT CONTROL (PMO) MODULE (release 1)
# Own contracts: PCT (exact CPM / EVM / change control scenario), PCT2 (WBS generation + legacy predecessor cycles),
# PCP (late penalty). Schedule dates are fixed (calendar Mon-Fri, start Monday 2026-11-02) so every figure is exact.
TOKEN=$ADMIN_TOKEN
PC=projectcontrol
call POST Accounts/register-user '{"userName":"pm.ci","name":"pm.ci","lastName":"آزمون","email":"pm.ci@example.com","roleIds":[15],"password":"Ci#Pm-User-2026","phoneNumber":"09120000022","birthDate":"1990-01-01T00:00:00+03:30","nationalCode":"0012345622"}'
call POST Accounts/register-user '{"userName":"dcc.ci","name":"dcc.ci","lastName":"آزمون","email":"dcc.ci@example.com","roleIds":[16],"password":"Ci#Dcc-User-2026","phoneNumber":"09120000023","birthDate":"1990-01-01T00:00:00+03:30","nationalCode":"0012345623"}'
PM_TOKEN=$(login pm.ci 'Ci#Pm-User-2026'); DCC_TOKEN=$(login dcc.ci 'Ci#Dcc-User-2026')
[ -n "$PM_TOKEN" ] && [ -n "$DCC_TOKEN" ] && ok "pc: login project manager (role 15) and DCC (role 16)" || bad "pc: login project manager (role 15) and DCC (role 16)"
PMID=$(uid "$PM_TOKEN"); PLANID=$(uid "$PLAN_TOKEN")
[ -n "$PMID" ] && [ -n "$PLANID" ] && ok "pc: user ids resolved" || bad "pc: user ids resolved"
# R1q D27: the project manager and the document controller work with the controlled documents, the NCRs and the inspections every day, so they read the quality records (they write nothing there)
as "$PM_TOKEN" GET "quality/records?PageSize=0"; check "r1q D27: the project manager (role 15) reads the inspection records (the record $R1NUM is among them)" ".success and ([.data.data[]|select(.id == $R1 and .number == \"$R1NUM\")]|length) == 1"
as "$DCC_TOKEN" GET "quality/documents?PageSize=0"; check "r1q D27: the document controller (role 16) reads the controlled documents ($DOC1CODE is among them)" ".success and ([.data.data[]|select(.id == $DOC1 and .code == \"$DOC1CODE\")]|length) == 1"
as "$DCC_TOKEN" POST quality/settings '{"key":"CalibrationWarnDays","value":31}'; nomsg "r1q D27: ... but reading is all: the document controller cannot change the quality settings" "شما مجوز این کار را ندارید"
as "$SEC_TOKEN" GET quality/documents; [ "$CODE" = "403" ] && ok "r1q D27: a role outside the list (security) is still refused (403)" || bad "r1q D27: a role outside the list (security) is still refused (403) got $CODE"

as "$PLAN_TOKEN" POST $PC/calendars '{"name":"Mon-Fri","workingWeekdays":62,"hoursPerDay":8,"useCompanyHolidays":false}'; check "pc: working calendar saved (Mon-Fri)" '.success and .data.id > 0 and .data.workingWeekdays == 62'
PCCAL=$(val .data.id)
as "$PM_TOKEN" POST $PC/calendars '{"name":"x","workingWeekdays":62,"hoursPerDay":8}'; no "pc: project manager cannot write calendars"
as "$PLAN_TOKEN" POST $PC/calendars '{"name":"bad","workingWeekdays":0,"hoursPerDay":8}'; no "pc: calendar without any working day rejected"

# --- contract, pump equipment, work order, terms
call POST Contracts '{"code":"PC-CT-01","title":"قرارداد آزمون کنترل پروژه","status":1,"employer":"کارفرمای آزمون"}'; check "pc: contract created" '.success and .data.id > 0'
PCT=$(val .data.id)
call POST Equipments '{"code":"PC-EQ-PUMP","title":"Process Pump API 610"}'; PEQ=$(val .data.id)
call POST ContractEquipments "{\"contractId\":$PCT,\"equipmentId\":$PEQ,\"count\":1}"; check "pc: contract equipment" '.success'
call POST WorkOrders "{\"contractId\":$PCT,\"equipmentId\":$PEQ,\"code\":\"PC-WO-1\",\"title\":\"Pump 1\",\"description\":\"x\",\"count\":1}"; check "pc: work order created" '.success and .data.id > 0'
PCW1=$(val .data.id)
PCTERMS="{\"contractId\":$PCT,\"currencyCode\":\"IRR\",\"valueExVat\":1000000000,\"vatPercent\":10,\"advancePercent\":10,\"retentionPercent\":5,\"latePenaltyPercentPerWeek\":1,\"penaltyCapPercent\":10,\"graceDays\":0,\"calendarId\":$PCCAL,\"dataDateWeekday\":3,\"scheduleStartDate\":\"2026-11-02T00:00:00\",\"accrualMode\":1,\"clientReviewDays\":14,\"managementReserve\":0,\"autoSnapshot\":true,\"clientReportShowsIndices\":false}"
as "$WH_TOKEN" POST $PC/terms "$PCTERMS"; no "pc: warehouse cannot write contract terms"
as "$PLAN_TOKEN" POST $PC/terms "$PCTERMS"; check "pc: contract terms saved (value, penalty, calendar, start)" '.success and .data.valueExVat == 1000000000 and .data.dataDateWeekday == 3 and .data.clientReportShowsIndices == false'
as "$PLAN_TOKEN" POST $PC/terms "$(echo "$PCTERMS" | jq -c '.vatPercent = 101')"; no "pc: percentage above 100 rejected"
# R1a: a contract that project control works on is not deleted, even by the PMO (the answer names what is in the way); only the PMO deletes a contract at all
call DELETE "Contracts/$PCT"; check "r1a legacy: the PMO cannot delete a contract that has project control records; the answer names them" '.success == false and (.message|contains("حذف قرارداد ممکن نیست")) and (.message|contains("شرایط قرارداد در کنترل پروژه"))'
as "$PLAN_TOKEN" DELETE "Contracts/$PCT"; r403 "r1a legacy: planning cannot delete a contract (403)"
call GET "Contracts/contracts?Id=$PCT"; check "r1a legacy: the contract of the project is still there" ".success and .data.id == $PCT"

# --- initiation (WI-PL-009 sections 3-8) and the 9-character project code
as "$PLAN_TOKEN" POST $PC/initiation/start/$PCT; check "pc: initiation started: 10 steps" '.success and (.data.steps|length) == 10'
as "$PLAN_TOKEN" POST $PC/terms/generate-code "{\"contractId\":$PCT,\"category\":1}"; check "pc: project code generated (9 characters, MA)" '.success and (.data.projectCode|length) == 9 and (.data.projectCode|contains("MA"))'
as "$PLAN_TOKEN" POST $PC/terms/generate-code "{\"contractId\":$PCT,\"category\":1}"; no "pc: project code is issued once"
as "$PLAN_TOKEN" POST $PC/initiation/action "{\"contractId\":$PCT,\"step\":3,\"note\":\"units notified\"}"; check "pc: units notified step done" '.success'
as "$PLAN_TOKEN" POST $PC/initiation/action "{\"contractId\":$PCT,\"step\":4,\"projectManagerUserId\":$PMID}"; no "pc: planning cannot select the project manager"
as "$CEO_TOKEN" POST $PC/initiation/action "{\"contractId\":$PCT,\"step\":4,\"projectManagerUserId\":$PMID}"; check "pc: CEO selects the project manager" '.success'
call GET "$PC/terms/$PCT"; check "pc: terms show the manager and the code" ".success and .data.projectManagerUserId == $PMID and .data.projectCode != null"
as "$PLAN_TOKEN" GET "$PC/claims?ContractId=$PCT"; check "pc: claims file opened with the initiation (read)" '.success'

# --- claims (R1a): a claim is notified only after two different people approved it: the PMO deputy and the design and manufacturing side (engineering or the project manager)
user2 dual.ci 1,4 'Ci#Dual-User-2026' 09120000092 0012345692
check "r1a2 h1: the user is given the engineering role at once and asks for the PMO role (PMO is a sensitive role since R1a2; two active PMO users exist, so a second PMO user must approve it)" '.success and .data.id > 0 and ([.data.roles[]?.name]|index("ENGINEERING")) != null and ([.data.roles[]?.name]|index("PMO")) == null and (.message|contains("PMO"))'
approve_grants dual.ci
DUAL_TOKEN=$(login dual.ci 'Ci#Dual-User-2026'); [ -n "$DUAL_TOKEN" ] && ok "r1a pc: login of a user who holds two roles, PMO and engineering" || bad "r1a pc: login of a user who holds two roles, PMO and engineering"
as "$PLAN_TOKEN" POST $PC/claims "{\"contractId\":$PCT,\"direction\":1,\"issue\":\"تاخیر کارفرما در تایید نقشه‌ها\",\"basis\":\"بند ۱۲ قرارداد\"}"; check "r1a pc: claim saved" '.success and .data.id > 0 and .data.status == 0'
CL1=$(val .data.id)
as "$PLAN_TOKEN" POST $PC/claims/action "{\"id\":$CL1,\"action\":\"quantify\",\"days\":10,\"amount\":50000000}"; check "r1a pc: claim quantified: 10 days and 50,000,000 rial" '.success and .data.status == 1 and .data.daysQuantified == 10 and .data.amountQuantified == 50000000'
as "$WH_TOKEN" POST $PC/claims/action "{\"id\":$CL1,\"action\":\"approve-pmo\"}"; nomsg "r1a pc: a storekeeper cannot approve a claim for the PMO" "مجوز"
as "$PLAN_TOKEN" POST $PC/claims/action "{\"id\":$CL1,\"action\":\"approve-pmo\"}"; nomsg "r1a pc: planning cannot approve a claim for the PMO" "مجوز"
call POST $PC/claims/action "{\"id\":$CL1,\"action\":\"approve-design\"}"; nomsg "r1a pc: the PMO deputy does not approve for the design and manufacturing side (engineering or the project manager does)" "مدیر مهندسی یا مدیر پروژه"
as "$PLAN_TOKEN" POST $PC/claims/action "{\"id\":$CL1,\"action\":\"notify\"}"; nomsg "r1a pc: a claim cannot be notified before both approvals" "ابلاغ ادعا نیازمند تایید"
call POST $PC/claims/action "{\"id\":$CL1,\"action\":\"approve-pmo\",\"note\":\"تایید معاون PMO\"}"; check "r1a pc: the PMO approves the claim" '.success and .data.pmoApproved == true and .data.designManufacturingApproved == false'
call POST $PC/claims/action "{\"id\":$CL1,\"action\":\"approve-pmo\"}"; nomsg "r1a pc: the PMO approval is given once" "تایید PMO برای این ادعا"
as "$ENG_TOKEN" POST $PC/claims/action "{\"id\":$CL1,\"action\":\"approve-design\",\"note\":\"تایید مدیر مهندسی\"}"; check "r1a pc: engineering approves the claim for the design and manufacturing side" '.success and .data.pmoApproved == true and .data.designManufacturingApproved == true'
as "$PLAN_TOKEN" POST $PC/claims/action "{\"id\":$CL1,\"action\":\"notify\"}"; check "r1a pc: after the two approvals the claim is notified" '.success and .data.status == 2'
as "$PLAN_TOKEN" POST $PC/claims "{\"contractId\":$PCT,\"direction\":1,\"issue\":\"ادعای دوم برای آزمون تفکیک وظایف\"}"; check "r1a pc: second claim saved" '.success and .data.id > 0'
CL2=$(val .data.id)
as "$PLAN_TOKEN" POST $PC/claims/action "{\"id\":$CL2,\"action\":\"quantify\",\"days\":3}"; check "r1a pc: second claim quantified (3 days)" '.success and .data.status == 1'
as "$DUAL_TOKEN" POST $PC/claims/action "{\"id\":$CL2,\"action\":\"approve-pmo\"}"; check "r1a pc: the user with both roles approves as the PMO deputy" '.success and .data.pmoApproved == true'
as "$DUAL_TOKEN" POST $PC/claims/action "{\"id\":$CL2,\"action\":\"approve-design\"}"; nomsg "r1a pc: the same person cannot give the second approval (the two approvals come from two different people)" "دو نفر مختلف"
as "$PLAN_TOKEN" POST $PC/claims/action "{\"id\":$CL2,\"action\":\"notify\"}"; nomsg "r1a pc: so the claim cannot be notified yet" "ابلاغ ادعا نیازمند تایید"
as "$ENG_TOKEN" POST $PC/claims/action "{\"id\":$CL2,\"action\":\"approve-design\"}"; check "r1a pc: another person (engineering) gives the second approval" '.success and .data.designManufacturingApproved == true'
as "$PLAN_TOKEN" POST $PC/claims/action "{\"id\":$CL2,\"action\":\"notify\"}"; check "r1a pc: the second claim is notified after two different approvers" '.success and .data.status == 2'

# R1a2 (H4): a claim is approved only on the quantified amount, never by the person who registered or quantified it, a new quantification or an edit of the text starts the approvals again,
# the people who did each step are remembered, and a claim that was notified is not edited any more
DUALID=$(uid "$DUAL_TOKEN"); PLANID=$(uid "$PLAN_TOKEN"); ENGID=$(uid "$ENG_TOKEN")
[ -n "$DUALID" ] && [ -n "$PLANID" ] && [ -n "$ENGID" ] && ok "r1a2 h4: the ids of the dual-role, planning and engineering users are resolved" || bad "r1a2 h4: the ids of the dual-role, planning and engineering users are resolved"
call POST $PC/claims "{\"contractId\":$PCT,\"direction\":1,\"issue\":\"ادعای سوم برای آزمون تایید برآورد\",\"basis\":\"بند ۱۴ قرارداد\"}"; check "r1a2 h4: a claim is registered by the PMO user" '.success and .data.id > 0 and .data.status == 0'
CL3=$(val .data.id)
call POST $PC/claims/action "{\"id\":$CL3,\"action\":\"approve-pmo\"}"; nomsg "r1a2 h4: an approval before the quantification is refused (PMO side)" "تایید فقط برای ادعای برآوردشده ممکن است"
as "$ENG_TOKEN" POST $PC/claims/action "{\"id\":$CL3,\"action\":\"approve-design\"}"; nomsg "r1a2 h4: an approval before the quantification is refused (design and manufacturing side)" "تایید فقط برای ادعای برآوردشده ممکن است"
call POST $PC/claims/action "{\"id\":$CL3,\"action\":\"quantify\",\"days\":5,\"amount\":1000000}"; check "r1a2 h4: the PMO user quantifies the claim he registered; the quantifier is remembered" ".success and .data.status == 1 and .data.quantifiedByUserId == $IAMADM"
call POST $PC/claims/action "{\"id\":$CL3,\"action\":\"approve-pmo\"}"; nomsg "r1a2 h4: the person who registered and quantified a claim cannot approve it" "تفکیک وظایف"
as "$PLAN_TOKEN" POST $PC/claims/action "{\"id\":$CL3,\"action\":\"quantify\",\"days\":6,\"amount\":2000000}"; check "r1a2 h4: planning quantifies it again (6 days, 2,000,000 rial): the quantifier is now planning" ".success and .data.status == 1 and .data.daysQuantified == 6 and .data.quantifiedByUserId == $PLANID"
call POST $PC/claims/action "{\"id\":$CL3,\"action\":\"approve-pmo\"}"; nomsg "r1a2 h4: the registrant still cannot approve it, whoever quantified it" "تفکیک وظایف"
as "$DUAL_TOKEN" POST $PC/claims/action "{\"id\":$CL3,\"action\":\"approve-pmo\"}"; check "r1a2 h4: a PMO user who neither registered nor quantified it approves; the approver and the time are kept" ".success and .data.pmoApproved == true and .data.pmoApprovedByUserId == $DUALID and (.data.pmoApprovedAt|length) > 0"
as "$PLAN_TOKEN" POST $PC/claims/action "{\"id\":$CL3,\"action\":\"quantify\",\"days\":7,\"amount\":2500000}"; check "r1a2 h4: a new quantification takes the approval back: what was approved is not what the claim says now" '.success and .data.pmoApproved == false and .data.pmoApprovedByUserId == null and .data.daysQuantified == 7'
as "$DUAL_TOKEN" POST $PC/claims/action "{\"id\":$CL3,\"action\":\"approve-pmo\"}"; check "r1a2 h4: the PMO side approves the new amount" ".success and .data.pmoApproved == true and .data.pmoApprovedByUserId == $DUALID"
as "$ENG_TOKEN" POST $PC/claims/action "{\"id\":$CL3,\"action\":\"approve-design\"}"; check "r1a2 h4: engineering approves it for the design and manufacturing side; the approver is kept" ".success and .data.designManufacturingApproved == true and .data.designApprovedByUserId == $ENGID and .data.pmoApproved == true"
as "$PLAN_TOKEN" POST $PC/claims "{\"id\":$CL3,\"contractId\":$PCT,\"direction\":1,\"issue\":\"ادعای سوم برای آزمون تایید برآورد (متن اصلاح‌شده)\",\"basis\":\"بند ۱۴ قرارداد\"}"
check "r1a2 h4: an edit of the text of the claim takes both approvals back" '.success and .data.status == 1 and .data.pmoApproved == false and .data.designManufacturingApproved == false and .data.pmoApprovedByUserId == null and .data.designApprovedByUserId == null'
as "$PLAN_TOKEN" POST $PC/claims/action "{\"id\":$CL3,\"action\":\"notify\"}"; nomsg "r1a2 h4: so the claim cannot be notified on the old approvals" "ابلاغ ادعا نیازمند تایید"
as "$DUAL_TOKEN" POST $PC/claims/action "{\"id\":$CL3,\"action\":\"approve-pmo\"}"; check "r1a2 h4: the PMO side approves the corrected text" '.success and .data.pmoApproved == true'
as "$ENG_TOKEN" POST $PC/claims/action "{\"id\":$CL3,\"action\":\"approve-design\"}"; check "r1a2 h4: engineering approves the corrected text" '.success and .data.designManufacturingApproved == true'
as "$PLAN_TOKEN" POST $PC/claims/action "{\"id\":$CL3,\"action\":\"notify\"}"; check "r1a2 h4: after two fresh approvals the claim is notified" '.success and .data.status == 2'
as "$PLAN_TOKEN" POST $PC/claims "{\"id\":$CL3,\"contractId\":$PCT,\"direction\":1,\"issue\":\"متن دیگر پس از ابلاغ\",\"basis\":\"بند ۱۴ قرارداد\"}"; nomsg "r1a2 h4: a claim that was notified is not edited any more (what the client was told does not change)" "ادعای ابلاغ‌شده ویرایش نمی‌شود"

# R1a2 review (L-7): the person whose save changed the text of a claim last is barred from both approvals too, like the one who registered it and the one who quantified it. The user with both roles
# (PMO and engineering) is neither of those two for the fourth claim, so before the review he could approve it on either side; now he edited the text, and he cannot.
as "$PLAN_TOKEN" POST $PC/claims "{\"contractId\":$PCT,\"direction\":1,\"issue\":\"ادعای چهارم برای آزمون آخرین ویرایش‌کننده\",\"basis\":\"بند ۱۶ قرارداد\"}"
check "r1a2 review l-7: a claim is registered by planning; the registrant is the last editor of the text so far" ".success and .data.id > 0 and .data.status == 0 and .data.lastEditedByUserId == $PLANID"
CL4=$(val .data.id)
as "$PLAN_TOKEN" POST $PC/claims/action "{\"id\":$CL4,\"action\":\"quantify\",\"days\":2,\"amount\":500000}"; check "r1a2 review l-7: planning quantifies it" ".success and .data.status == 1 and .data.quantifiedByUserId == $PLANID"
as "$DUAL_TOKEN" POST $PC/claims "{\"id\":$CL4,\"contractId\":$PCT,\"direction\":1,\"issue\":\"ادعای چهارم برای آزمون آخرین ویرایش‌کننده (متن اصلاح‌شده)\",\"basis\":\"بند ۱۶ قرارداد\"}"
check "r1a2 review l-7: the user with both roles corrects the text: he is the last editor now, the quantification and the quantifier stay" ".success and .data.status == 1 and .data.lastEditedByUserId == $DUALID and .data.quantifiedByUserId == $PLANID and .data.daysQuantified == 2"
as "$DUAL_TOKEN" POST $PC/claims/action "{\"id\":$CL4,\"action\":\"approve-pmo\"}"; nomsg "r1a2 review l-7: the last editor of the text cannot approve it as the PMO deputy" "آخرین ویرایش"
as "$DUAL_TOKEN" POST $PC/claims/action "{\"id\":$CL4,\"action\":\"approve-design\"}"; nomsg "r1a2 review l-7: nor for the design and manufacturing side" "آخرین ویرایش"
call POST $PC/claims/action "{\"id\":$CL4,\"action\":\"approve-pmo\"}"; check "r1a2 review l-7 (control): a PMO user who neither registered, quantified nor edited it approves" ".success and .data.pmoApproved == true and .data.pmoApprovedByUserId == $IAMADM"
as "$ENG_TOKEN" POST $PC/claims/action "{\"id\":$CL4,\"action\":\"approve-design\"}"; check "r1a2 review l-7 (control): and so does engineering" ".success and .data.designManufacturingApproved == true and .data.designApprovedByUserId == $ENGID"

# --- equipment code and MDR/MDL from the template
as "$PLAN_TOKEN" POST $PC/work-order-info "{\"workOrderId\":$PCW1,\"contractId\":$PCT,\"typeCode\":\"PU\",\"sizeCode\":\"100\",\"optionCode\":\"25\"}"; check "pc: equipment project code PU1002501" '.success and .data.equipmentProjectCode == "PU1002501"'
as "$QC_TOKEN" POST $PC/mdr/draft "{\"contractId\":$PCT,\"workOrderId\":$PCW1}"; no "pc: QC cannot draft the MDR"
as "$DCC_TOKEN" POST $PC/mdr/draft "{\"contractId\":$PCT,\"workOrderId\":$PCW1}"; check "pc: MDR drafted from the pump template" '.success and .data.linesDrafted == 12'
as "$DCC_TOKEN" POST $PC/mdr/draft "{\"contractId\":$PCT,\"workOrderId\":$PCW1}"; no "pc: the MDR is drafted once per work order"
# R1a: a work order that has engineering documents (the MDR above) is not deleted, even by the PMO; the answer names what is in the way. Only the PMO deletes a work order at all.
call DELETE WorkOrders/delete-workOrder-collection "[$PCW1]"; check "r1a legacy: the PMO cannot delete a work order that has engineering documents; the answer for that work order names them" '.success and (.data|length) == 1 and .data[0].success == false and (.data[0].message|contains("حذف دستور ساخت ممکن نیست")) and (.data[0].message|contains("مدارک مهندسی"))'
as "$PLAN_TOKEN" DELETE WorkOrders/delete-workOrder-collection "[$PCW1]"; r403 "r1a legacy: planning cannot delete work orders (403)"
call GET "WorkOrders/get-workorder?Id=$PCW1&ContractId=$PCT"; check "r1a legacy: the work order is still there" ".success and .data.id == $PCW1"
as "$DCC_TOKEN" GET "$PC/mdr?WorkOrderId=$PCW1&PageSize=0"
check "pc: MDR has 12 lines, 11 on the client list (MDL subset), each with a standard source" '(.data.data|length) == 12 and ([.data.data[]|select(.clientSubmittal)]|length) == 11 and ([.data.data[]|select(.standardSource != null)]|length) == 12'
check "pc: template standard sources are marked to be verified" '[.data.data[]|select((.standardSource // "")|contains("to be verified"))]|length >= 1'
CL_IDS=$(jq -c '[.data.data[]|select(.clientSubmittal)|.id]' "$B"); INT_ID=$(jq -r '[.data.data[]|select(.clientSubmittal|not)|.id][0]' "$B")

# --- supply chain for two activities: one purchase order with two lines (60 and 40 plates)
as "$WH_TOKEN" POST procurement/requests "{\"source\":2,\"kind\":1,\"requestDate\":\"2026-10-22T00:00:00\",\"description\":\"ورق پروژه کنترل\",\"submit\":true,\"lines\":[{\"itemId\":$PLATE,\"quantity\":60,\"estimatedUnitPrice\":400000,\"technicalRequirements\":\"ASTM A516-70 با گواهی 3.1\"},{\"itemId\":$PLATE,\"quantity\":40,\"estimatedUnitPrice\":400000,\"technicalRequirements\":\"ASTM A516-70 با گواهی 3.1\"}]}"
check "pc: purchase request with two lines submitted (40M rial)" '.success and .data.status == 1 and (.data.lines|length) == 2 and .data.estimatedAmount == 40000000'
PCPR=$(val .data.id); PRL1=$(val '.data.lines[]|select(.quantity==60)|.id'); PRL2=$(val '.data.lines[]|select(.quantity==40)|.id')
as "$PLAN_TOKEN" POST procurement/requests/action "{\"id\":$PCPR,\"action\":\"approve-planning\"}"
as "$CEO_TOKEN" POST procurement/requests/action "{\"id\":$PCPR,\"action\":\"approve-management\"}"; check "pc: purchase request approved" '.success and .data.status == 2'
PQA="{\"providerId\":$PA,\"quoteNumber\":\"PC-Q-A\",\"vatPercent\":10,\"deliveryDays\":20,\"technicallyAccepted\":true,\"lines\":[{\"requestLineId\":$PRL1,\"quantity\":60,\"unitPrice\":390000},{\"requestLineId\":$PRL2,\"quantity\":40,\"unitPrice\":390000}]}"
PQB="{\"providerId\":$PB,\"quoteNumber\":\"PC-Q-B\",\"vatPercent\":10,\"technicallyAccepted\":true,\"lines\":[{\"requestLineId\":$PRL1,\"quantity\":60,\"unitPrice\":380000},{\"requestLineId\":$PRL2,\"quantity\":40,\"unitPrice\":380000}]}"
as "$COM_TOKEN" POST procurement/inquiries "{\"purchaseRequestId\":$PCPR,\"inquiryDate\":\"2026-10-22T00:00:00\",\"quotes\":[$PQA,$PQB]}"; check "pc: inquiry with two quotes" '.success and (.data.quotes|length) == 2'
PCINQ=$(val .data.id); PQAID=$(val ".data.quotes[]|select(.providerId == $PA)|.id")
as "$COM_TOKEN" POST procurement/inquiries/select "{\"inquiryId\":$PCINQ,\"quoteId\":$PQAID,\"reason\":\"گرید A و تحویل 20 روزه\"}"; check "pc: quote selected" '.success and .data.status == 2'
as "$COM_TOKEN" POST "procurement/orders/from-inquiry/$PCINQ"; check "pc: purchase order draft with two lines" '.success and (.data.lines|length) == 2'
PCPO=$(val .data.id); POL1=$(val '.data.lines[]|select(.quantity==60)|.id'); POL2=$(val '.data.lines[]|select(.quantity==40)|.id')
as "$ADMIN_TOKEN" POST procurement/orders/action "{\"id\":$PCPO,\"action\":\"approve\"}"
as "$COM_TOKEN" POST procurement/orders/action "{\"id\":$PCPO,\"action\":\"release\"}"; check "pc: purchase order released" '.success and .data.status == 2'

# --- four activities (weights 0: they count equally in the physical percent), budgets 1,000,000,000 rial
actp() { as "$PLAN_TOKEN" POST $PC/activities "$1"; }
actp "{\"contractId\":$PCT,\"code\":\"PC-A\",\"title\":\"صدور مدارک مهندسی\",\"sourceType\":4,\"sourceId\":0,\"workOrderId\":$PCW1,\"durationDays\":3,\"responsibleUnit\":\"ENGINEERING\",\"progressMethod\":1,\"weight\":0,\"budgetAtCompletion\":300000000,\"phase\":1}"
check "pc: activity A (engineering issue, 3 days)" '.success and .data.id > 0 and .data.responsibleUnit == "ENGINEERING"'; PCA=$(val .data.id)
actp "{\"contractId\":$PCT,\"code\":\"PC-B\",\"title\":\"تامین ورق الف\",\"sourceType\":6,\"durationDays\":2,\"responsibleUnit\":\"PLANNING\",\"progressMethod\":2,\"weight\":0,\"budgetAtCompletion\":200000000,\"phase\":2,\"purchaseOrderLineId\":$POL1}"
check "pc: activity B (supply receipt, 60 plates)" '.success and .data.id > 0'; PCB=$(val .data.id)
actp "{\"contractId\":$PCT,\"code\":\"PC-C\",\"title\":\"ساخت\",\"sourceType\":7,\"durationDays\":4,\"responsibleUnit\":\"CONSTRUCTION\",\"progressMethod\":0,\"weight\":0,\"budgetAtCompletion\":400000000,\"phase\":3}"
check "pc: activity C (manual progress)" '.success and .data.id > 0'; PCC=$(val .data.id)
actp "{\"contractId\":$PCT,\"code\":\"PC-D\",\"title\":\"تامین ورق ب\",\"sourceType\":6,\"durationDays\":1,\"responsibleUnit\":\"PLANNING\",\"progressMethod\":2,\"weight\":0,\"budgetAtCompletion\":100000000,\"phase\":2,\"purchaseOrderLineId\":$POL2}"
check "pc: activity D (supply receipt, 40 plates)" '.success and .data.id > 0'; PCD=$(val .data.id)
actp "{\"contractId\":$PCT,\"code\":\"PC-X\",\"title\":\"x\",\"sourceType\":6,\"durationDays\":1,\"progressMethod\":2}"; no "pc: supply activity without an order line rejected"
as "$WH_TOKEN" POST $PC/activities "{\"contractId\":$PCT,\"code\":\"PC-Y\",\"title\":\"y\",\"durationDays\":1}"; no "pc: warehouse cannot write activities"
# R1a2 (L6): the responsible unit decides who starts, holds and resumes an activity, so only planning and the PMO set or change it; a project manager (also a unit manager) cannot hand an activity to his own role
as "$PM_TOKEN" POST $PC/activities "{\"contractId\":$PCT,\"code\":\"PC-PM\",\"title\":\"فعالیت واحد مدیر پروژه\",\"sourceType\":7,\"durationDays\":1,\"responsibleUnit\":\"PROJECTMANAGER\",\"progressMethod\":0,\"weight\":0,\"budgetAtCompletion\":1,\"phase\":3}"; nomsg "r1a2 l6: a project manager cannot create an activity for his own unit" "تعیین یا تغییر واحد مسئول"
as "$PM_TOKEN" GET "$PC/activities?ContractId=$PCT&PageSize=0"; PCABODY=$(jq -c --argjson id "$PCA" '.data.data[]|select(.id == $id)' "$B")
as "$PM_TOKEN" POST $PC/activities "$(jq -c '.responsibleUnit = "PROJECTMANAGER"' <<<"$PCABODY")"; nomsg "r1a2 l6: nor move an existing activity of the engineering unit to his own unit" "تعیین یا تغییر واحد مسئول"
as "$PM_TOKEN" POST $PC/activities "$(jq -c . <<<"$PCABODY")"; check "r1a2 l6: (control) the project manager can still save the activity when the unit stays as it is" '.success and .data.responsibleUnit == "ENGINEERING"'
as "$PLAN_TOKEN" GET "$PC/activities?ContractId=$PCT&PageSize=0"; check "r1a2 l6: the refused saves changed nothing: the activity is still the engineering unit's and the refused code PC-PM was not created" ".success and ([.data.data[]|select(.id == $PCA)][0].responsibleUnit) == \"ENGINEERING\" and ([.data.data[]|select(.code == \"PC-PM\")]|length) == 0"
# R1a: starting, holding and resuming an activity belongs to the unit that owns it (ResponsibleUnit), planning and the PMO; the manager of another unit is turned away.
# Only refusals and one hold-and-resume round trip (back to "not started") run here, so the exact schedule figures below are not touched.
as "$WH_TOKEN" POST $PC/activities/action "{\"id\":$PCC,\"action\":\"start\"}"; nomsg "r1a pc: the warehouse manager cannot start an activity of the construction unit" "شروع و توقف فعالیت"
as "$ENG_TOKEN" POST $PC/activities/action "{\"id\":$PCC,\"action\":\"hold\",\"reason\":\"x\"}"; nomsg "r1a pc: the engineering manager cannot hold an activity of the construction unit" "شروع و توقف فعالیت"
as "$PM_TOKEN" POST $PC/activities/action "{\"id\":$PCA,\"action\":\"hold\",\"reason\":\"x\"}"; nomsg "r1a pc: the project manager cannot hold an activity of the engineering unit" "شروع و توقف فعالیت"
as "$ENG_TOKEN" POST $PC/activities/action "{\"id\":$PCA,\"action\":\"hold\",\"reason\":\"انتظار تایید مشخصات\"}"; check "r1a pc: the responsible unit (engineering) holds its own activity" '.success and .data.status == 3'
as "$WH_TOKEN" POST $PC/activities/action "{\"id\":$PCA,\"action\":\"resume\"}"; nomsg "r1a pc: the warehouse manager cannot resume it" "شروع و توقف فعالیت"
as "$ENG_TOKEN" POST $PC/activities/action "{\"id\":$PCA,\"action\":\"resume\"}"; check "r1a pc: the responsible unit resumes it (not started again)" '.success and .data.status == 0'
as "$PLAN_TOKEN" POST $PC/activities/action "{\"id\":$PCC,\"action\":\"hold\",\"reason\":\"انتظار مواد\"}"; check "r1a pc: planning may hold the activity of any unit" '.success and .data.status == 3'
call POST $PC/activities/action "{\"id\":$PCC,\"action\":\"resume\"}"; check "r1a pc: the PMO resumes it (not started again)" '.success and .data.status == 0'

pcdep() { as "$PLAN_TOKEN" POST $PC/dependencies "{\"contractId\":$PCT,\"predecessorId\":$1,\"successorId\":$2,\"type\":1,\"lagDays\":0}"; }
pcdep $PCA $PCB; check "pc: dependency A to B" '.success'
pcdep $PCA $PCC; pcdep $PCB $PCD; check "pc: dependency B to D" '.success'
pcdep $PCC $PCD; check "pc: dependency C to D" '.success'
pcdep $PCD $PCA; no "pc: cycle D to A rejected on save"
pcdep $PCB $PCB; no "pc: self dependency rejected"
pcdep $PCA $PCB; no "pc: duplicate dependency rejected"

# --- CPM: exact dates, float and the critical path
as "$PLAN_TOKEN" POST $PC/cpm/run "{\"contractId\":$PCT,\"forecast\":false,\"mirror\":true}"
check "pc: CPM finishes on 2026-11-11 after 8 working days, no cycle" '.success and .data.hasCycle == false and .data.projectFinishOffset == 8 and (.data.projectFinish|startswith("2026-11-11")) and (.data.projectStart|startswith("2026-11-02"))'
check "pc: CPM early dates of A, C and D" '([.data.items[]|select(.code=="PC-A")][0].earlyFinish|startswith("2026-11-04")) and ([.data.items[]|select(.code=="PC-C")][0].earlyFinish|startswith("2026-11-10")) and ([.data.items[]|select(.code=="PC-D")][0].earlyStart|startswith("2026-11-11"))'
check "pc: activity B has total float 2 (2026-11-05..06)" '[.data.items[]|select(.code=="PC-B")][0]|(.totalFloat == 2 and (.earlyStart|startswith("2026-11-05")) and (.earlyFinish|startswith("2026-11-06")) and .critical == false)'
check "pc: critical path is A, C, D" '.data.criticalPath == ["PC-A","PC-C","PC-D"]'
as "$PM_TOKEN" GET "$PC/activities?ContractId=$PCT&OnlyCritical=true&PageSize=0"; check "pc: critical activity filter" '(.data.data|length) == 3'
as "$PLAN_TOKEN" GET "$PC/executive-plan?ContractId=$PCT&From=2026-11-02&Days=14&PageSize=0"; check "pc: executive plan (look-ahead) lists the activities" '.success'

# --- baseline 0: signatures of the unit managers, approval by the PMO deputy
as "$PLAN_TOKEN" POST $PC/baselines "{\"contractId\":$PCT,\"reason\":\"مبنای اولیه\"}"
check "pc: baseline 0 drafted: 4 activities, BAC 1,000,000,000, 3 unit signatures" '.success and .data.number == 0 and .data.status == 0 and .data.activityCount == 4 and .data.bac == 1000000000 and (.data.signatures|length) == 3'
PCB0=$(val .data.id)
call POST $PC/baselines/action "{\"id\":$PCB0,\"action\":\"approve\"}"; no "pc: baseline cannot be approved before the managers sign"
as "$PM_TOKEN" POST $PC/baselines/action "{\"id\":$PCB0,\"action\":\"sign\"}"; no "pc: project manager is not a signing unit"
as "$PROD_TOKEN" POST $PC/baselines/action "{\"id\":$PCB0,\"action\":\"sign\"}"; check "pc: construction manager signs" '.success and ([.data.signatures[]|select(.unitRole=="CONSTRUCTION")][0].signedAt != null)'
as "$ENG_TOKEN" POST $PC/baselines/action "{\"id\":$PCB0,\"action\":\"sign\"}"; check "pc: engineering manager signs" '.success and .data.status == 0'
as "$PLAN_TOKEN" POST $PC/baselines/action "{\"id\":$PCB0,\"action\":\"sign\"}"; check "pc: planning manager signs -> managers signed" '.success and .data.status == 1'
as "$PM_TOKEN" POST $PC/baselines/action "{\"id\":$PCB0,\"action\":\"approve\"}"; no "pc: only the PMO deputy approves a baseline"
call POST $PC/baselines/action "{\"id\":$PCB0,\"action\":\"approve\"}"; check "pc: baseline 0 approved and current" '.success and .data.status == 2 and .data.isCurrent == true and .data.bac == 1000000000'
call GET "$PC/terms/$PCT"; check "pc: terms point to the current baseline" ".data.currentBaselineId == $PCB0"

# --- engineering progress from the MDR (60/80/100) and the transmittal response codes
as "$DCC_TOKEN" POST $PC/mdr/action "{\"id\":$INT_ID,\"action\":\"first-issue\",\"revision\":\"A\"}"; check "pc: internal document first issue = 60 percent" '.success and .data.issueState == 1 and .data.progressPercent == 60'
as "$DCC_TOKEN" POST $PC/mdr/action "{\"id\":$INT_ID,\"action\":\"internal-approve\"}"; no "pc: DCC cannot approve internally (engineering manager only)"
as "$ENG_TOKEN" POST $PC/mdr/action "{\"id\":$INT_ID,\"action\":\"internal-approve\"}"; check "pc: engineering manager approves the internal document = 100 percent" '.success and .data.issueState == 3 and .data.progressPercent == 100'
PCT_BAD=$(jq -nc --argjson c $PCT --argjson i $INT_ID '{contractId:$c,direction:1,transmittalDate:"2026-10-01T00:00:00",lines:[{deliverableId:$i,purpose:1}]}')
as "$DCC_TOKEN" POST $PC/transmittals "$PCT_BAD"; no "pc: outgoing transmittal with an internal-only document rejected"
PCT1=$(jq -nc --argjson c $PCT --argjson ids "$CL_IDS" '{contractId:$c,direction:1,transmittalDate:"2026-10-01T00:00:00",reference:"Letter 1",lines:($ids|map({deliverableId:.,purpose:1}))}')
as "$DCC_TOKEN" POST $PC/transmittals "$PCT1"
check "pc: transmittal T1 of the 11 client documents, response due 14 days later" '.success and (.data.number|length) > 0 and (.data.lines|length) == 11 and (.data.responseDue|startswith("2026-10-15"))'
TR1=$(val .data.id); TL1=$(jq -r '.data.lines[0].id' "$B"); TL2=$(jq -r '.data.lines[1].id' "$B"); TL3=$(jq -r '.data.lines[2].id' "$B"); TL4=$(jq -r '.data.lines[3].id' "$B")
as "$DCC_TOKEN" GET "$PC/transmittals?OnlyOverdue=true&PageSize=0"; check "pc: unanswered transmittal past its due date is overdue" "[.data.data[]|select(.id == $TR1)]|length == 1"
as "$DCC_TOKEN" POST $PC/transmittals/response "{\"transmittalLineId\":$TL1,\"responseCode\":\"Z\",\"responseDate\":\"2026-10-10T00:00:00\"}"; no "pc: unknown response code rejected"
as "$DCC_TOKEN" POST $PC/transmittals/response "{\"transmittalLineId\":$TL1,\"responseCode\":\"A\",\"responseDate\":\"2026-10-10T00:00:00\"}"; check "pc: client code A approves the document" '.success'
as "$DCC_TOKEN" POST $PC/transmittals/response "{\"transmittalLineId\":$TL2,\"responseCode\":\"A\",\"responseDate\":\"2026-10-10T00:00:00\"}"
as "$DCC_TOKEN" POST $PC/transmittals/response "{\"transmittalLineId\":$TL3,\"responseCode\":\"B\",\"responseDate\":\"2026-10-10T00:00:00\"}"; check "pc: client code B (approved with comments) also approves" '.success'
as "$DCC_TOKEN" POST $PC/transmittals/response "{\"transmittalLineId\":$TL4,\"responseCode\":\"C\",\"responseDate\":\"2026-10-10T00:00:00\"}"; check "pc: client code C leaves the document unapproved" '.success'
PCT2L=$(jq -nc --argjson c $PCT --argjson ids "$CL_IDS" '{contractId:$c,direction:1,transmittalDate:"2026-10-12T00:00:00",reference:"Letter 2",lines:($ids[3:7]|map({deliverableId:.,purpose:1}))}')
as "$DCC_TOKEN" POST $PC/transmittals "$PCT2L"; check "pc: second transmittal re-sends four documents" '.success and (.data.lines|length) == 4'
as "$DCC_TOKEN" GET "$PC/mdr?WorkOrderId=$PCW1&PageSize=0"
check "pc: MDR states: 3+1 approved, 4 at second issue, 4 at first issue" '([.data.data[]|select(.issueState==3)]|length) == 4 and ([.data.data[]|select(.issueState==2)]|length) == 4 and ([.data.data[]|select(.issueState==1)]|length) == 4'
as "$PLAN_TOKEN" POST $PC/cpm/run "{\"contractId\":$PCT,\"forecast\":true,\"mirror\":false}"
as "$PLAN_TOKEN" GET "$PC/activities?ContractId=$PCT&PageSize=0"
check "pc: engineering activity A is exactly 80 percent (average over 12 documents)" '[.data.data[]|select(.code=="PC-A")][0].percentCache == 80'

# --- supply progress from the receipt, the incoming inspection and the NCR
call POST inventory/documents "{\"type\":1,\"documentDate\":\"2026-10-22T00:00:00\",\"warehouseId\":$WQ,\"destinationWarehouseId\":$W1,\"purchaseOrderId\":$PCPO,\"referenceNumber\":\"PC-INV-1\",\"lines\":[{\"itemId\":$PLATE,\"quantity\":60,\"heatNumber\":\"HT-PC1\",\"purchaseOrderLineId\":$POL1},{\"itemId\":$PLATE,\"quantity\":40,\"heatNumber\":\"HT-PC2\",\"purchaseOrderLineId\":$POL2}]}"
check "pc: plate receipt against the order drafted" '.success and (.data.lines|length) == 2'
PCRCV=$(val .data.id); call POST "inventory/documents/$PCRCV/confirm"; check "pc: plate receipt into quarantine confirmed" '.success and .data.status == 1'
as "$PLAN_TOKEN" GET "$PC/activities?ContractId=$PCT&PageSize=0"
as "$PLAN_TOKEN" POST $PC/cpm/run "{\"contractId\":$PCT,\"forecast\":true,\"mirror\":false}"
as "$PLAN_TOKEN" GET "$PC/activities?ContractId=$PCT&PageSize=0"
check "pc: received plates in quarantine = temporary receipt = 70 percent for B and D" '([.data.data[]|select(.code=="PC-B")][0].percentCache == 70) and ([.data.data[]|select(.code=="PC-D")][0].percentCache == 70)'
as "$PLAN_TOKEN" POST $PC/cpm/run "{\"contractId\":$PCT,\"forecast\":true,\"mirror\":false}"

# --- cost entries (actual cost 600,000,000 by 2026-11-06) and manual progress that needs another person's approval
pccost() { as "$FIN_TOKEN" POST $PC/costs "{\"contractId\":$PCT,\"kind\":$1,\"entryDate\":\"$2T00:00:00\",\"amount\":$3,\"description\":\"$4\"}"; }
pccost 1 2026-11-03 400000000 "مواد اولیه"; check "pc: cost entry 400M recorded against the contract" '.success and .data.contractId > 0 and .data.amount == 400000000'
pccost 3 2026-11-05 200000000 "دستمزد"; check "pc: cost entry 200M recorded" '.success'
as "$PLAN_TOKEN" POST $PC/costs "{\"contractId\":$PCT,\"kind\":1,\"entryDate\":\"2026-11-03T00:00:00\",\"amount\":1,\"description\":\"x\"}"; no "pc: planning cannot post costs (finance only)"
as "$PLAN_TOKEN" POST $PC/manual-progress "{\"activityId\":$PCC,\"percent\":50,\"comment\":\"نیمی از ساخت انجام شد\"}"; check "pc: manual progress proposed (pending)" '.success and .data.state == 0 and .data.percent == 50'
PCMP=$(val .data.id)
as "$PLAN_TOKEN" POST $PC/manual-progress "{\"activityId\":$PCA,\"percent\":50}"; no "pc: manual progress on a system-measured activity rejected"
as "$PLAN_TOKEN" GET "$PC/evm/$PCT?asOf=2026-11-06"
check "pc: EVM stage 1: PV 700M, EV 450M (A 80%, B 70%, D 70%, C unapproved excluded), AC 600M" '.success and .data.fromBaseline == true and .data.bac == 1000000000 and .data.pv == 700000000 and .data.ev == 450000000 and .data.ac == 600000000 and .data.cv == -150000000 and .data.sv == -250000000'
check "pc: EVM stage 1 indices: CPI 0.75, SPI 0.6429, both red, corrective action required" '.data.cpi == 0.75 and .data.spi == 0.6429 and .data.cpiStatus == "red" and .data.spiStatus == "red" and .data.correctiveActionRequired == true'
as "$PLAN_TOKEN" POST $PC/manual-progress/decide "{\"id\":$PCMP,\"approve\":true}"; no "pc: the proposer cannot approve their own manual progress"
as "$PM_TOKEN" POST $PC/manual-progress/decide "{\"id\":$PCMP,\"approve\":true}"; no "pc: project manager is not the approver of manual progress"
call POST $PC/manual-progress/decide "{\"id\":$PCMP,\"approve\":true,\"note\":\"تایید\"}"; check "pc: manual progress approved by a different person" '.success and .data.state == 1'
as "$PLAN_TOKEN" GET "$PC/evm/$PCT?asOf=2026-11-06"; check "pc: EVM after approving C at 50 percent: EV 650M" '.data.ev == 650000000 and .data.cpi == 1.0833'

# --- weekly snapshot (immutable) and the scheduled run
PCSNAPDATE=$(dd -14)
as "$PLAN_TOKEN" POST $PC/snapshots "{\"contractId\":$PCT,\"dataDate\":\"${PCSNAPDATE}T00:00:00\"}"
check "pc: weekly snapshot taken with 4 lines, BAC and hash" '.success and (.data.lines|length) == 4 and .data.bac == 1000000000 and (.data.hash|length) > 10'
PCSNAP=$(val .data.id); PCSNAPHASH=$(val .data.hash)
as "$PLAN_TOKEN" POST $PC/snapshots "{\"contractId\":$PCT,\"dataDate\":\"${PCSNAPDATE}T00:00:00\"}"; no "pc: second snapshot for the same data date rejected"
as "$PLAN_TOKEN" POST $PC/snapshots "{\"contractId\":$PCT,\"dataDate\":\"2030-01-02T00:00:00\"}"; no "pc: snapshot with a future data date rejected"
as "$PLAN_TOKEN" GET "$PC/snapshots/$PCSNAP"; check "pc: snapshot unchanged after later progress (hash identical)" ".data.hash == \"$PCSNAPHASH\""
as "$PLAN_TOKEN" POST $PC/snapshots/run-due '{"asOf":"2026-11-11T12:00:00"}'; check "pc: scheduled snapshot run takes the Wednesday snapshot" '.success and .data.snapshotsTaken >= 1'
as "$PLAN_TOKEN" POST $PC/snapshots/run-due '{"asOf":"2026-11-11T12:00:00"}'; check "pc: second run takes nothing (one per data date)" '.success and .data.snapshotsTaken == 0'
as "$PM_TOKEN" POST $PC/snapshots "{\"contractId\":$PCT}"; no "pc: project manager cannot take snapshots (planning)"

# --- QC accepts plate A; plate B is rejected: NCR classified as rework caps D at 80 percent
as "$QC_TOKEN" GET "inventory/quality/inspections?Status=0&PageSize=0"
PCQI1=$(jq -r ".data.data[]|select(.receiptDocumentId==$PCRCV and .quantity==60)|.id" "$B"); PCQI2=$(jq -r ".data.data[]|select(.receiptDocumentId==$PCRCV and .quantity==40)|.id" "$B")
[ -n "$PCQI1" ] && [ -n "$PCQI2" ] && ok "pc: two incoming inspections waiting for the receipt" || bad "pc: two incoming inspections waiting for the receipt"
as "$QC_TOKEN" POST inventory/quality/inspections "{\"id\":$PCQI1,\"acceptedQuantity\":60,\"rejectedQuantity\":0,\"reportNumber\":\"QC-PC-1\"}"; check "pc: plate A accepted (60)" '.success and .data.status == 1'
as "$QC_TOKEN" POST inventory/quality/inspections "{\"id\":$PCQI2,\"acceptedQuantity\":0,\"rejectedQuantity\":40,\"reportNumber\":\"QC-PC-2\",\"rejectReason\":\"ترک سطحی در لبه ورق\"}"; check "pc: plate B rejected (40) -> NCR" '.success and (.data.ncrNumber|startswith("NCR-"))'
PCNCR=$(val .data.ncrId)
as "$PLAN_TOKEN" POST $PC/cpm/run "{\"contractId\":$PCT,\"forecast\":true,\"mirror\":false}"
as "$PLAN_TOKEN" GET "$PC/activities?ContractId=$PCT&PageSize=0"
check "pc: B is 100 after QC accept; D with an unclassified NCR stays at 70" '([.data.data[]|select(.code=="PC-B")][0].percentCache == 100) and ([.data.data[]|select(.code=="PC-D")][0].percentCache == 70)'
as "$QC_TOKEN" POST inventory/quality/ncr "{\"id\":$PCNCR,\"severity\":1,\"disposition\":2,\"source\":1,\"causeCategory\":2,\"rootCause\":\"ورق معیوب از تامین‌کننده\"}"; check "pc: NCR classified: minor, rework (still open)" '.success and .data.disposition == 2'
as "$PLAN_TOKEN" POST $PC/cpm/run "{\"contractId\":$PCT,\"forecast\":true,\"mirror\":false}"
as "$PLAN_TOKEN" GET "$PC/activities?ContractId=$PCT&PageSize=0"
check "pc: D is capped at 80 percent while the rework NCR is open" '[.data.data[]|select(.code=="PC-D")][0].percentCache == 80'
as "$PLAN_TOKEN" GET "$PC/evm/$PCT?asOf=2026-11-06"
check "pc: EVM stage 2 exact: PV 700M, EV 720M, AC 600M, CV 120M, SV 20M" '.data.pv == 700000000 and .data.ev == 720000000 and .data.ac == 600000000 and .data.cv == 120000000 and .data.sv == 20000000'
check "pc: EVM stage 2 indices: CPI 1.2, SPI 1.0286, EAC 833,333,333.33" '.data.cpi == 1.2 and .data.spi == 1.0286 and .data.eacTypical == 833333333.33 and .data.cpiStatus == "green" and .data.spiStatus == "green" and .data.correctiveActionRequired == false'
as "$PLAN_TOKEN" GET "$PC/progress/$PCT"; check "pc: physical progress is the average of the four activities" '.success and .data.physicalPercent == 77.5'
as "$PLAN_TOKEN" GET "$PC/cash-flow/$PCT"; check "pc: cash flow curve (S curve) is returned" '.success'

# --- change request: scenario, impact on the critical path, board, authority, new baseline
PCCH="{\"contractId\":$PCT,\"origin\":2,\"type\":2,\"managerAgreement\":\"موافقت مدیر برنامه‌ریزی\",\"description\":\"افزایش زمان ساخت به دلیل تعمیر قالب\",\"reason\":\"عیب قالب\",\"requestedDaysDelta\":2,\"requestedPriceDelta\":100000000,\"scenario\":[{\"activityId\":$PCC,\"durationDelta\":2,\"budgetDelta\":100000000}]}"
as "$SEC_TOKEN" POST $PC/changes "$PCCH"; no "pc: security user is not a requester of changes"
as "$PLAN_TOKEN" POST $PC/changes "$(echo "$PCCH" | jq -c 'del(.managerAgreement)')"; no "pc: internal request needs the requester manager's agreement"
as "$PLAN_TOKEN" POST $PC/changes "$PCCH"; check "pc: change request drafted with its scenario" '.success and .data.status == 0 and (.data.scenario|length) == 1 and (.data.number|length) > 0'
PCCHID=$(val .data.id)
as "$PLAN_TOKEN" POST $PC/changes/action "{\"id\":$PCCHID,\"action\":\"register\"}"
check "pc: registered; board = project manager, planning, construction, commercial; due date set" '.success and .data.status == 1 and ([.data.board[].role]|sort) == ["COMMERCIAL","CONSTRUCTION","PLANNING","PROJECTMANAGER"] and .data.dueDate != null'
call POST $PC/changes/action "{\"id\":$PCCHID,\"action\":\"decide\",\"decision\":1,\"note\":\"x\"}"; no "pc: decision before the impact analysis rejected"
as "$PLAN_TOKEN" POST $PC/changes/action "{\"id\":$PCCHID,\"action\":\"analyze\"}"
check "pc: impact analysis: +2 days, +100M, on the critical path, C and D move" '.success and .data.status == 2 and .data.impactDeltaDays == 2 and .data.impactDeltaCost == 100000000 and .data.impactOnCriticalPath == true and ([.data.impactActivities[].code]|index("PC-C") != null) and ([.data.impactActivities[].code]|index("PC-D") != null)'
as "$PLAN_TOKEN" POST $PC/changes/action "{\"id\":$PCCHID,\"action\":\"recommend\",\"note\":\"تایید با رعایت مهلت\"}"; no "pc: planning cannot give the project manager's recommendation"
as "$PM_TOKEN" POST $PC/changes/action "{\"id\":$PCCHID,\"action\":\"recommend\",\"note\":\"تایید با رعایت مهلت\"}"; check "pc: project manager recommends" '.success and .data.recommendation != null'
call POST $PC/changes/action "{\"id\":$PCCHID,\"action\":\"decide\",\"decision\":1,\"note\":\"x\"}"; no "pc: decision before the board has voted rejected"
as "$PM_TOKEN" POST $PC/changes/action "{\"id\":$PCCHID,\"action\":\"vote\",\"vote\":1}"; check "pc: project manager votes" '.success'
as "$PLAN_TOKEN" POST $PC/changes/action "{\"id\":$PCCHID,\"action\":\"vote\",\"vote\":1}"
as "$PROD_TOKEN" POST $PC/changes/action "{\"id\":$PCCHID,\"action\":\"vote\",\"vote\":1}"
as "$COM_TOKEN" POST $PC/changes/action "{\"id\":$PCCHID,\"action\":\"vote\",\"vote\":1}"; check "pc: all four board members voted" '.success and ([.data.board[]|select(.vote == 1)]|length) == 4'
as "$PM_TOKEN" POST $PC/changes/action "{\"id\":$PCCHID,\"action\":\"decide\",\"decision\":1,\"note\":\"x\"}"; no "pc: project manager recommends only, cannot decide (authority table)"
call POST $PC/changes/action "{\"id\":$PCCHID,\"action\":\"decide\",\"decision\":1,\"note\":\"تایید معاون PMO\"}"
check "pc: PMO deputy approves within authority -> implementing, baseline attached" '.success and .data.status == 4 and .data.decision == 1 and .data.baselineId != null'
call GET "$PC/baselines?ContractId=$PCT&PageSize=0"
check "pc: baseline 1 approved and current (BAC 1.1bn); baseline 0 superseded" '([.data.data[]|select(.number==1)][0]|(.status == 2 and .isCurrent == true and .bac == 1100000000 and .changeRequestId != null)) and ([.data.data[]|select(.number==0)][0].status == 3)'
as "$PLAN_TOKEN" GET "$PC/activities?ContractId=$PCT&PageSize=0"
check "pc: plan re-run: C now 6 days ends 2026-11-12, D 2026-11-13, budget of C 500M" '([.data.data[]|select(.code=="PC-C")][0]|(.durationDays == 6 and (.earlyFinish|startswith("2026-11-12")) and .budgetAtCompletion == 500000000)) and ([.data.data[]|select(.code=="PC-D")][0].earlyFinish|startswith("2026-11-13"))'
as "$PM_TOKEN" POST $PC/changes/action "{\"id\":$PCCHID,\"action\":\"close\"}"; no "pc: only planning closes a change"
as "$PLAN_TOKEN" POST $PC/changes/action "{\"id\":$PCCHID,\"action\":\"close\"}"; check "pc: change closed" '.success and .data.status == 5'
as "$PLAN_TOKEN" GET "$PC/changes?ContractId=$PCT"; check "pc: change list is paged" '.success and (.data.data|length) >= 1'
call GET "$PC/approval-authorities"; check "pc: approval authority table seeded (PMO up to 5bn rial and 30 days; PM recommends only)" '.success and ([.data[]|select(.role=="PMO")][0]|(.canDecide == true and .maxAmount == 5000000000 and .maxDelayDays == 30)) and ([.data[]|select(.role=="PROJECTMANAGER")][0].canDecide == false)'
as "$CEO_TOKEN" GET "$PC/approval-authorities"; check "pc: the CEO also reads the table" '.success'

# --- commercial: payment milestones, guarantee alerts, late penalty (contract PCP)
as "$COM_TOKEN" POST $PC/milestones "{\"contractId\":$QCT,\"title\":\"پرداخت پس از ترخیص کیفی\",\"kind\":3,\"trigger\":4,\"workOrderId\":$WO1,\"amount\":50000000}"; check "pc: payment milestone on the release note trigger" '.success and .data.status == 0 and .data.seq == 1'
PCMS1=$(val .data.id)
as "$COM_TOKEN" POST $PC/milestones "{\"contractId\":$QCT,\"title\":\"پرداخت تاریخ‌دار\",\"kind\":9,\"trigger\":1,\"plannedDate\":\"$(dd -1)T00:00:00\",\"amount\":10000000}"; check "pc: payment milestone on a date" '.success'
as "$COM_TOKEN" POST $PC/milestones "{\"contractId\":$QCT,\"title\":\"پرداخت پیشرفت\",\"kind\":2,\"trigger\":2,\"triggerPercent\":100,\"amount\":10000000}"
# R1a: the evaluation moves milestones to "due" (it starts the invoicing flow): PMO, planning, commercial and financial only; the role attribute answers 403 with the standard refusal body
as "$WH_TOKEN" POST $PC/milestones/evaluate/$QCT; r403 "r1a pc: the storekeeper cannot evaluate payment milestones (403)"
as "$QC_TOKEN" POST $PC/milestones/evaluate/$QCT; r403 "r1a pc: QC cannot evaluate payment milestones (403)"
as "$COM_TOKEN" POST $PC/milestones/evaluate/$QCT; check "pc: released note and a past date make two milestones due; progress one stays planned" '.success and .data.becameDue == 2 and ([.data.milestones[]|select(.status == 1)]|length) == 2'
as "$QC_TOKEN" POST $PC/milestones "{\"contractId\":$QCT,\"title\":\"x\",\"kind\":9,\"trigger\":1,\"plannedDate\":\"$(dd 1)T00:00:00\",\"amount\":1}"; no "pc: QC cannot define payment milestones"
as "$COM_TOKEN" POST $PC/milestones/action "{\"id\":$PCMS1,\"action\":\"paid\"}"; no "pc: a milestone that is only due cannot be marked paid"
# R1a2 (M3): a provisional statement that a payment point refers to is neither edited nor deleted; one nobody refers to is, and both leave rows in the audit trail
M3PSB='"type":"موقت","status":"ارسال شده"'
call POST ContractProvisionalStatements "{\"contractId\":$QCT,\"number\":11,\"date\":\"$(dd -2)T00:00:00Z\",\"price\":30000000,\"acceptedPrice\":30000000,$M3PSB}"; check "r1a2 m3: setup: a provisional statement of the contract" '.success and .data.id > 0'
M3PS=$(val .data.id)
call POST ContractProvisionalStatements "{\"contractId\":$QCT,\"number\":12,\"date\":\"$(dd -1)T00:00:00Z\",\"price\":1000,\"acceptedPrice\":1000,$M3PSB}"; check "r1a2 m3: setup: a second statement that no payment point will refer to" '.success and .data.id > 0'
M3PS2=$(val .data.id)
as "$COM_TOKEN" POST $PC/milestones "{\"contractId\":$QCT,\"title\":\"پرداخت صورت‌وضعیت یازده\",\"kind\":9,\"trigger\":1,\"plannedDate\":\"$(dd -2)T00:00:00\",\"amount\":30000000}"; check "r1a2 m3: setup: a payment point dated in the past" '.success and .data.status == 0'
M3MS=$(val .data.id)
as "$COM_TOKEN" POST $PC/milestones/evaluate/$QCT; check "r1a2 m3: setup: the payment point becomes due" '.success and .data.becameDue == 1'
as "$COM_TOKEN" POST $PC/milestones/action "{\"id\":$M3MS,\"action\":\"statement\",\"provisionalStatementId\":$M3PS}"; check "r1a2 m3: setup: the payment point takes the statement (status 2, statement issued)" ".success and .data.status == 2 and .data.provisionalStatementId == $M3PS"
call PUT ContractProvisionalStatements "{\"id\":$M3PS,\"contractId\":$QCT,\"number\":11,\"date\":\"$(dd -2)T00:00:00Z\",\"price\":99000000,\"acceptedPrice\":99000000,$M3PSB}"; nomsg "r1a2 m3: a statement that a payment point refers to is not edited" "ویرایش صورت‌وضعیت ممکن نیست"
call DELETE ContractProvisionalStatements "{\"id\":$M3PS,\"contractId\":$QCT}"; nomsg "r1a2 m3: nor deleted; the answer names the payment points" "نقاط پرداخت"
call GET "ContractProvisionalStatements?Id=$M3PS&ContractId=$QCT"; check "r1a2 m3: the refused edit and delete left the statement as it was" '.success and .data.price == 30000000 and .data.acceptedPrice == 30000000'
# R1a2 (M8): the two amounts of a statement are for the roles that work with money and plans
as "$WH_TOKEN" GET "ContractProvisionalStatements?Id=$M3PS&ContractId=$QCT"; check "r1a2 m8: a storekeeper reads the statement without its two amounts" '.success and .data.id > 0 and .data.price == null and .data.acceptedPrice == null and .data.number == 11'
as "$COM_TOKEN" GET "ContractProvisionalStatements?Id=$M3PS&ContractId=$QCT"; check "r1a2 m8: the commercial user reads both amounts" '.success and .data.price == 30000000 and .data.acceptedPrice == 30000000'
as "$WH_TOKEN" GET "ContractProvisionalStatements/provisional-statements?ContractId=$QCT"; check "r1a2 m8: in the list of statements the storekeeper sees no amount at all" '.success and (.data.data|length) >= 1 and ([.data.data[]|select(.price != null or .acceptedPrice != null)]|length) == 0'
call PUT ContractProvisionalStatements "{\"id\":$M3PS2,\"contractId\":$QCT,\"number\":12,\"date\":\"$(dd -1)T00:00:00Z\",\"price\":2000,\"acceptedPrice\":2000,$M3PSB}"; check "r1a2 m3: a statement that nothing refers to is edited as before" '.success and .data.price == 2000'
call DELETE ContractProvisionalStatements "{\"id\":$M3PS2,\"contractId\":$QCT}"; check "r1a2 m3: and deleted as before" '.success'
call GET "ContractProvisionalStatements?Id=$M3PS2&ContractId=$QCT"; nomsg "r1a2 m3: and it is gone" "یافت نشد"

call POST ContractGuaranty "{\"title\":\"ضمانت‌نامه حسن انجام کار\",\"bank\":\"ملی\",\"no\":\"PC-G-1\",\"price\":\"500,000,000\",\"regDate\":\"$(dd -300)T00:00:00\",\"dueDate\":\"$(dd 10)T00:00:00\",\"contractEntityId\":$PCT}"; check "pc: legacy contract guaranty created (text amount)" '.success'
as "$COM_TOKEN" POST $PC/guarantees/parse; check "pc: legacy guarantees parsed into typed side data" '.success and .data.created >= 1'
as "$COM_TOKEN" GET "$PC/guarantees?ContractId=$PCT&PageSize=0"; check "pc: guarantee amount parsed to 500,000,000, expiry in 10 days" '.success and ([.data.data[]|select(.no=="PC-G-1")][0]|(.amountDecimal == 500000000 and .parseFailed == false and .daysToExpiry == 10))'
as "$COM_TOKEN" GET "$PC/guarantees/alerts?contractId=$PCT"; check "pc: guarantee alert listed at the 14-day level" '(if type == "array" then . else .data end) | ([.[]|select(.no=="PC-G-1")][0]|(.alertLevel == 14 and .daysToExpiry == 10))'
as "$QC_TOKEN" POST $PC/guarantees/parse; no "pc: QC cannot parse guarantees"

# --- guarantee release (R1a): a second guarantee (PC-G-2, expiry far away, so the alert figures of PC-G-1 stay as they are) is released through its own action
# (date not in the future and a note are required; commercial, finance manager and PMO sign it); a direct "Released" or "Expired" through the other calls is refused,
# because the release must leave a dated event with its note and the expiry is written by the daily job (covered by the unit tests, there is no HTTP route to run it)
call POST ContractGuaranty "{\"title\":\"ضمانت‌نامه پیش‌پرداخت\",\"bank\":\"ملی\",\"no\":\"PC-G-2\",\"price\":\"200,000,000\",\"regDate\":\"$(dd -100)T00:00:00\",\"dueDate\":\"$(dd 200)T00:00:00\",\"contractEntityId\":$PCT}"; check "r1a pc: second legacy guaranty created" '.success'
as "$COM_TOKEN" POST $PC/guarantees/parse; check "r1a pc: the second guaranty is parsed into typed side data" '.success and .data.created >= 1'
as "$COM_TOKEN" GET "$PC/guarantees?ContractId=$PCT&PageSize=0"; check "r1a pc: the second guarantee is active with the amount 200,000,000 and no release event" '.success and ([.data.data[]|select(.no=="PC-G-2")][0]|(.status == 3 and .amountDecimal == 200000000 and (.events|length) == 0))'
PCG2=$(jq -r '[.data.data[]|select(.no=="PC-G-2")][0].id' "$B"); PCG2BODY=$(jq -c '[.data.data[]|select(.no=="PC-G-2")][0]|del(.events)' "$B"); PCGROWS=$(jq -c '[.data.data[].id]|sort' "$B")
as "$FM_TOKEN" GET "$PC/guarantees?ContractId=$PCT&PageSize=0"; check "r1a pc: the finance manager, who releases guarantees, reads the guarantees list too (the same rows the commercial user sees)" ".success and ([.data.data[].id]|sort) == $PCGROWS"
as "$COM_TOKEN" POST $PC/guarantees "$(jq -c '.status = 6' <<< "$PCG2BODY")"; nomsg "r1a pc: Released cannot be set through the save call (only the release action does it)" "از این مسیر"
as "$COM_TOKEN" POST $PC/guarantees "$(jq -c '.status = 5' <<< "$PCG2BODY")"; nomsg "r1a pc: Expired cannot be set by hand either (the expiry is automatic: correct the date or extend)" "تمدید کنید"
as "$COM_TOKEN" POST $PC/guarantees/events "{\"guaranteeId\":$PCG2,\"kind\":4,\"eventDate\":\"$(dd 0)T00:00:00\"}"; nomsg "r1a pc: a release event cannot be added through the events call" "guarantees/release"
as "$COM_TOKEN" POST $PC/guarantees/events "{\"guaranteeId\":$PCG2,\"kind\":5,\"eventDate\":\"$(dd 0)T00:00:00\"}"; nomsg "r1a pc: an expiry event cannot be added by hand" "خودکار ثبت"
RELBODY="{\"guaranteeId\":$PCG2,\"releaseDate\":\"$(dd 0)T00:00:00\",\"note\":\"نامه کارفرما شماره ۱۲۳\"}"
as "$WH_TOKEN" POST $PC/guarantees/release "$RELBODY"; r403 "r1a pc: the storekeeper cannot release a guarantee (403)"
as "$FIN_TOKEN" POST $PC/guarantees/release "$RELBODY"; r403 "r1a pc: the accountant cannot release a guarantee either (403)"
as "$COM_TOKEN" POST $PC/guarantees/release "{\"guaranteeId\":$PCG2,\"note\":\"نامه کارفرما\"}"; nomsg "r1a pc: a release needs a date" "تاریخ آزادسازی را وارد کنید"
as "$COM_TOKEN" POST $PC/guarantees/release "{\"guaranteeId\":$PCG2,\"releaseDate\":\"$(dd 3)T00:00:00\",\"note\":\"نامه کارفرما\"}"; nomsg "r1a pc: a release date in the future is refused" "در آینده"
as "$COM_TOKEN" POST $PC/guarantees/release "{\"guaranteeId\":$PCG2,\"releaseDate\":\"$(dd 0)T00:00:00\"}"; nomsg "r1a pc: a release needs a note (the letter of the client or the bank)" "توضیح"
# R1a2 (M2): the release needs two people. The first call only records who asked and when; the guarantee stays active and no release event exists. A different person of the roles confirms with the same call.
COMID=$(uid "$COM_TOKEN"); FMID2=$(uid "$FM_TOKEN")
[ -n "$COMID" ] && [ -n "$FMID2" ] && ok "r1a2 m2: the ids of the commercial user and the finance manager are resolved" || bad "r1a2 m2: the ids of the commercial user and the finance manager are resolved"
as "$COM_TOKEN" POST $PC/guarantees/release "$RELBODY"
check "r1a2 m2: the first call records who asked and when; the guarantee stays active and no release event is written" ".success and .data.status == 3 and .data.releaseRequestedByUserId == $COMID and (.data.releaseRequestedAt|length) > 0 and (.data.events|length) == 0 and (.message|contains(\"منتظر تأیید\"))"
as "$COM_TOKEN" POST $PC/guarantees/release "$RELBODY"; nomsg "r1a2 m2: the person who asked cannot confirm the own request" "خودتان ثبت کرده"
as "$COM_TOKEN" GET "$PC/guarantees?ContractId=$PCT&PageSize=0"; check "r1a2 m2: so the guarantee is still active, with the request on its record" ".success and ([.data.data[]|select(.no==\"PC-G-2\")][0]|(.status == 3 and .releaseRequestedByUserId == $COMID and (.events|length) == 0))"
as "$FM_TOKEN" POST $PC/guarantees/release "$RELBODY"
check "r1a pc: a different person, the finance manager, confirms: the guarantee is released and the release event carries the date and the note" '.success and .data.status == 6 and ([.data.events[]|select(.kind == 4)]|length) == 1 and ([.data.events[]|select(.kind == 4)][0].note|contains("نامه کارفرما"))'
as "$COM_TOKEN" POST $PC/guarantees/release "$RELBODY"; nomsg "r1a pc: a released guarantee is not released twice" "قبلاً آزاد شده"
as "$COM_TOKEN" POST $PC/guarantees "$(jq -c '.status = 3' <<< "$PCG2BODY")"; nomsg "r1a pc: a released guarantee is not opened again" "دوباره باز نمی"
as "$COM_TOKEN" POST $PC/guarantees/events "{\"guaranteeId\":$PCG2,\"kind\":3,\"eventDate\":\"$(dd 0)T00:00:00\"}"; nomsg "r1a pc: no event is added to a closed guarantee" "بسته شده"
as "$COM_TOKEN" GET "$PC/guarantees?ContractId=$PCT&PageSize=0"; check "r1a pc: the register shows the released guarantee; PC-G-1 is untouched (active)" '.success and ([.data.data[]|select(.no=="PC-G-2")][0].status == 6) and ([.data.data[]|select(.no=="PC-G-1")][0].status == 3)'

# R1a2 (M2): once a guarantee is issued, its expiry date is what the bank holds: it changes only through an extension event with its evidence (a note, and the letter when there is one).
# The cancellation is an event of its own with the rules of the release (roles, a date that is not in the future, a note) and a second person; saving with the status Cancelled is refused.
# A third guarantee (PC-G-3, expiry far away: the alert figures of PC-G-1 stay as they are) is used for this.
call POST ContractGuaranty "{\"title\":\"ضمانت‌نامه تعهد قطعات\",\"bank\":\"ملی\",\"no\":\"PC-G-3\",\"price\":\"100,000,000\",\"regDate\":\"$(dd -10)T00:00:00\",\"dueDate\":\"$(dd 400)T00:00:00\",\"contractEntityId\":$PCT}"; check "r1a2 m2: a third legacy guaranty is created" '.success and .data.id > 0'; PCG3L=$(val .data.id)
as "$COM_TOKEN" POST $PC/guarantees/parse; check "r1a2 m2: the third guaranty is parsed into typed side data" '.success and .data.created >= 1'
as "$COM_TOKEN" GET "$PC/guarantees?ContractId=$PCT&PageSize=0"
check "r1a2 m2: the third guarantee is active with the amount 100,000,000 and no request on its record" '.success and ([.data.data[]|select(.no=="PC-G-3")][0]|(.status == 3 and .amountDecimal == 100000000 and .releaseRequestedByUserId == null and (.events|length) == 0))'
PCG3=$(jq -r '[.data.data[]|select(.no=="PC-G-3")][0].id' "$B"); PCG3BODY=$(jq -c '[.data.data[]|select(.no=="PC-G-3")][0]|del(.events)' "$B")
# R1a2 (M3): the legacy row of a guaranty that project control keeps a record for (expiry, alerts, release) is not deleted, whatever its state (active, released ...)
PCGSRC=$(jq -c '[.data.data[]|select(.no != null)|{(.no): .sourceId}]|add' "$B")
# R1a2 review (L-6): the price text of a guaranty ("500,000,000") is money data as well. The contract carries its guaranties (the read stays open to every signed-in user): the price roles and the roles
# that write guaranties read the text, everybody else gets it left out and the rest of the record as it was
for L6T in COM_TOKEN FM_TOKEN PLAN_TOKEN CEO_TOKEN TR_TOKEN; do as "${!L6T}" GET "Contracts/contracts?Id=$PCT"; check "r1a2 review l-6: ${L6T%_TOKEN} reads the price of the guaranties of the contract" '.success and ([.data.guaranties[]|select(.no == "PC-G-1" and .price == "500,000,000")]|length) == 1 and ([.data.guaranties[]|select(.no == "PC-G-3" and .price == "100,000,000")]|length) == 1'; done
for L6T in WH_TOKEN QC_TOKEN ENG_TOKEN; do as "${!L6T}" GET "Contracts/contracts?Id=$PCT"; check "r1a2 review l-6: ${L6T%_TOKEN} reads the guaranties of the contract with the price text left out and the rest of the record there" '.success and (.data.guaranties|length) >= 3 and ([.data.guaranties[]|select(.price != null)]|length) == 0 and ([.data.guaranties[]|select(.no == "PC-G-1" and .bank == "ملی")]|length) == 1'; done
# R1a2 (M3), continued: the deletes of the legacy rows
for PCGNO in PC-G-1 PC-G-2 PC-G-3; do
  PCGLID=$(jq -r --arg g "$PCGNO" '.[$g]' <<<"$PCGSRC")
  call DELETE "ContractGuaranty?contractGuarantyId=$PCGLID"; nomsg "r1a2 m3: the legacy guaranty $PCGNO, which project control keeps a record for, cannot be deleted" "حذف ضمانت‌نامه ممکن نیست"
done
[ "$(jq -r '.["PC-G-3"]' <<<"$PCGSRC")" = "$PCG3L" ] && ok "r1a2 m3: the source id of the register entry is the id of the legacy guaranty" || bad "r1a2 m3: the source id of the register entry is the id of the legacy guaranty ($PCGSRC / $PCG3L)"
as "$COM_TOKEN" POST $PC/guarantees "$PCG3BODY"; check "r1a2 m2: (control) the save call with the expiry date unchanged is accepted" '.success and .data.status == 3'
as "$COM_TOKEN" POST $PC/guarantees "$(jq -c --arg d "$(dd 500)T00:00:00" '.expiryDate = $d' <<< "$PCG3BODY")"; nomsg "r1a2 m2: the save call no longer moves the expiry date of an issued guarantee" "فقط با رویداد"
as "$COM_TOKEN" POST $PC/guarantees "$(jq -c '.status = 7' <<< "$PCG3BODY")"; nomsg "r1a2 m2: Cancelled cannot be typed into the save call (the cancellation event does it)" "از رویداد «ابطال»"
EXTBODY="{\"guaranteeId\":$PCG3,\"kind\":2,\"eventDate\":\"$(dd 0)T00:00:00\",\"newExpiryDate\":\"$(dd 500)T00:00:00\""
as "$COM_TOKEN" POST $PC/guarantees/events "$EXTBODY}"; nomsg "r1a2 m2: an extension without a note (the letter or addendum of the bank) is refused" "توضیح"
as "$COM_TOKEN" POST $PC/guarantees/events "$EXTBODY,\"note\":\"الحاقیه بانک شماره ۷\",\"documentId\":\"00000000-0000-0000-0000-000000000001\"}"; nomsg "r1a2 m2: an extension that names a letter file which does not exist is refused" "فایل نامه"
as "$COM_TOKEN" POST $PC/guarantees/events "$EXTBODY,\"note\":\"الحاقیه بانک شماره ۷\"}"; check "r1a2 m2: an extension with a note moves the expiry date and leaves its event" ".success and (.data.expiryDate|startswith(\"$(dd 500)\")) and ([.data.events[]|select(.kind == 2)]|length) == 1"
CANCELBODY="{\"guaranteeId\":$PCG3,\"kind\":3,\"eventDate\":\"$(dd 0)T00:00:00\",\"note\":\"نامه کارفرما شماره ۴۵۶\"}"
as "$WH_TOKEN" POST $PC/guarantees/events "$CANCELBODY"; nomsg "r1a2 m2: a storekeeper cannot cancel a guarantee" "مجوز"
as "$FIN_TOKEN" POST $PC/guarantees/events "$CANCELBODY"; nomsg "r1a2 m2: the accountant cannot cancel a guarantee either (commercial, finance manager and PMO do)" "مجوز"
as "$COM_TOKEN" POST $PC/guarantees/events "{\"guaranteeId\":$PCG3,\"kind\":3,\"eventDate\":\"$(dd 0)T00:00:00\"}"; nomsg "r1a2 m2: a cancellation needs a note" "توضیح"
as "$COM_TOKEN" POST $PC/guarantees/events "{\"guaranteeId\":$PCG3,\"kind\":3,\"eventDate\":\"$(dd 3)T00:00:00\",\"note\":\"x\"}"; nomsg "r1a2 m2: a cancellation date in the future is refused" "در آینده"
as "$COM_TOKEN" POST $PC/guarantees/events "$CANCELBODY"
check "r1a2 m2: the first call records who asked; the guarantee stays active and no cancellation event is written" ".success and .data.status == 3 and .data.releaseRequestedByUserId == $COMID and ([.data.events[]|select(.kind == 3)]|length) == 0 and (.message|contains(\"منتظر تأیید\"))"
as "$COM_TOKEN" POST $PC/guarantees/events "$CANCELBODY"; nomsg "r1a2 m2: the person who asked cannot confirm the own cancellation" "خودتان ثبت کرده"
as "$FM_TOKEN" POST $PC/guarantees/events "$CANCELBODY"
check "r1a2 m2: a different person, the finance manager, confirms: the guarantee is cancelled and the event carries the note" '.success and .data.status == 7 and ([.data.events[]|select(.kind == 3)]|length) == 1 and ([.data.events[]|select(.kind == 3)][0].note|contains("نامه کارفرما"))'
as "$FM_TOKEN" POST $PC/guarantees/release "{\"guaranteeId\":$PCG3,\"releaseDate\":\"$(dd 0)T00:00:00\",\"note\":\"نامه کارفرما\"}"; nomsg "r1a2 m2: a cancelled guarantee is not released" "آزاد نمی"
as "$COM_TOKEN" POST $PC/guarantees "$(jq -c '.status = 3' <<< "$PCG3BODY")"; nomsg "r1a2 m2: a cancelled guarantee is not opened again" "دوباره باز نمی"

# --- R1a2 review (M-3): the release and the cancellation of a guarantee share ONE request slot. The first call records who asked, for WHICH of the two (release = 1, cancellation = 2), with which date and
# note; only the same action confirms it, and the confirmation records the date and the note of the request. The one who asked, or a PMO user, takes the request back (guarantees/withdraw).
# A fourth guarantee (PC-G-4, expiry far away: the alert figures of PC-G-1 stay as they are) is used for this; it ends released.
call POST ContractGuaranty "{\"title\":\"ضمانت‌نامه آزمون درخواست مشترک\",\"bank\":\"ملی\",\"no\":\"PC-G-4\",\"price\":\"50,000,000\",\"regDate\":\"$(dd -5)T00:00:00\",\"dueDate\":\"$(dd 450)T00:00:00\",\"contractEntityId\":$PCT}"; check "r1a2 review m-3: a fourth legacy guaranty is created" '.success and .data.id > 0'
as "$COM_TOKEN" POST $PC/guarantees/parse; check "r1a2 review m-3: the fourth guaranty is parsed into typed side data" '.success and .data.created >= 1'
as "$COM_TOKEN" GET "$PC/guarantees?ContractId=$PCT&PageSize=0"
check "r1a2 review m-3: the fourth guarantee is active with the amount 50,000,000 and no request on its record" '.success and ([.data.data[]|select(.no=="PC-G-4")][0]|(.status == 3 and .amountDecimal == 50000000 and .releaseRequestedByUserId == null and .releaseRequestedKind == null and .releaseRequestOpen == false))'
PCG4=$(jq -r '[.data.data[]|select(.no=="PC-G-4")][0].id' "$B")
M3D=$(dd -2); M3N='نامه کارفرما شماره ۷۷۱'
as "$COM_TOKEN" POST $PC/guarantees/release "{\"guaranteeId\":$PCG4,\"releaseDate\":\"${M3D}T00:00:00\",\"note\":\"$M3N\"}"
check "r1a2 review m-3: a release is requested: the guarantee stays active, and the request says which action it is for (release = 1) with its date and its note" ".success and .data.status == 3 and .data.releaseRequestedByUserId == $COMID and .data.releaseRequestedKind == 1 and .data.releaseRequestedNote == \"$M3N\" and (.data.releaseRequestedDate|startswith(\"$M3D\")) and .data.releaseRequestOpen == true and (.data.events|length) == 0"
as "$FM_TOKEN" POST $PC/guarantees/events "{\"guaranteeId\":$PCG4,\"kind\":3,\"eventDate\":\"$(dd 0)T00:00:00\",\"note\":\"نامه بانک\"}"
nomsg "r1a2 review m-3: a different person cannot confirm the RELEASE request by cancelling: the refusal names the pending action" "درخواست «آزادسازی» منتظر تأیید است"
as "$COM_TOKEN" GET "$PC/guarantees?ContractId=$PCT&PageSize=0"
check "r1a2 review m-3: so the guarantee is still active and the release request is untouched: the same person, kind, note and date" ".success and ([.data.data[]|select(.no==\"PC-G-4\")][0]|(.status == 3 and .releaseRequestedByUserId == $COMID and .releaseRequestedKind == 1 and .releaseRequestedNote == \"$M3N\" and (.releaseRequestedDate|startswith(\"$M3D\")) and .releaseRequestOpen == true))"
# the request is taken back by the one who asked or by a PMO user; the others (and the roles outside the lists) cannot
WDBODY="{\"guaranteeId\":$PCG4}"
as "$WH_TOKEN" POST $PC/guarantees/withdraw "$WDBODY"; r403 "r1a2 review m-3: the storekeeper cannot take a request back (403)"
as "$FIN_TOKEN" POST $PC/guarantees/withdraw "$WDBODY"; r403 "r1a2 review m-3: the accountant cannot take a request back either (403)"
as "$FM_TOKEN" POST $PC/guarantees/withdraw "$WDBODY"; nomsg "r1a2 review m-3: a finance manager who did not ask cannot take the request back (the one who asked, or a PMO user, can)" "فقط کسی که آن را ثبت کرده یا کاربر PMO"
as "$COM_TOKEN" POST $PC/guarantees/withdraw "$WDBODY"
check "r1a2 review m-3: the one who asked takes the request back: all five fields are cleared, the guarantee is as before, and the answer says which request it was" '.success and .data.status == 3 and .data.releaseRequestedByUserId == null and .data.releaseRequestedAt == null and .data.releaseRequestedKind == null and .data.releaseRequestedNote == null and .data.releaseRequestedDate == null and .data.releaseRequestOpen == false and (.message|contains("درخواست آزادسازی پس گرفته شد"))'
as "$COM_TOKEN" POST $PC/guarantees/withdraw "$WDBODY"; nomsg "r1a2 review m-3: there is nothing to take back a second time" "درخواستی منتظر تأیید نیست"
as "$FM_TOKEN" POST $PC/guarantees/release "{\"guaranteeId\":$PCG4,\"releaseDate\":\"${M3D}T00:00:00\",\"note\":\"$M3N\"}"
check "r1a2 review m-3: a call by another person after the withdrawal is only a new request, it releases nothing: the request now belongs to the finance manager" ".success and .data.status == 3 and .data.releaseRequestedByUserId == $FMID2 and .data.releaseRequestedKind == 1 and (.data.events|length) == 0"
call POST $PC/guarantees/withdraw "$WDBODY"
check "r1a2 review m-3: a PMO user takes back a request that somebody else made" '.success and .data.releaseRequestedByUserId == null and .data.releaseRequestedKind == null and .data.releaseRequestOpen == false'
# the other way round: a request for the cancellation is not confirmed by a release call
as "$COM_TOKEN" POST $PC/guarantees/events "{\"guaranteeId\":$PCG4,\"kind\":3,\"eventDate\":\"$(dd -1)T00:00:00\",\"note\":\"نامه بانک\"}"
check "r1a2 review m-3: a cancellation is requested: the request says it is for the cancellation (kind 2) and nothing else changes" '.success and .data.status == 3 and .data.releaseRequestedKind == 2 and .data.releaseRequestOpen == true and (.data.events|length) == 0'
as "$FM_TOKEN" POST $PC/guarantees/release "{\"guaranteeId\":$PCG4,\"releaseDate\":\"$(dd -1)T00:00:00\",\"note\":\"نامه بانک\"}"
nomsg "r1a2 review m-3: a release call cannot confirm the cancellation request: the refusal names the pending action" "درخواست «ابطال» منتظر تأیید است"
as "$COM_TOKEN" POST $PC/guarantees/withdraw "$WDBODY"; check "r1a2 review m-3: the one who asked takes the cancellation request back; the slot is free again" '.success and .data.releaseRequestedKind == null and .data.releaseRequestOpen == false and (.message|contains("درخواست ابطال پس گرفته شد"))'
# request the release, try to confirm it as a cancellation (refused), then confirm it as a release with another date and another note
as "$COM_TOKEN" POST $PC/guarantees/release "{\"guaranteeId\":$PCG4,\"releaseDate\":\"${M3D}T00:00:00\",\"note\":\"$M3N\"}"; check "r1a2 review m-3: the release is requested again" '.success and .data.status == 3 and .data.releaseRequestedKind == 1'
as "$FM_TOKEN" POST $PC/guarantees/events "{\"guaranteeId\":$PCG4,\"kind\":3,\"eventDate\":\"$(dd 0)T00:00:00\",\"note\":\"نامه بانک\"}"; nomsg "r1a2 review m-3: the cancellation of the finance manager is refused again, naming the pending release" "درخواست «آزادسازی» منتظر تأیید است"
as "$FM_TOKEN" POST $PC/guarantees/release "{\"guaranteeId\":$PCG4,\"releaseDate\":\"$(dd 0)T00:00:00\",\"note\":\"تأیید مالی\"}"
check "r1a2 review m-3: the finance manager confirms the release with another date and another note: the guarantee is released on the DATE and with the NOTE OF THE REQUEST, the note of the confirming person follows it, and the answer says that the date was replaced" ".success and .data.status == 6 and ([.data.events[]|select(.kind == 4)]|length) == 1 and ([.data.events[]|select(.kind == 4)][0].eventDate|startswith(\"$M3D\")) and ([.data.events[]|select(.kind == 4)][0].note == \"$M3N | تأییدکننده: تأیید مالی\") and (.message|contains(\"تاریخ واردشده با تاریخ درخواست یکی نبود\"))"
as "$COM_TOKEN" GET "$PC/guarantees?ContractId=$PCT&PageSize=0"
check "r1a2 review m-3: the register shows PC-G-4 released with no request open, and PC-G-1 untouched (active)" '.success and ([.data.data[]|select(.no=="PC-G-4")][0]|(.status == 6 and .releaseRequestOpen == false)) and ([.data.data[]|select(.no=="PC-G-1")][0].status == 3)'

call POST Contracts '{"code":"PC-CT-P","title":"قرارداد آزمون جریمه","status":1,"employer":"کارفرمای آزمون"}'; PCP=$(val .data.id)
as "$PLAN_TOKEN" POST $PC/terms "{\"contractId\":$PCP,\"currencyCode\":\"IRR\",\"valueExVat\":1000000000,\"latePenaltyPercentPerWeek\":1,\"penaltyCapPercent\":10,\"graceDays\":0,\"contractDeliveryDate\":\"$(dd -14)T00:00:00\",\"dataDateWeekday\":3,\"clientReviewDays\":14,\"autoSnapshot\":false}"; check "pc: penalty contract terms saved" '.success'
as "$COM_TOKEN" POST $PC/penalties/compute/$PCP; check "pc: late penalty 14 days x 1 percent per week of 1bn = 20,000,000" '.success and (.data|length) == 1 and .data[0].lateDays == 14 and .data[0].amount == 20000000 and .data[0].baseAmount == 1000000000'
PCPEN=$(val '.data[0].id')
as "$COM_TOKEN" POST $PC/penalties/decide "{\"id\":$PCPEN,\"status\":1,\"reason\":\"بخشودگی\"}"; no "pc: only the CEO waives a penalty"
as "$CEO_TOKEN" POST $PC/penalties/decide "{\"id\":$PCPEN,\"status\":1,\"reason\":\"بخشودگی به دلیل تاخیر کارفرما\"}"; check "pc: CEO waives the penalty -> amount 0" '.success and .data.status == 1 and .data.amount == 0'
as "$COM_TOKEN" POST $PC/penalties/compute/$PCP; check "pc: a decided penalty is not recomputed" '.success and .data[0].amount == 0 and .data[0].status == 1'

# --- shipping gate: packing needs a released quality release note (the single record is the Quality one)
as "$WH_TOKEN" POST $PC/shipments "{\"contractId\":$QCT,\"workOrderId\":$WO2,\"packingList\":\"1 crate\"}"; check "pc: shipment planned for the unreleased work order" '.success and .data.status == 0 and (.data.number|startswith("SH"))'
PCSH2=$(val .data.id)
as "$WH_TOKEN" POST $PC/shipments/action "{\"id\":$PCSH2,\"action\":\"pack\",\"packingVerification\":\"checked\"}"; nomsg "pc: packing without a released release note is blocked" "بدون برگه ترخیص"
as "$WH_TOKEN" POST $PC/shipments "{\"contractId\":$QCT,\"workOrderId\":$WO1,\"packingList\":\"2 crates\"}"; PCSH1=$(val .data.id)
as "$WH_TOKEN" POST $PC/shipments/action "{\"id\":$PCSH1,\"action\":\"pack\"}"; no "pc: packing needs the verification result"
as "$WH_TOKEN" POST $PC/shipments/action "{\"id\":$PCSH1,\"action\":\"pack\",\"packingVerification\":\"matches the packing list\"}"; check "pc: released work order packed; release note linked" ".success and .data.status == 1 and .data.releaseNoteId == $RN1"
as "$WH_TOKEN" POST $PC/shipments/action "{\"id\":$PCSH1,\"action\":\"release\"}"; no "pc: shipping release belongs to planning"
as "$PLAN_TOKEN" POST $PC/shipments/action "{\"id\":$PCSH1,\"action\":\"release\"}"; check "pc: planning releases the shipment" '.success and .data.status == 2'
as "$WH_TOKEN" POST $PC/shipments/action "{\"id\":$PCSH1,\"action\":\"ship\",\"waybill\":\"WB-100\",\"shippingDocuments\":\"packing list, CoC\"}"; check "pc: shipped" '.success and .data.status == 3'
as "$PLAN_TOKEN" POST $PC/shipments/action "{\"id\":$PCSH1,\"action\":\"deliver\",\"deliveryReceiptNumber\":\"DR-1\"}"; check "pc: delivered" '.success and .data.status == 4 and .data.deliveredAt != null'
as "$PLAN_TOKEN" POST $PC/shipments/action "{\"id\":$PCSH1,\"action\":\"handover\",\"handoverMinutesNumber\":\"HM-1\"}"; check "pc: handover minutes recorded" '.success and .data.status == 5'

# --- reports: client report has no indices unless the contract says so; MS Project export; final book
as "$PLAN_TOKEN" POST $PC/reports/generate "{\"contractId\":$PCT,\"kind\":1}"
check "pc: client monthly report carries progress but no SPI/CPI" '.success and (.data.hash|length) > 10 and (.data.content|fromjson|(.physicalPercent // .PhysicalPercent)) != null and ((.data.content|fromjson|(.spi // .Spi)) == null) and ((.data.content|fromjson|(.cpi // .Cpi)) == null)'
PCREP=$(val .data.id)
as "$PM_TOKEN" POST $PC/reports/$PCREP/release; check "pc: project manager releases the client report" '.success and .data.releasedAt != null'
as "$PLAN_TOKEN" POST $PC/terms "$(echo "$PCTERMS" | jq -c '.clientReportShowsIndices = true')"; check "pc: contract allows indices in the client report" '.success and .data.clientReportShowsIndices == true'
as "$PLAN_TOKEN" POST $PC/reports/generate "{\"contractId\":$PCT,\"kind\":1,\"dataDate\":\"2026-11-06T00:00:00\"}"; check "pc: client report shows SPI/CPI only when the contract allows it" '(.data.content|fromjson|(.spi // .Spi)) != null'
as "$PLAN_TOKEN" POST $PC/terms "$PCTERMS" >/dev/null
as "$PLAN_TOKEN" POST $PC/reports/generate "{\"contractId\":$PCT,\"kind\":2}"; check "pc: internal weekly report generated" '.success and .data.kind == 2'
as "$PLAN_TOKEN" POST $PC/reports/generate "{\"contractId\":$PCT,\"kind\":3}"; check "pc: CEO monthly report generated" '.success and .data.kind == 3'
as "$PM_TOKEN" GET "$PC/reports?ContractId=$PCT"; check "pc: reports are listed (paged)" '.success and (.data.data|length) >= 3'
as "$PLAN_TOKEN" POST $PC/reports/generate "{\"contractId\":$PCT,\"kind\":4}"; no "pc: final book is not a periodic report"

PCMSP=$(curl -s -o "$OUT/pc-msp.tmp" -w '%{http_code} %{content_type}' "$API/$PC/export/msproject/$PCT" -H "Authorization: Bearer $PLAN_TOKEN")
if [ "${PCMSP%% *}" = "200" ] && echo "$PCMSP" | grep -qi "xml" && grep -q "<Project" "$OUT/pc-msp.tmp" && [ "$(grep -o '<Task>' "$OUT/pc-msp.tmp" | wc -l)" -eq 5 ] && python3 -I -c 'import sys,xml.dom.minidom as m; m.parse(sys.argv[1])' "$OUT/pc-msp.tmp" 2>/dev/null; then ok "pc: MS Project XML export is well-formed with 5 tasks (project + 4)"; else echo "$PCMSP" > "$B"; head -c 600 "$OUT/pc-msp.tmp" >> "$B"; bad "pc: MS Project XML export is well-formed with 5 tasks (project + 4)"; fi
rm -f "$OUT/pc-msp.tmp"

as "$DCC_TOKEN" POST $PC/final-books "{\"workOrderId\":$PCW1,\"variant\":\"client\"}"; no "pc: final book of an incomplete data book is refused"
as "$DCC_TOKEN" POST $PC/final-books "{\"workOrderId\":$PCW1,\"variant\":\"client\",\"allowIncomplete\":true}"; check "pc: incomplete final book by DCC refused (PMO only)" '.success == false'
call POST $PC/final-books "{\"workOrderId\":$PCW1,\"variant\":\"client\",\"allowIncomplete\":true}"; check "pc: final book (client variant) issued as controlled document R01 with a hash" '.success and .data.revision == "R01" and (.data.hash|length) > 10 and .data.controlledDocumentId != null and (.data.documentCode|endswith("-L"))'
call POST $PC/final-books "{\"workOrderId\":$PCW1,\"variant\":\"client\",\"allowIncomplete\":true}"; check "pc: re-issue makes revision R02" '.success and .data.revision == "R02"'
as "$DCC_TOKEN" GET "$PC/final-books?WorkOrderId=$PCW1"; check "pc: final books listed" '.success and (.data.data|length) == 2'

# --- second contract: WBS generation from the work order, plan run, cycle checks (new and legacy predecessors)
call POST Contracts '{"code":"PC-CT-02","title":"قرارداد آزمون WBS","status":1,"employer":"کارفرمای آزمون"}'; PCT2=$(val .data.id)
call POST ContractEquipments "{\"contractId\":$PCT2,\"equipmentId\":$PEQ,\"count\":1}"
call POST WorkOrders "{\"contractId\":$PCT2,\"equipmentId\":$PEQ,\"code\":\"PC-WO-3\",\"title\":\"Pump 3\",\"description\":\"x\",\"count\":1}"; PCW3=$(val .data.id)
as "$PLAN_TOKEN" POST $PC/terms "{\"contractId\":$PCT2,\"currencyCode\":\"IRR\",\"valueExVat\":500000000,\"calendarId\":$PCCAL,\"dataDateWeekday\":3,\"scheduleStartDate\":\"2026-11-02T00:00:00\",\"clientReviewDays\":14,\"autoSnapshot\":false}"; check "pc: second contract terms" '.success'
as "$PLAN_TOKEN" POST $PC/work-order-info "{\"workOrderId\":$PCW3,\"contractId\":$PCT2,\"typeCode\":\"PU\",\"sizeCode\":\"150\",\"optionCode\":\"25\"}"; check "pc: second equipment code PU1502501 (unique across contracts)" '.success and .data.equipmentProjectCode == "PU1502501"'
as "$PLAN_TOKEN" POST $PC/wbs/generate "{\"contractId\":$PCT2,\"workOrderIds\":[$PCW3]}"
check "pc: WBS generated from the work order: 4 nodes, 6 activities, 5 dependencies, 12 MDR lines" '.success and .data.nodesCreated == 4 and .data.activitiesCreated == 6 and .data.dependenciesCreated == 5 and .data.mdrLinesDrafted == 12'
as "$PLAN_TOKEN" POST $PC/wbs/generate "{\"contractId\":$PCT2,\"workOrderIds\":[$PCW3]}"; check "pc: generating again creates nothing twice" '(.success == false) or (.data.nodesCreated == 0 and .data.activitiesCreated == 0)'
as "$PLAN_TOKEN" GET "$PC/wbs?ContractId=$PCT2&PageSize=0"; check "pc: generated WBS nodes are listed" '.success and (.data.data|length) == 4'
as "$PLAN_TOKEN" POST $PC/cpm/run "{\"contractId\":$PCT2,\"forecast\":false,\"mirror\":true}"
check "pc: generated plan: MDR 10 + MDL 10 + packing 2 = 22 working days, ends 2026-12-01" '.success and .data.hasCycle == false and .data.projectFinishOffset == 22 and (.data.projectFinish|startswith("2026-12-01"))'
as "$PLAN_TOKEN" GET "$PC/activities?ContractId=$PCT2&PageSize=0"
PCMDRACT=$(jq -r '[.data.data[]|select(.title|contains("MDR"))|select(.title|contains("MDL")|not)][0].id' "$B"); PCDELACT=$(jq -r '[.data.data[]|select(.title|contains("تحویل به کارفرما"))][0].id' "$B")
as "$PLAN_TOKEN" POST $PC/dependencies "{\"contractId\":$PCT2,\"predecessorId\":$PCDELACT,\"successorId\":$PCMDRACT,\"type\":1,\"lagDays\":0}"; no "pc: cycle delivered -> MDR rejected"
as "$PLAN_TOKEN" POST $PC/wbs/auto-weights/$PCT2
as "$PLAN_TOKEN" GET "$PC/need-by?ContractId=$PCT2&PageSize=0"; check "pc: need-by dates listing" '.success'
as "$PLAN_TOKEN" GET "$PC/notices?WorkOrderId=$PCW3&PageSize=0"; check "pc: inspection notice listing" '.success'

# legacy assembly predecessors now run the same cycle detection
call POST Assemblies "{\"title\":\"Casing\",\"code\":\"PC-ASM-1\",\"workOrderId\":$PCW3,\"assemblerDuration\":1}"; PCAS1=$(jq -r '.data.id // empty' "$B")
call POST Assemblies "{\"title\":\"Rotor\",\"code\":\"PC-ASM-2\",\"workOrderId\":$PCW3,\"assemblerDuration\":1}"; PCAS2=$(jq -r '.data.id // empty' "$B")
[ -n "$PCAS1" ] && [ -n "$PCAS2" ] && ok "pc: two legacy assemblies created" || bad "pc: two legacy assemblies created"
call PUT Assemblies/set-predecessor "{\"id\":$PCAS2,\"predecessorId\":$PCAS1}"; check "pc: legacy assembly predecessor 1 -> 2 accepted" '.success'
call PUT Assemblies/set-predecessor "{\"id\":$PCAS1,\"predecessorId\":$PCAS2}"; no "pc: legacy assembly loop 2 -> 1 rejected"
call PUT Assemblies/set-predecessor "{\"id\":$PCAS1,\"predecessorId\":$PCAS1}"; no "pc: legacy assembly self link rejected"

# --- dashboards
as "$PM_TOKEN" GET $PC/dashboard; check "pc: PMO dashboard: active projects, red projects, late activities, guarantee alerts, exposure" '.success and .data.activeProjects >= 2 and .data.guaranteeAlerts >= 1 and .data.openChangeRequests >= 0 and (.data.worst|length) >= 1'
as "$CEO_TOKEN" GET "$PC/portfolio?PageSize=0"; check "pc: portfolio has one row for the main contract" ".success and ([.data.data[]|select(.contractId == $PCT)]|length) == 1"
as "$CEO_TOKEN" GET finance/ceo-dashboard
check "pc: CEO dashboard carries the project control counts" '.success and .data.pcActiveProjects >= 2 and .data.pcGuaranteeAlerts >= 1 and (.data.pcPenaltyExposure != null) and (.data.pcOverdueClientResponses >= 1)'
as "$SEC_TOKEN" GET $PC/dashboard; [ "$CODE" = "403" ] && ok "pc: security user cannot open the PMO dashboard (403)" || bad "pc: security user cannot open the PMO dashboard (403) got $CODE"
TOKEN=$ADMIN_TOKEN

# ---------------------------------------------------------------- finance: general ledger, treasury, receivables, tax (release F1)
TOKEN=$ADMIN_TOKEN
FG=finance/gl; FT=finance/treasury; FR=finance/receivables; FX=finance/tax
[ -n "$FIN2_TOKEN" ] && [ -n "$FM_TOKEN" ] && [ -n "$PAYR_TOKEN" ] && [ -n "$TR_TOKEN" ] && ok "finance: login second accountant, finance manager (17), payroll (18) and treasury (19) users" || bad "finance: login second accountant, finance manager (17), payroll (18) and treasury (19) users"
TODAY=$(date +%Y-%m-%d)
ADMINID=$(uid "$ADMIN_TOKEN")

# --- fiscal years on the Persian calendar
as "$FM_TOKEN" POST $FG/years/ensure '{"date":"2026-03-21T00:00:00"}'
check "finance: fiscal year 1405 has 12 periods" '.success and .data.year == 1405 and (.data.periods|length) == 12'
check "finance: 1405-01-01 is 2026-03-21, 1405-07-01 is 2026-09-23 and the year ends 2027-03-20" '(.data.startDate|startswith("2026-03-21")) and (.data.periods[6].startDate|startswith("2026-09-23")) and (.data.endDate|startswith("2027-03-20"))'
check "finance: first six periods have 31 days, the next five 30 days" '([.data.periods[0:6][]|((.endDate[0:10]|strptime("%Y-%m-%d")|mktime) - (.startDate[0:10]|strptime("%Y-%m-%d")|mktime))/86400]|all(. == 30)) and ([.data.periods[6:11][]|((.endDate[0:10]|strptime("%Y-%m-%d")|mktime) - (.startDate[0:10]|strptime("%Y-%m-%d")|mktime))/86400]|all(. == 29))'
FY=$(val .data.id)
as "$FM_TOKEN" POST $FG/years/ensure "{\"date\":\"${TODAY}T00:00:00\"}"; check "finance: the year of today exists" '.success and .data.id > 0'
FYT=$(val .data.id)
as "$PAYR_TOKEN" POST $FG/years/ensure '{"date":"2026-03-21T00:00:00"}'; no "finance: payroll user cannot manage fiscal years"
as "$COM_TOKEN" GET $FG/years; [ "$CODE" = "403" ] && ok "finance: commercial user cannot read the ledger (403)" || bad "finance: commercial user cannot read the ledger (403) got $CODE"
as "$PAYR_TOKEN" GET finance/dashboard; [ "$CODE" = "403" ] && ok "finance: payroll user has no finance dashboard yet (403)" || bad "finance: payroll user has no finance dashboard yet (403) got $CODE"

# --- chart of accounts, set-up check (statutory values are not seeded)
as "$FM_TOKEN" GET "$FG/accounts?PageSize=0"; check "finance: chart of accounts seeded with groups, general and subsidiary levels" '.success and (.data.data|length) > 100 and ([.data.data[]|select(.code=="10301")]|length) == 1 and ([.data.data[]|select(.code=="10301")][0].requiresDetail) == true'
as "$FM_TOKEN" GET $FG/setup-check
check "finance: set-up check lists only the missing VAT rate" '.success and .data.ok == false and ([.data.problems[].code]|sort) == ["VAT_RATE_MISSING"]'
check "finance: seeded ratios are flagged for verification" '(.data.toVerify|length) >= 3'
as "$FM_TOKEN" GET "$FX/rates?PageSize=0"; check "finance: tax table has no VAT row and the seeded ratios carry source and verify flag" '.success and ([.data.data[]|select(.kind == 1)]|length) == 0 and ([.data.data[]|select(.verify == true and (.source|length) > 0)]|length) >= 3'

# --- manual vouchers: rules and segregation of duties
MV="{\"date\":\"${TODAY}T00:00:00\",\"description\":\"سند آزمون دستی\",\"lines\":[{\"accountCode\":\"80108\",\"debit\":1000000},{\"accountCode\":\"10101\",\"credit\":1000000}]}"
as "$FIN_TOKEN" POST $FG/vouchers "{\"date\":\"${TODAY}T00:00:00\",\"lines\":[{\"accountCode\":\"80108\",\"debit\":1000},{\"accountCode\":\"10101\",\"credit\":900}]}"; no "finance: unbalanced voucher rejected"
as "$FIN_TOKEN" POST $FG/vouchers "{\"date\":\"${TODAY}T00:00:00\",\"lines\":[{\"accountCode\":\"801\",\"debit\":1000},{\"accountCode\":\"10101\",\"credit\":1000}]}"; no "finance: vouchers post to subsidiary accounts only"
as "$FIN_TOKEN" POST $FG/vouchers "{\"date\":\"${TODAY}T00:00:00\",\"lines\":[{\"accountCode\":\"10301\",\"debit\":1000},{\"accountCode\":\"10101\",\"credit\":1000}]}"; no "finance: account with a mandatory detail needs it in a manual voucher"
as "$FIN_TOKEN" POST $FG/vouchers "{\"date\":\"${TODAY}T00:00:00\",\"lines\":[{\"accountCode\":\"80108\",\"debit\":1000,\"credit\":1000},{\"accountCode\":\"10101\",\"credit\":0}]}"; no "finance: a line has either debit or credit"
as "$COM_TOKEN" POST $FG/vouchers "$MV"; no "finance: commercial user cannot write vouchers"
as "$FIN_TOKEN" POST $FG/vouchers "$MV"; check "finance: manual voucher saved as draft" '.success and .data.status == 0 and .data.type == 2 and .data.totalAmount == 1000000 and .data.number == null'
V1=$(val .data.id)
as "$FIN_TOKEN" POST $FG/vouchers/action "{\"id\":$V1,\"action\":\"check\"}"; no "finance: preparer cannot check own voucher"
as "$FIN2_TOKEN" POST $FG/vouchers/action "{\"id\":$V1,\"action\":\"check\"}"; check "finance: second accountant checks the voucher" '.success and .data.status == 1'
as "$FIN2_TOKEN" POST $FG/vouchers/action "{\"id\":$V1,\"action\":\"finalize\"}"; no "finance: only the finance manager finalizes"
as "$FM_TOKEN" POST $FG/vouchers/action "{\"id\":$V1,\"action\":\"finalize\"}"; check "finance: finance manager finalizes: number 1" '.success and .data.status == 2 and .data.number == 1'
as "$FIN_TOKEN" POST $FG/vouchers "$(jq -c ". + {id:$V1}" <<< "$MV")"; no "finance: a final voucher cannot be edited"
as "$FIN_TOKEN" DELETE "$FG/vouchers/$V1"; no "finance: a final voucher cannot be deleted"
as "$FM_TOKEN" POST $FG/vouchers "$MV"; V2=$(val .data.id)
as "$FIN2_TOKEN" POST $FG/vouchers/action "{\"id\":$V2,\"action\":\"check\"}"
as "$FM_TOKEN" POST $FG/vouchers/action "{\"id\":$V2,\"action\":\"finalize\"}"; no "finance: the preparer cannot finalize his own voucher"
as "$FIN2_TOKEN" POST $FG/vouchers/action "{\"id\":$V2,\"action\":\"uncheck\"}"; check "finance: a checked voucher goes back to draft" '.success and .data.status == 0'
as "$FM_TOKEN" DELETE "$FG/vouchers/$V2"; check "finance: a draft voucher is deleted" '.success'
as "$FIN_TOKEN" POST $FG/vouchers/action "{\"id\":$V1,\"action\":\"reverse\",\"note\":\"آزمون\"}"; check "finance: reversal of a final voucher is a new draft with swapped lines" '.success and .data.type == 5 and .data.status == 0 and .data.reversesVoucherId == '"$V1"' and ([.data.lines[]|select(.accountCode=="10101")][0].debit) == 1000000'
V1R=$(val .data.id)
as "$FIN_TOKEN" POST $FG/vouchers/action "{\"id\":$V1,\"action\":\"reverse\"}"; no "finance: a voucher is reversed only once"
as "$FIN2_TOKEN" POST $FG/vouchers/action "{\"id\":$V1R,\"action\":\"check\"}"; as "$FM_TOKEN" POST $FG/vouchers/action "{\"id\":$V1R,\"action\":\"finalize\"}"; check "finance: reversal voucher finalized: number 2" '.success and .data.number == 2'

# --- period lock, late posting of events into the next open period
as "$FM_TOKEN" GET $FG/years; PERIOD7=$(jq -r --argjson y "$FY" '.data[]|select(.id == $y)|.periods[]|select(.startDate[0:10] <= "2026-10-15" and .endDate[0:10] >= "2026-10-15")|.id' "$B")
as "$FM_TOKEN" POST $FG/periods/action "{\"id\":$PERIOD7,\"action\":\"lock\"}"; check "finance: period of 2026-10-15 locked" '.success'
as "$FIN_TOKEN" POST $FG/vouchers "$(jq -c '.date = "2026-10-15T00:00:00"' <<< "$MV")"; no "finance: a voucher in a locked period is rejected"
as "$FM_TOKEN" POST $FG/periods/action "{\"id\":$PERIOD7,\"action\":\"reopen\"}"; no "finance: reopening a period needs a reason"

# --- events into vouchers
as "$FM_TOKEN" POST $FG/post-events; check "finance: pending events turned into auto vouchers (some late: their period is locked)" '.success and .data.posted > 5 and .data.failed == 0 and .data.latePosted >= 1'
as "$FM_TOKEN" POST $FG/post-events; check "finance: posting events is idempotent" '.success and .data.posted == 0'
as "$FM_TOKEN" GET "finance/events?PageSize=0"; check "finance: every event is posted (or not required)" '[.data.data[]|select(.status != 4 and .status != 9)]|length == 0'
as "$FM_TOKEN" GET "$FG/vouchers?FiscalYearId=$FY&Type=3&PageSize=0"; check "finance: auto vouchers are checked and flagged as late posting where needed" '.success and (.data.data|length) > 5 and ([.data.data[]|select(.status != 1)]|length) == 0 and ([.data.data[]|select(.latePosting == true)]|length) >= 1'
as "$FM_TOKEN" POST $FG/periods/action "{\"id\":$PERIOD7,\"action\":\"reopen\",\"reason\":\"آزمون بازگشایی\"}"; check "finance: period reopened with a reason" '.success'
as "$FM_TOKEN" POST $FG/vouchers/finalize-up-to "{\"fiscalYearId\":$FY,\"upTo\":\"$(dd 400)T00:00:00\"}"; check "finance: bulk finalize numbers the auto vouchers one after the other" '.success and .data.finalized > 5 and .data.firstNumber == 3 and (.data.lastNumber - .data.firstNumber + 1) == .data.finalized'
as "$FM_TOKEN" GET "$FG/vouchers?FiscalYearId=$FY&Status=2&PageSize=0"; check "finance: final voucher numbers are gapless" '([.data.data[].number]|sort) as $n | ($n|length) > 5 and $n == [range(1; ($n|length)+1)]'
as "$FM_TOKEN" GET "$FG/reports/trial-balance?FiscalYearId=$FY&Level=2&Columns=6"; check "finance: trial balance of final vouchers balances" '.success and .data.balanced == true and .data.totalDebit == .data.totalCredit and .data.totalDebit > 0 and .data.includesDraft == false'
as "$FM_TOKEN" GET "$FG/reports/reconciliation"; check "finance: ledger equals the item cost sub-ledger" '.success and ([.data.rows[]|select(.key == "inventory")][0].ok) == true'
check "finance: goods received not invoiced equals the open receipts" '([.data.rows[]|select(.key == "grni")][0].ok) == true'
check "finance: payables per supplier equal approved invoices minus paid requests" '([.data.rows[]|select(.key == "ap")][0].ok) == true'
check "finance: no unposted events remain" '.data.unpostedEvents == 0'
as "$FM_TOKEN" GET "$FG/reports/balance-sheet?FiscalYearId=$FY"; check "finance: balance sheet balances" '.success and .data.balanced == true'
as "$FM_TOKEN" GET "$FG/reports/income-statement?FiscalYearId=$FY"; check "finance: income statement returned" '.success and (.data.lines|length) > 0'
as "$FM_TOKEN" GET "$FG/reports/journal?FiscalYearId=$FY&PageSize=5"; check "finance: journal is paged by day" '.success and (.data.data|length) <= 5 and .data.totalItems > 0'
CODE=$(curl -s -o "$B" -w '%{http_code}' "$API/$FG/reports/export/trial-balance?FiscalYearId=$FY" -H "Authorization: Bearer $FM_TOKEN")
[ "$CODE" = "200" ] && [ "$(head -c 3 "$B" | od -An -tx1 | tr -d ' \n')" = "efbbbf" ] && ok "finance: trial balance exports as UTF-8 CSV with BOM" || bad "finance: trial balance exports as UTF-8 CSV with BOM ($CODE)"

# --- treasury masters
as "$FIN_TOKEN" POST $FT/bank-accounts '{"title":"x","iban":"IR270170000000100324200001"}'; no "finance: only treasury creates bank accounts"
as "$TR_TOKEN" POST $FT/bank-accounts '{"title":"بانک آزمون","iban":"IR000000000000000000000000"}'; no "finance: IBAN with a wrong check digit rejected"
as "$TR_TOKEN" POST $FT/bank-accounts '{"title":"بانک الف - جاری","bankName":"ملی","branch":"مرکزی","accountNumber":"100324200001","iban":"IR270170000000100324200001"}'; check "finance: bank account saved on account 10102" '.success and .data.accountCode == "10102"'
BA1=$(val .data.id)
as "$TR_TOKEN" POST $FT/bank-accounts '{"title":"بانک ب - جاری","bankName":"صادرات","accountNumber":"200000000003","iban":"IR950190000000200000000003"}'; BA2=$(val .data.id)
as "$TR_TOKEN" POST $FT/bank-accounts '{"title":"تکراری","iban":"IR270170000000100324200001"}'; no "finance: the same IBAN cannot be registered twice"
as "$TR_TOKEN" POST $FT/cash-boxes '{"title":"صندوق مرکزی","custodianTitle":"خزانه‌دار"}'; check "finance: cash box saved" '.success and .data.id > 0'
CB=$(val .data.id)
as "$TR_TOKEN" POST $FT/cheque-books "{\"bankAccountId\":$BA1,\"series\":\"A\",\"fromSerial\":501,\"toSerial\":510}"; check "finance: cheque book with 10 blank leaves" '.success and .data.leaves == 10 and .data.blank == 10'
CBK=$(val .data.id)
as "$TR_TOKEN" POST $FT/cheque-books "{\"bankAccountId\":$BA1,\"series\":\"A\",\"fromSerial\":505,\"toSerial\":515}"; no "finance: overlapping cheque book rejected"
