Y4=$(val .data.id); P1=$(val '.data.periods[0].id'); P2=$(val '.data.periods[1].id'); P3=$(val '.data.periods[2].id'); P4=$(val '.data.periods[3].id'); P5=$(val '.data.periods[4].id'); P6=$(val '.data.periods[5].id')

