OR7='{"deviceCode":"GATE-1","rows":[{"code":"ATT02","date":"2026-08-04","time":"13:55"},{"code":"ATT02","date":"2026-08-05","time":"00:30"},{"code":"ATT03","date":"2026-08-04","time":"22:00"},{"code":"ATT03","date":"2026-08-05","time":"10:00"}]}'
