as "$CEO_TOKEN" GET "finance/events?Contains=MLM-140506&IncludeNotRequired=true&PageSize=10"; check "mes B: the CEO reads it too" ".success and (.data.data|length) == 1 and (.data.data[0].labourHidden == false and .data.data[0].amount == $MBPV2ABS)"
as "$FIN_TOKEN" GET "finance/costs"; check "mes B: the accountant reads the cost report: the protected variance of 1405/06 is a row of its own (no work order, no contract, no cost centre) that hides labour and total, and it is the only hidden row; the published variance of 1405/05 stays a readable row of the same kind" ".success and ([.data[]|select(.labourHidden == true)]|length) == 1 and ([.data[]|select(.workOrderId == null and .contractId == null and .costCenter == null and .labourHidden == true)][0] | .labour == null and .total == null) and ([.data[]|select(.workOrderId == null and .contractId == null and .costCenter == null and .labourHidden == false)]|length) == 1 and ([.data[]|select(.workOrderId == null and .contractId == null and .costCenter == null and .labourHidden == false)][0] | .labour == $MBPVAR and .total == $MBPVAR)"
as "$FM_TOKEN" GET "finance/costs"; check "mes B: the finance manager reads both rows with their amounts: the variance of 1405/05 and that of the protected 1405/06, nothing hidden" ".success and ([.data[]|select(.labourHidden == true)]|length) == 0 and ([.data[]|select(.workOrderId == null and .contractId == null and .costCenter == null)]|length) == 2 and ([.data[]|select(.workOrderId == null and .contractId == null and .costCenter == null)|.labour]|sort) == ([$MBPVAR, $MBPV2]|sort) and ([.data[]|select(.workOrderId == null and .contractId == null and .costCenter == null)|.total]|sort) == ([$MBPVAR, $MBPV2]|sort)"
as "$FIN_TOKEN" POST finance/events/export '{"markExported":false}'; check "mes B: the accountant cannot export the waiting events to Sepidar while the protected labour event is among them: the refusal names the period 1405/06 and the roles that may export it" '.success == false and (.message|contains("1405/06")) and (.message|contains("مدیر مالی"))'
as "$FM_TOKEN" POST finance/events/export '{"markExported":false}'; { [ "$CODE" = "200" ] && [ "$(grep 'MLM-140506' "$B" | grep -c ",${MBPV2ABS},0,")" = "1" ] && [ "$(grep 'MLM-140506' "$B" | grep -c ",0,${MBPV2ABS},")" = "1" ]; } 2>/dev/null && ok "mes B: the finance manager exports the same events: the voucher file carries the protected true-up of 1405/06 with its two lines and the exact amount" || bad "mes B: the finance manager exports the same events: the voucher file carries the protected true-up of 1405/06 with its two lines and the exact amount ($CODE)"

