as "$ADMIN_TOKEN" POST $AI/admin/endpoints "{\"id\":$AIEP1,\"name\":\"chat primary\",\"kind\":1,\"url\":\"http://127.0.0.1:5091\",$AIBODY_BASE}"; check "ai: primary endpoint enabled again" '.success and .data.enabled == true'
