  [ "$AIQCOUT" = "notes=0" ] && break
done
[ "$AIQCOUT" = "notes=0" ] && ok "ai qc: the seat ran until no open NCR was left without a note" || bad "ai qc: the seat ran until no open NCR was left without a note (last outputs '$AIQCOUT')"
