as "$FM_TOKEN" GET "$AI/notes?TargetType=FinanceJournal&TargetId=$AIFV4&Rule=ROUND&PageSize=0"; check "ai fin: the control voucher has no round-amount note" '.success and (.data.data|length) == 0'
