# the latest Friday that lies in an open period (a locked period refuses the voucher; the next Friday back is tried)
AIFRI=""
for AIK in 0 7 14 21 28 35 42 49; do
  AIFD=$(date -d "$TODAY -$(( ($(date -d "$TODAY" +%u)+2)%7 + AIK )) days" +%F)
