CDRQ=$(val .data.id); CDRL1=$(val '.data.lines[0].id'); CDRL2=$(val '.data.lines[1].id'); CDRL3=$(val '.data.lines[2].id')
cdprreq; cdprdash; cdrill pr.requests_open "top=200"
