CDPO=$(val .data.id); CDPON=$(val .data.number); CDPOPN=$(val .data.providerName); CDPOL1=$(val '.data.lines[0].id'); CDPOL2=$(val '.data.lines[1].id'); CDPOL3=$(val '.data.lines[2].id')
